      for _, c in ipairs(cs) do login(c) end
      tickAll(40)
      local G = group(cs)
      G.mapLock, G.lockInside, G.deafInside = true, true, deaf
      zone({ cs[2], cs[3] }, "party", 36, "The Deadmines")
      tickAll(1)
      zone({ cs[1] }, "party", 36, "The Deadmines")
      tickAll(40)
      local dmg = { La = { [7] = 20000, [0] = 2000 }, Mo = { [0] = 9000, [5] = 6 }, Ny = { [2] = 7000, [0] = 500 } }
      for _, enc in ipairs({ 1230, 1236, 1238, 1234 }) do fight(G, 60, dmg, enc); tickAll(60) end
      for _, c in ipairs(cs) do assert(#c.rsent == 0 and #c.C.RunComm.results > 0, c.o.name .. ": tried inside, each 11 kept: " .. #c.C.RunComm.results) end
      zone({ cs[1] }, "none", 0)
      tickAll(30)
      zone({ cs[2], cs[3] }, "none", 0)
      tickAll(60)
      for _, c in ipairs(cs) do
        assert(not c.C.Runs.Current(), c.o.name .. " has no run left" .. (deaf and " (deaf inside)" or ""))
        assert(lastReport(c), c.o.name .. " has a report" .. (deaf and " (deaf inside)" or ""))
      end
      if not deaf then
        for _, c in ipairs(cs) do assert(lastReport(c).id == lastReport(cs[1]).id and cardsOf(lastReport(c)) == cardsOf(lastReport(cs[1])), c.o.name .. " shows the leader's report") end
      end
    end)
  end
  -- (and where the dungeon's map makes chat secret but lets the group's addon messages through: the hellos and the
  -- checkpoints go inside, the id settles there)
  isolated({ gmember("Ox", 1), gmember("Pe", 3), gmember("Qu", 3) }, function()
    local cs = { gchar("Ox", 1), gchar("Pe", 3), gchar("Qu", 3) }
    for _, c in ipairs(cs) do login(c) end
    tickAll(40)
    local G = group(cs)
    G.mapLock = true
    zone(cs, "party", 36, "The Deadmines")
    tickAll(40)
    assert(cs[2].env.C_ChatInfo.InChatMessagingLockdown(), "chat locked on the map")
    fight(G, 60, { Ox = { [0] = 1000 }, Pe = { [0] = 700 }, Qu = { [0] = 600 } }, 1230)
    tickAll(30)
    local ids, n = {}, 0
    for _, c in ipairs(cs) do local id = c.C.Runs.Current().id; if not ids[id] then ids[id] = true; n = n + 1 end end
    local m = cs[1].C.Runs.Current().members[sfx(cs[2])]
    assert(n == 1 and m and m.v and m.v.dm, "inside, one id and the checkpoints held: " .. n)
  end)
  said[#said + 1] = "a lockdown for the whole stay: tried inside and each 11 kept, the leader out first after a full clear ends every member's run with its report, heard inside or not; a map whose chat is secret but lets the group's messages through settles the id inside"

  -- (8) a raid of 40 (nine with Cute): five cards and up to ten mentions, no member twice; each client at most three
  -- messages at the end; a member joining late draws one hello's answer, two at most; a raidN outside your subgroup is
  -- never on another map
  do
    local roster, names = {}, {}
    local classes = { "WARRIOR", "MAGE", "PRIEST", "ROGUE", "HUNTER", "DRUID", "PALADIN", "WARLOCK", "SHAMAN" }
    for i = 1, 40 do names[i] = "Raider" .. string.char(64 + (i - 1) % 26 + 1) .. i; roster[i] = gmember(names[i], i == 1 and 1 or 3, classes[(i - 1) % 9 + 1]) end
    isolated(roster, function()
      local cs = {}
      for i = 1, 9 do cs[i] = gchar(names[i], i == 1 and 1 or 3, { class = classes[(i - 1) % 9 + 1] }); login(cs[i]) end
      tickAll(40)
      local list = {}
      for i = 1, 39 do list[i] = i <= 8 and cs[i] or { name = names[i], class = classes[(i - 1) % 9 + 1] } end
      local G = group(list, { raid = true })
      zone({ unpack(cs, 1, 8) }, "raid", 409, "Molten Core")
      for i = 6, 39 do G.map[guidOf(names[i])] = 2000 + i end
      tickAll(40)
      -- the late one: in the raid, then into the instance
      local late = cs[9]
      G.members[40] = entryOf(late)
      wire(late, G)
      for _, e in ipairs(G.members) do if e.c then e.c.everMet = e.c.everMet or {}; table.insert(e.c.everMet, G.members[40]); if e.c == late then for _, f in ipairs(G.members) do table.insert(late.everMet, f) end end end end
      for _, c2 in ipairs(clientsOf(G)) do fire(c2, "GROUP_ROSTER_UPDATE") end
      local marks = {}
      for i, c2 in ipairs(clientsOf(G)) do marks[i] = #c2.rsent end
      zone({ late }, "raid", 409, "Molten Core")
      tickAll(20)
      local answers = 0
      for i, c2 in ipairs(clientsOf(G)) do for k = marks[i] + 1, #c2.rsent do if c2.rsent[k].msg:match("^2H|.*%.a$") then answers = answers + 1 end end end
      assert(answers >= 1 and answers <= 2 and late.C.Runs.Current().id == cs[1].C.Runs.Current().id, "the late one answered once or twice and in the raid's run: " .. answers)
      local amounts = {}
      for i = 1, 40 do
        local a = { [0] = 1000 + i * 37 }
        if i % 5 == 0 then a[2] = 3000 + i * 11 end
        if i % 7 == 0 then a[5] = 3 + i % 6 end
        if i % 6 == 0 then a[6] = 4 + i % 9 end
        if i % 8 == 0 then a[8] = 500 + i * 13 end
        if i % 4 == 0 then a[7] = 2000 + i * 3 end
        amounts[names[i]] = a
      end
      for _, enc in ipairs({ 6601, 6602 }) do fight(G, 90, amounts, enc); tickAll(60) end
      for i = 10, 16 do for _ = 1, (i % 3) + 1 do die(G, names[i]); tickAll(2); rez(G, names[i]) end end
      tickAll(200)
      for _, m in pairs(cs[1].C.Runs.Current().members) do assert(not m.away, "nobody outside the subgroup taken for elsewhere") end
      for i, c2 in ipairs(clientsOf(G)) do marks[i] = #c2.rsent end
      zone(clientsOf(G), "none", 0)
      tickAll(25)
      for i, c2 in ipairs(clientsOf(G)) do assert(#c2.rsent - marks[i] <= 3, c2.o.name .. " sent more than three at the end: " .. rkinds(c2, marks[i] + 1)) end
      local rep = lastReport(cs[1])
      assert(rep and #rep.cards == 5 and #rep.mentions >= 1 and #rep.mentions <= 10, "five cards and the mentions: " .. cardsOf(rep) .. " / " .. #(rep and rep.mentions or {}))
      local seen = {}
      for _, x in ipairs(rep.cards) do assert(not seen[x[1]]); seen[x[1]] = true end
      for _, x in ipairs(rep.mentions) do assert(not seen[x[1]], "no member twice"); seen[x[1]] = true end
      assert(lastReport(cs[5]) and cardsOf(lastReport(cs[5])) == cardsOf(rep) and #lastReport(cs[5]).mentions == #rep.mentions, "the raid sees the scribe's")
      -- (the 2A carries no member count: the header's "members" is the client's own count, never its cards')
      assert(rep.n >= 30 and lastReport(cs[5]).n == rep.n, "the raid's members on the header, not its cards: " .. rep.n .. " / " .. lastReport(cs[5]).n)
      said[#said + 1] = string.format("a raid of 40: five cards and %d mentions, no member twice, three messages at most at the end, a late member answered %d time%s", #rep.mentions, answers, answers == 1 and "" or "s")
    end)
  end

  -- (5) pictures: SetUnit only on a unit in sight whose identity is plain, found in the order of 8.2 (a target and a
  -- nameplate included); without one the race model by display id (where the testers switched it on); else the icons,
  -- the race's portrait for a known race and sex, the class icon alone where either is unknown or the portrait does not
  -- load; no reason line; your own card always a model
  isolated({ gmember("Ayla", 1), gmember("Bram", 3), gmember("Cira", 3), gmember("Dorn", 3), gmember("Esk", 3) }, function()
    local c = gchar("Ayla", 1, { race = "Dwarf", sex = 3 })
    login(c)
    tickAll(40)
    local G = group({ c, { name = "Bram", class = "WARRIOR", race = "Orc", sex = 2 }, { name = "Cira", class = "PRIEST", race = "Human", sex = 3 }, { name = "Dorn", class = "HUNTER", race = "Troll", sex = 2 } })
    G.hidden[guidOf("Cira")] = true
    G.secretId[guidOf("Dorn")] = true
    local Cd = c.C.Cards
    assert(Cd.Find(c.o.guid) == "player" and Cd.Find(guidOf("Bram")) == "party1", "the player, then the party")
    assert(Cd.Find(guidOf("Cira")) == nil and Cd.Find(guidOf("Dorn")) == nil, "out of sight, or of secret identity: no unit")
    -- (a guild mate out of the group, as the target, then on a nameplate)
    G.members[#G.members + 1] = { name = "Esk", guid = guidOf("Esk"), class = "MAGE", race = "Gnome", sex = 2 }
    G.raid = false
    c.units.target = nil
    table.remove(G.members)
    G.extra = { name = "Esk", guid = guidOf("Esk"), class = "MAGE", race = "Gnome", sex = 2 }
    local holder = c.C.UI.frame or UIParent
    local card = Cd.Make(c.env.UIParent)
    local function fill(name, class, race, sex, guid) Cd.Fill(card, { guid = guid or guidOf(name), name = name, class = class, race = race, sex = sex, kind = "star", label = "GOLD STAR", title = "T", line = "L", value = "1", valueLabel = "x" }) end
    fill("Bram", "WARRIOR", "Orc", 2)
    assert(card.drew == "model" and card.model.__unit == "party1" and card.model:IsShown(), "a member in sight: their model by SetUnit")
    fill("Ayla", "MAGE", "Dwarf", 3, c.o.guid)
    assert(card.drew == "model" and card.model.__unit == "player", "your own card: always a model")
    fill("Cira", "PRIEST", "Human", 3)
    assert(card.drew == "icons" and card.portrait:IsShown() and card.portrait.__tex == 236447 and card.classIcon.__tex == 626004 and card.classIcon.__w == 32,
      "out of sight: the class colour, Human female's portrait and the priest's icon at its corner")
    c.env.CuteDB.settings.raceModel = true
    fill("Dorn", "HUNTER", "Troll", 2)
    assert(card.drew == "race" and card.model.__display == 59071 and card.model:IsShown(), "the race model where the testers switched it on: Troll male's display")
    c.env.CuteDB.settings.raceModel = nil
    fill("Esk", "MAGE", "Gnome", nil)
    assert(card.drew == "icons" and not card.portrait:IsShown() and card.classIcon.__w == 72, "the sex unknown: the class icon alone, large")
    rawset(card.portrait, "SetTexture", function() return false end)
    fill("Cira", "PRIEST", "Human", 3)
    assert(card.drew == "icons" and not card.portrait:IsShown() and card.classIcon.__w == 72, "a portrait that does not load: the class icon alone")
    rawset(card.portrait, "SetTexture", nil)
    for _, fs in ipairs({ card.name, card.title, card.line, card.value, card.valueLabel, card.label }) do
      assert(not fs:GetText():lower():find("range") and not fs:GetText():lower():find("sight"), "no reason line on a card")
    end
    -- (a guild mate out of the group is found as the target, then on a nameplate once the target is cleared, in 8.2's
    -- order, and drawn by SetUnit there; nowhere, no unit)
    c.units.target = guidOf("Esk")
    assert(Cd.Find(guidOf("Esk")) == "target", "a guild mate out of the group as the target: " .. tostring(Cd.Find(guidOf("Esk"))))
    fill("Esk", "MAGE", "Gnome", 2)
    assert(card.drew == "model" and card.model.__unit == "target", "the target's model by SetUnit: " .. tostring(card.drew) .. " " .. tostring(card.model.__unit))
    c.units.target, c.units.nameplate7 = nil, guidOf("Esk")
    assert(Cd.Find(guidOf("Esk")) == "nameplate7", "then on a nameplate: " .. tostring(Cd.Find(guidOf("Esk"))))
    c.units.nameplate7 = nil
    assert(Cd.Find(guidOf("Esk")) == nil, "nowhere: no unit")
  end)
  said[#said + 1] = "pictures: SetUnit only in sight and plain, your own card a model, the race model by display id where switched on, the portrait and class icon, the class icon alone where race, sex or the file fails"

  -- (11) chat lines, (18) the card screen and the Runs tab laid out: Send to party at most 255 bytes a line, only in the
  -- click, greyed in an encounter, in the chat lockdown, without a group and with the policy in doubt; another member's
  -- 2P shows who posted and leaves the button live; Print to chat sends nothing; Warm Feet never on the party line;
  -- the posting lines never counted as typed; CuteCardFrame in report, raid (662 high) and test mode, with and without
  -- a cover, the Runs tab with rows and empty, Settings > Runs, at J's default and minimum sizes
  isolated({ gmember("Fen", 1), gmember("Gus", 3), gmember("Hob", 3) }, function()
    local cs = { gchar("Fen", 1, { class = "WARRIOR", race = "Human" }), gchar("Gus", 3, { class = "PRIEST", race = "Dwarf", sex = 3 }), gchar("Hob", 3, { class = "ROGUE", race = "Gnome" }) }
    for _, c in ipairs(cs) do login(c) end
    tickAll(40)
    -- the empty Runs tab: "No runs yet." and its button
    local gus = cs[2]
    gus.C.UI:Open("runs")
    assert(texts(gus):find("No runs yet.", 1, true), "the empty Runs tab says so")
    check(gus.C.UI.frame, "runs: the empty Runs tab")
    -- (the Guide's big band row hides the pooled band line's own text, Guide.lua bandRow: the Runs tab drawn after it
    -- shows its line all the same)
    gus.C.UI.bandLines.items[1].name:Hide()
    gus.C.UI:Draw()
    assert(texts(gus):find("No runs yet.", 1, true), "the Runs tab's band line after the Guide drew the band")
    -- the tab open while a run starts: drawn again on its own, its clock running
    local G = group(cs)
    zone(cs, "party", 36, "The Deadmines")
    tickAll(40)
    assert(texts(gus):find("Now: The Deadmines", 1, true), "the band: the run on now, drawn as it started")
    local function bandText() local l = bandLine(gus, 1); return l and l.name:IsShown() and l.name:GetText() or "" end
    local b1 = bandText()
    tickAll(3)
    assert(bandText() ~= b1 and bandText():find("^Now: The Deadmines"), "the band's clock runs: " .. b1 .. " / " .. bandText())
    gus.C.UI:Open("runs")
    check(gus.C.UI.frame, "runs: the Runs tab with a run on")
    local dmg = { Fen = { [7] = 30000, [0] = 2000 }, Gus = { [2] = 9000, [6] = 7 }, Hob = { [0] = 9000, [5] = 6, [8] = 9000 } }
    for _, enc in ipairs({ 1230, 1236, 1238, 1234 }) do fight(G, 60, dmg, enc); tickAll(60) end
    zone(cs, "none", 0)
    tickAll(25)
    -- (the tab, still open, drew the report's row as it came)
    local drawn
    for _, r in ipairs(gus.C.UI.lists.runs.items) do if r:IsShown() and r.name:GetText() == "The Deadmines" then drawn = true end end
    assert(drawn and not texts(gus):find("Now: The Deadmines", 1, true), "the open tab drew the report's row and dropped the band's run")
    local CF = gus.C.CardFrame
    assert(CF.frame and CF.frame:IsShown() and CF.rep and CF.rep.from == "scribe", "the report on the screen")
    local h = CF.frame:GetHeight()
    assert(h == 560 and CF.frame:GetWidth() == gus.C.CardFrame.Width(#CF.rep.cards), "the report's size: " .. h)
    check(CF.frame, "runs: the report, no cover")
    -- Send to party's states
    local function state() local ok, why = CF.SendState(CF.rep); return ok and "live" or why end
    gus.encounter = true; assert(state() == "After the fight", "greyed in an encounter: " .. state()); gus.encounter = false
    gus.chatLocked = true; assert(state() == "Outside the instance", "greyed in the chat lockdown"); gus.chatLocked = false
    gus.C.Policy.doubt = true; assert(state() == "Waiting for Guild Info", "greyed while the policy is in doubt"); gus.C.Policy.doubt = nil
    local keep = gus.group; gus.group = nil; assert(state() == "Not in a group", "greyed without a group"); gus.group = keep
    assert(state() == "live", "live otherwise")
    -- (the button follows the game while the screen shows, no combat event needed; a refused click says why at once)
    CF:DrawSend()
    gus.chatLocked = true; tickAll(2)
    assert(CF.sendButton.label:GetText() == "Outside the instance" and not CF.sendButton:IsEnabled(), "greyed on its own as the lockdown comes: " .. CF.sendButton.label:GetText())
    gus.chatLocked = false; tickAll(2)
    assert(CF.sendButton.label:GetText() == "Send to party" and CF.sendButton:IsEnabled(), "live again on its own: " .. CF.sendButton.label:GetText())
    gus.encounter = true
    local refused = #gus.chatOut
    press(CF.sendButton)
    assert(#gus.chatOut == refused and CF.sendButton.label:GetText() == "After the fight", "a refused click posts nothing and says why: " .. CF.sendButton.label:GetText())
    gus.encounter = false
    -- the click: every line in it, on PARTY, at most 255 bytes, nothing the font cannot draw but names; the lines never
    -- counted as typed; then Sent, and the others see who posted
    local typed = 0
    gus.C.Sample:OnChat(function() typed = typed + 1 end)
    local n0 = #gus.chatOut
    CF:DrawSend()
    press(CF.sendButton)
    local posted = {}
    for i = n0 + 1, #gus.chatOut do posted[#posted + 1] = gus.chatOut[i] end
    assert(#posted >= 2 and typed == 0, "lines posted, none counted as typed: " .. #posted .. ", " .. typed)
    for _, l in ipairs(posted) do
      assert(l.hw and l.kind == "PARTY" and #l.text <= 255 and not undrawable(l.text), "a line in the click, on PARTY, within 255 bytes: " .. l.text)
    end
    assert(posted[1].text:find("^Cute recap") and not table.concat((function() local t = {}; for _, l in ipairs(posted) do t[#t + 1] = l.text end return t end)(), "\n"):find("Warm Feet", 1, true), "the header first; Warm Feet never on the party line")
    assert(state() == "Sent", "Sent after the post")
    tickAll(3)
    local fen = cs[1].C.CardFrame
    assert(fen.frame:IsShown() and fen.posted:GetText() == "Gus posted" and fen.sendButton:IsEnabled(), "another member's 2P: who posted, the button live")
    -- (Warm Feet's line left out wherever it is on a card)
    local wf = cs[1].C.Awards.Text({ place = "X", kind = "d", dur = 60, cards = { { "a", "WF", 9000 }, { "b", "FI", 4 } }, gone = {} }, function() return "Y" end)
    assert(#wf == 2 and not table.concat(wf):find("Warm Feet", 1, true), "Warm Feet off the party line")
    -- History: the Runs tab, the report's row; a click opens it again; right-click offers to delete it
    press(CF.buttons[2])
    assert(gus.C.UI.page == "runs" and not CF.frame:IsShown(), "History opens the Runs tab")
    local row
    for _, r in ipairs(gus.C.UI.lists.runs.items) do if r:IsShown() then row = r end end
    assert(row and row.name:GetText() == "The Deadmines", "the history's row: " .. tostring(row and row.name:GetText()))
    check(gus.C.UI.frame, "runs: the Runs tab, a report in the history")
    -- (a group run's row on the widget that drew the dungeon's atlas: the sprint icon whole, the atlas's crop reset,
    -- as Blizzard_CustomAuraButton.lua resets the texcoords between SetAtlas and SetTexture)
    local Rn = gus.C.Runs
    Rn.Keep({ id = "g-test", kind = "g", place = "Map 1429", start = lastReport(gus).start + 3600, dur = 1000, bosses = 0, known = 0, wipes = 0, deaths = 0,
      cards = {}, mentions = {}, gone = {}, members = {}, n = 2 })
    gus.C.UI:Draw()
    local grow
    for _, r in ipairs(gus.C.UI.lists.runs.items) do if r:IsShown() and r.icon.__tex == 132307 then grow = r end end
    local tc = grow and grow.icon.__tc
    assert(tc and tc[1] == 0 and tc[2] == 1 and tc[3] == 0 and tc[4] == 1, "the sprint icon whole on a row that drew an atlas: " .. tostring(tc and table.concat(tc, ",")))
    table.remove(Rn.DB().list, 1)
    gus.C.UI:Draw()
    gus.C.UI.frame:SetSize(760, 420)
    gus.C.UI:Draw()
    check(gus.C.UI.frame, "runs: the Runs tab, small")
    gus.C.UI.frame:SetSize(1040, 640)
    row.__scripts.OnClick(row, "LeftButton")
    assert(CF.frame:IsShown(), "a row's click opens its report")
    row.__scripts.OnClick(row, "RightButton")
    local menu = gus.menus[#gus.menus]
    assert(menu and menu[2] and menu[2].text == "Delete from history", "right-click: Delete from history")
    -- (Send to party is for the report of the run that just ended, to the group it ran with: an older one from the
    -- history, one half an hour old, or one of another group stays on this screen)
    local latest = lastReport(gus)
    local sentFor = Rn.sentFor
    Rn.sentFor = nil
    local function copy(t, extra) local o = {}; for k, v in pairs(t) do o[k] = v end; for k, v in pairs(extra) do o[k] = v end return o end
    local older = copy(latest, { id = "old-1" })
    table.insert(Rn.DB().list, 2, older)
    local function why(r) local ok, w = CF.SendState(r); return ok and "live" or w end
    assert(why(older) == "Earlier run", "an older report: " .. why(older))
    assert(why(copy(latest, { at = latest.at - 1900 })) == "Earlier run", "half an hour on: Earlier run")
    assert(why(copy(latest, { members = { ZZZZZZZZ = { n = "Zed" } } })) == "Not this group", "another group's: Not this group")
    assert(why(latest) == "live", "the run that just ended, live: " .. why(latest))
    table.remove(Rn.DB().list, 2)
    Rn.sentFor = sentFor
    -- (a closed field takes its awards off a report opened again from the history: the screen, the row's tooltip and
    -- the party line; the officers close Meter in runs a day later)
    local A = gus.C.Awards
    local meterTitles = {}
    for _, a in ipairs(A.LIST) do for _, code in ipairs(a.reads) do if code == "rm" then meterTitles[#meterTitles + 1] = a.title end end end
    local metered = false
    for _, x in ipairs(latest.cards) do for _, code in ipairs(A.BY[x[2]].reads) do if code == "rm" then metered = true end end end
    assert(metered, "the report had a meter card: " .. cardsOf(latest))
    local held = gus.env.CuteDB.policy
    gus.env.CuteDB.policy = { vis = { run_meter = "self" } }
    gus.C.UI:Draw()
    row.__scripts.OnClick(row, "LeftButton")
    for _, x in ipairs(CF.rep.cards) do for _, code in ipairs(A.BY[x[2]].reads) do assert(code ~= "rm", "a closed field's card on the screen: " .. cardsOf(CF.rep)) end end
    local tip = tipText(row.tip)
    local line = table.concat(A.Text(CF.rep, function() return "X" end), "\n")
    for _, t in ipairs(meterTitles) do
      assert(not tip:find(t, 1, true) and not line:find(t, 1, true), "a closed field's award in the row's tooltip or on the party line: " .. t)
    end
    gus.env.CuteDB.policy = held
    -- Settings > Runs
    gus.C.UI:Open("settings", "runs")
    assert(texts(gus):find("Show the report when a run ends", 1, true) and texts(gus):find("Long groups outside instances", 1, true), "Settings > Runs: its rows")
    check(gus.C.UI.frame, "runs: Settings > Runs")
    -- the cover where Cute_Quest gives one, through its own door (merge2 M6: the stand-in door this round had hid that
    -- none was there); without Cute_Quest the Dungeon atlas. And a raid's mentions
    CF:Report(CF.rep)
    assert(not CF.cover:IsShown() and CF.atlas:IsShown() and CF.title:GetText() == "The Deadmines", "no Cute_Quest: the Dungeon atlas, the place whole: " .. CF.title:GetText())
    local raid = gus.C.RunsUI.Test(true)
    assert(CF.frame:GetHeight() == 662 and #raid.mentions >= 5 and CF.label:GetText() == "TEST RECAP", "a raid's test: 662 high, the mentions: " .. CF.frame:GetHeight())
    check(CF.frame, "runs: a raid's test report")
    -- the test: Print to chat sends nothing; Next draws another set
    local sent0, chat0 = #gus.chatOut, #gus.chat
    local t1 = gus.C.RunsUI.Test(false)
    press(CF.buttons[3])
    assert(#gus.chatOut == sent0 and #gus.chat > chat0, "Print to chat: in your chat frame, nothing sent")
    press(CF.buttons[2])
    local t2 = CF.rep
    assert(t2 ~= t1 and cardsOf(t2) ~= cardsOf(t1), "Next: another set of awards")
    check(CF.frame, "runs: the test report")
    -- the slash words
    gus.env.SlashCmdList.CUTE("run test")
    assert(CF.frame:IsShown() and CF.rep.test, "/cute run test")
    gus.env.SlashCmdList.CUTE("run")
    assert(CF.rep.id == lastReport(gus).id, "/cute run: the last report")
    gus.C.Cards:Show(t1, "test")
    assert(CF.rep == t1 and CF.label:GetText() == "TEST RECAP", "Cards:Show, the design's interface")
    local d0 = #gus.chat
    gus.env.SlashCmdList.CUTE("diag runs")
    local diag = table.concat(gus.chat, "\n", d0 + 1)
    assert(diag:find("diag runs: no run on", 1, true) and diag:find("group channel: sent", 1, true) and not diag:find("Fen", 1, true), "/cute diag runs, no name:\n" .. diag)
    gus.env.SlashCmdList.CUTE("race")
    assert(gus.C.UI.page == "race", "the core's words still the core's")
  end)
  said[#said + 1] = "the card screen and the Runs tab: Send to party in the click, within 255 bytes, greyed in an encounter, the lockdown, no group, a policy in doubt, who posted shown and the button live, Print to chat sends nothing, Warm Feet off the line, the posting never typed; laid out with and without a cover, a raid's 662, the tab with rows and empty, Settings > Runs, J at both sizes; /cute run, run test, diag runs"

  -- the run stats and the run fields: in the registry for every client (Runs on or off), the fields under Runs in Who
  -- sees what, each lifetime count revealing its week; the stats bumped by this client's own build
  do
    local S, P = yezin.C.Stats, yezin.C.Policy
    for _, id in ipairs({ "runs", "runs_week", "honors", "honors_week", "roasts", "roasts_week" }) do assert(S.byId[id] and S.byId[id].cat == "runs", "the run stat " .. id) end
    assert(S.byId.runs.code == "ru" and S.byId.honors.code == "ho" and S.byId.roasts.code == "rx" and S.byCode.rm == "run_meter" and S.byCode.rl == "run_loot", "codes for life")
    for _, pair in ipairs({ { "runs", "runs_week" }, { "honors", "honors_week" }, { "roasts", "roasts_week" } }) do
      local saved = yezin.env.CuteDB.policy
      yezin.env.CuteDB.policy = { vis = { [pair[2]] = "self" } }
      assert(P:Route(pair[1]) == "self", pair[1] .. " goes its week's way")
      yezin.env.CuteDB.policy = saved
    end
    yezin.C.UI:Open("settings", "vis")
    assert(texts(yezin):find("Meter in runs", 1, true) and texts(yezin):find("Yards in runs", 1, true), "the run fields in Who sees what")
    assert(S.HIDDEN.sex and S.HIDDEN_ORDER[#S.HIDDEN_ORDER] == "sex", "sex rides beside the GUID")
  end
  said[#said + 1] = "the run stats and fields in the registry, Who sees what lists the fields, each count reveals its week"

  -- (19) memory: a raid run's saved state bounded (40 members, 16 quests each); the history at its cap; what the new
  -- stats add to a member's full record, counted
  do
    local function size(v, seen)
      seen = seen or {}
      if type(v) == "string" then return #v + 2 end
      if type(v) == "number" then return 8 end
      if type(v) ~= "table" or seen[v] then return 1 end
      seen[v] = true
      local n = 4
      for k, x in pairs(v) do n = n + size(k, seen) + size(x, seen) end
      return n
    end
    local Rn = yezin.C.Runs
    local run = { id = "x-1", kind = "r", inst = 409, start = 0, at = 0, seq = 0, members = {}, own = { q = {} }, bosses = {}, nb = 8, wipes = 0, dorder = 0,
      maps = {}, meter = { done = {}, tot = {} }, loot = {} }
    for i = 1, 16 do run.own.q[i] = 9000 + i end
    for i = 1, 40 do
      local g = string.format("Player-4242-0B%06X", i)
      local sx = g:match("([^%-]+)$")
      local v = { t = 9000, o = 0, de = 9, dt = 300, fd = 100, dm = 9999999, hl = 9999999, ab = 999999, tk = 9999999, av = 999999, ["in"] = 40, dp = 40, mt = 1,
        ch = 99, wy = 3, yd = 99999, ju = 999, cn = 30, lv = 1, gd = 999999, lq = 4, ln = 9, q = {} }
      for k = 1, 16 do v.q[k] = 9000 + k end
      run.members[sx] = { g = g, n = "Member" .. i, c = "MAGE", r = "Human", s = 2, first = 0, obs = { de = 9, fd = 100, dt = 300 }, v = v, seq = 9, hello = "0.7.1" }
      run.meter.tot[sx] = { dm = 9999999, hl = 9999999, ab = 999999, tk = 9999999, av = 999999, ["in"] = 40, dp = 40, dd = 9 }
      run.loot[sx] = { hr = 99, lr = 1, nd = 4, wn = 2, lq = 4 }
    end
    for i = 1, 200 do run.meter.done[i] = true end
    local runBytes = size(run)
    assert(runBytes < 48 * 1024, "a raid run's saved state: " .. runBytes .. " bytes")
    local db = Rn.DB()
    local saved = { list = db.list, keep = db.keep }
    db.list, db.keep = {}, 50
    for i = 1, 60 do
      local rep = { id = "h" .. i, kind = "d", place = "The Deadmines", start = i, dur = 2500, bosses = 5, known = 5, wipes = 1, deaths = 7, n = 5, members = {}, cards = {}, mentions = {}, gone = {} }
      for k = 1, 5 do local sx = string.format("0C%06X", k); rep.members[sx] = { n = "Member" .. k, c = "MAGE", r = "Human", s = 2, g = "Player-4242-" .. sx }; rep.cards[k] = { sx, "HD", 38, "star" } end
      Rn.Keep(rep)
    end
    local histBytes = size(db.list)
    assert(#db.list == 50 and histBytes < 50 * 1000, "the history at its cap, under a kilobyte a report: " .. #db.list .. ", " .. histBytes)
    db.list, db.keep = saved.list, saved.keep
    local M = yezin.C.Comm
    local added = 0
    for _, id in ipairs({ "runs", "runs_week", "honors", "honors_week", "roasts", "roasts_week", "sex" }) do
      local v = id == "sex" and 3 or 1234
      added = added + #id + 2 + #M.Encode(yezin.C.Stats.byId[id], v)
    end
    assert(added <= 150, "the new stats add at most 150 bytes to a full record: " .. added)
    said[#said + 1] = string.format("memory: a raid run's saved state %d KB, the history of 50 %d KB, the new stats %d bytes of a full record", math.floor(runBytes / 1024 + 0.5), math.floor(histBytes / 1024 + 0.5), added)
  end

  -- (4.1, 4.4) what each client counts of its own (quests, gold looted, a level, the lines typed and "where are you",
  -- jumps, consumables, yards, items received) and what the loot history gives every client (rolls, need rolls, wins):
  -- the 2V carries the own keys; the loot history's awards reach the report
  isolated({ gmember("Ivo", 1), gmember("Jem", 3), gmember("Kip", 3), gmember("Lor", 3) }, function()
    local cs = { gchar("Ivo", 1), gchar("Jem", 3) }
    for _, c in ipairs(cs) do login(c) end
    tickAll(40)
    local G = group({ cs[1], cs[2], { name = "Kip", class = "ROGUE" }, { name = "Lor", class = "HUNTER" } })
    zone(cs, "party", 36, "The Deadmines")
    tickAll(40)
    local jem = cs[2]
    local r = jem.C.Runs.Current()
    fire(jem, "QUEST_TURNED_IN", 214, 500, 300)
    jem.o.money = jem.o.money + 300; fire(jem, "PLAYER_MONEY")
    jem.o.money = jem.o.money + 750; fire(jem, "PLAYER_MONEY")
    fire(jem, "MERCHANT_SHOW"); jem.o.money = jem.o.money + 99; fire(jem, "PLAYER_MONEY"); fire(jem, "MERCHANT_CLOSED")
    fire(jem, "PLAYER_LEVEL_UP", 31)
    jem.env.C_ChatInfo.SendChatMessage("where are you", "PARTY")
    jem.env.C_ChatInfo.SendChatMessage("pull now", "PARTY")
    jem.env.JumpOrAscendStart(); jem.env.JumpOrAscendStart()
    fire(jem, "BAG_UPDATE_DELAYED"); tickAll(2)
    jem.o.bags[0][1].count = 3
    fire(jem, "BAG_UPDATE_DELAYED"); tickAll(2)
    jem.speed = 7
    tickAll(10)
    jem.speed = 0
    fire(jem, "CHAT_MSG_LOOT", "You receive loot: |cff0070dd|Hitem:30002:0|h[Item]|h|r.", "", "", "", "", "", 0, 0, "", 0, 0, jem.o.guid)
    fire(jem, "CHAT_MSG_LOOT", "Kip receives loot: |cff0070dd|Hitem:30005:0|h[Item]|h|r.", "", "", "", "", "", 0, 0, "", 0, 0, guidOf("Kip"))
    local v = jem.C.Runs:OwnValues()
    assert(v.q and v.q[1] == 214 and v.gd == 750 and v.lv == 1 and v.ch == 2 and v.wy == 1 and v.ju == 2 and v.cn == 2,
      "the own counts: quests " .. tostring(v.q and #v.q) .. ", gold " .. tostring(v.gd) .. ", level " .. tostring(v.lv) .. ", lines " .. tostring(v.ch) .. ", where " .. tostring(v.wy) .. ", jumps " .. tostring(v.ju) .. ", consumables " .. tostring(v.cn))
    assert(v.yd and v.yd >= 56 and v.yd <= 84 and v.lq == 3 and v.ln == 1, "yards " .. tostring(v.yd) .. ", items " .. tostring(v.ln) .. " of quality " .. tostring(v.lq))
    -- (the loot history: one boss's drops, its rolls on the loot history's own clock)
    local t0 = jem.clock + 77777
    fight(G, 60, nil, 1230)
    local function roll(name, n, state) return { playerName = name, playerGUID = guidOf(name), playerClass = "MAGE", isSelf = false, state = state or 3, roll = n } end
    G.lootInfos = { { encounterName = "Boss", encounterID = 1230, startTime = t0 + 60, duration = 60 } }
    G.lootDrops[1230] = {}
    for k = 1, 5 do
      local d = { lootListKey = k, itemHyperlink = "|cff0070dd|Hitem:" .. (k == 5 and 30002 or (30001 + 3 * k)) .. ":0|h[Item]|h|r", playerRollState = 3, startTime = t0 + 60, duration = 60,
        rollInfos = { roll("Lor", 40 + k, 0), roll("Kip", k == 1 and 1 or 30, 3), roll("Jem", k == 2 and 100 or 50, 3), roll("Ivo", 20, 3) } }
      d.winner = k == 5 and roll("Ivo", 99, 3) or roll("Lor", 45, 0)
      G.lootDrops[1230][k] = d
    end
    tickAll(40)
    jem.C.Runs:ReadLoot()
    local loot = jem.C.Runs.Current().loot
    assert(loot[sfx("Jem")].hr == 100 and loot[sfx("Kip")].lr == 1 and loot[sfx("Lor")].nd == 5 and loot[sfx("Ivo")].wn == 1 and loot[sfx("Ivo")].lq == 3,
      "the loot history: Jem's hundred, Kip's one, Lor's five need rolls, Ivo's rare")
    for _, enc in ipairs({ 1236, 1238, 1234 }) do fight(G, 60, nil, enc); tickAll(40) end
    tickAll(200)
    zone(cs, "none", 0)
    tickAll(25)
    local rep = lastReport(jem)
    assert(holderOf(rep, "FH") == sfx("Jem") and holderOf(rep, "BD") == sfx("Kip") and holderOf(rep, "NA") == sfx("Lor") and holderOf(rep, "LB") == sfx("Ivo"),
      "the loot history's awards: " .. cardsOf(rep))
  end)
  -- (and the 2V carries the own keys in a group all of the guild)
  isolated({ gmember("Mio", 1), gmember("Ned", 3) }, function()
    local cs = { gchar("Mio", 1), gchar("Ned", 3) }
    for _, c in ipairs(cs) do login(c) end
    tickAll(40)
    local G = group(cs)
    zone(cs, "party", 36, "The Deadmines")
    tickAll(40)
    local ned = cs[2]
    fire(ned, "QUEST_TURNED_IN", 166, 0, 0)
    ned.env.JumpOrAscendStart()
    ned.env.C_ChatInfo.SendChatMessage("where r u", "PARTY")
    ned.o.money = ned.o.money + 100; fire(ned, "PLAYER_MONEY")
    die(G, ned); tickAll(3); rez(G, ned)
    fight(G, 30, { Ned = { [0] = 500 } }, 1230)
    tickAll(40)
    local keys = keysSent(ned)
    for _, k in ipairs({ "t", "o", "de", "fd", "dm", "mt", "q", "ch", "wy", "ju", "gd" }) do assert(keys[k], "the 2V carries " .. k) end
    local mio = cs[1].C.Runs.Current().members[sfx(ned)]
    assert(mio.v.q[1] == 166 and mio.v.ju == 1 and mio.v.de == 1 and mio.v.dm == 500, "the scribe holds Ned's values")
  end)
  said[#said + 1] = "the own counts (quests, gold looted less a quest's reward and not at a merchant, a level, lines and where, jumps, consumables, yards, items) in the 2V, and the loot history's rolls, needs and wins on the cards"

  -- (12) the choice, on tables alone (Awards.lua makes no client call): a member { sfx, guid, name, v }
  do
    local A = yezin.C.Awards
    assert(A and A.Pick, "Awards.lua loads")
    local function mem(name, v, order)
      local g = guidOf(name)
      return { sfx = g:match("([^%-]+)$"), guid = g, name = name, v = v, order = order }
    end
    local ALL = function() return true end
    local function codes(cards) local out = {}; for _, c in ipairs(cards) do out[#out + 1] = c[2] end return table.concat(out, " ") end
    local function holder(cards, code) for _, c in ipairs(cards) do if c[2] == code then return c[1] end end end
    -- the 26: codes for life, two capital letters, none twice; seven GOLD STAR, nine SHOUT-OUT, eight BLOOPER, two
    -- THANKS; every quip at most 56 characters
    local kinds, seen = {}, {}
    for _, a in ipairs(A.LIST) do
      assert(a.code:match("^%u%u$") and not seen[a.code], "a code for life: " .. a.code)
      seen[a.code] = true
      kinds[a.kind] = (kinds[a.kind] or 0) + 1
      assert(#a.quip <= 56 and #a.title <= 24 and not (a.quip .. a.title):find("[\128-\255]"), "a quip at most 56 characters: " .. a.code)
    end
    assert(#A.LIST == 26 and kinds.star == 7 and kinds.shout == 9 and kinds.blooper == 8 and kinds.thanks == 2, "26 awards: " .. #A.LIST)
    -- every key a 2V carries has its bounds and (but the run's clock) its policy code
    for _, k in ipairs(A.ORDER) do
      assert(A.KEYS[k] and (A.KEYS[k].list or (A.KEYS[k].lo and A.KEYS[k].hi)), "bounds for " .. k)
      assert(k == "t" or k == "o" or A.CodeOf(k), "a policy code for " .. k)
    end
    -- each award reachable: a fixture where one member meets it and four do nothing much
    local base = function() return { t = 1800, de = 1, dt = 20, dm = 100, hl = 100, ab = 0, tk = 100, av = 10, ["in"] = 0, dp = 0, ch = 0, wy = 0, yd = 500, ju = 0, cn = 0, lv = 0, gd = 0 } end
    local FIX12 = {
      HD = { dm = 5000 }, LF = { hl = 5000 }, OS = { ["in"] = 9 }, CW = { dp = 7 }, IW = { tk = 9000, de = 0 }, BW = { ab = 900 },
      TJ = { dm = 900, hl = 200 }, NS = { de = 0, tk = 400 }, PW = { q = { 11, 12, 13, 14 } }, LB = { lq = 4, ln = 2 }, FH = { hr = 100 },
      TB = { yd = 2400 }, NR = { ch = 30 }, DG = { lv = 1 }, CM = { gd = 5000 }, WL = { cn = 6 }, FI = { de = 6 }, OA = { fd = 60 },
      SP = { dt = 400 }, WF = { av = 900 }, LO = { wy = 2 }, PG = { ju = 250 }, NA = { nd = 5 }, BD = { lr = 2 } }
    for code, extra in pairs(FIX12) do
      local ms = {}
      for i, name in ipairs({ "Ana", "Bo", "Cy", "Dee", "Eli" }) do
        local v = base()
        if i == 1 then for k, x in pairs(extra) do v[k] = x end end
        if code == "PW" and i == 2 then v.q = { 11, 12, 13 } end
        if code == "PW" and i == 3 then v.q = { 14 } end
        if code == "NS" then v.de = (i == 1) and 0 or 2; if i == 2 then v.tk = 900 end end
        if code == "TJ" and i == 2 then v.hl, v.dm = 400, 1000 end
        ms[i] = mem(name, v)
      end
      local cards, mentions = A.Pick(ms, { n = 5, bosses = 3, runId = "k1-0A000001" }, ALL)
      local found = holder(cards, code) or holder(mentions, code)
      assert(found == ms[1].sfx, code .. " reachable from its fixture: " .. codes(cards))
    end
    -- THANKS for a member with nothing: Steady Hands where their deaths are at most the median, else Good Company
    do
      local ms = { mem("Ana", { t = 900, de = 0, dm = 9000, hl = 0 }), mem("Bo", { t = 900, de = 0, hl = 9000, dm = 0 }), mem("Cy", { t = 900, de = 0 }) }
      local cards = A.Pick(ms, { n = 3, bosses = 1, runId = "x" }, ALL)
      assert(#cards == 3 and holder(cards, "SH") == ms[3].sfx, "a member with nothing gets Steady Hands: " .. codes(cards))
      ms[3].v.de = 4
      cards = A.Pick(ms, { n = 3, bosses = 1, runId = "x" }, ALL)
      assert(holder(cards, "GC") == ms[3].sfx or holder(cards, "FI") == ms[3].sfx, "deaths above the median: Good Company, or a blooper: " .. codes(cards))
      -- (two with nothing: Steady Hands to the first by GUID, so the next gets Good Company)
      local four = { ms[1], ms[2], mem("Cy2", { t = 900, de = 0 }), mem("Dee", { t = 900, de = 0 }) }
      local a3, a4 = four[3], four[4]
      if a4.guid < a3.guid then a3, a4 = a4, a3 end
      cards = A.Pick(four, { n = 4, bosses = 1, runId = "x" }, ALL)
      assert(holder(cards, "SH") == a3.sfx and holder(cards, "GC") == a4.sfx, "Steady Hands taken, the next empty-handed member Good Company: " .. codes(cards))
    end
    -- thresholds at their edges: Off Switch at 5 (8 in a raid), Floor Inspector at 3, Pogo Stick at 100, Spectator at 180 s,
    -- Narrator at 15, a share at 1.25 fair shares
    local function gets(code, v, n)
      local ms = {}
      for i = 1, n or 5 do ms[i] = mem("Edge" .. i, (i == 1) and v or { t = 1800, de = 0 }) end
      local cards, mentions = A.Pick(ms, { n = n or 5, bosses = 2, runId = "e" }, ALL)
      return holder(cards, code) ~= nil or holder(mentions, code) ~= nil
    end
    assert(gets("OS", { ["in"] = 5, t = 1800 }) and not gets("OS", { ["in"] = 4, t = 1800 }), "Off Switch at 5")
    assert(gets("OS", { ["in"] = 8, t = 1800 }, 8) and not gets("OS", { ["in"] = 7, t = 1800 }, 8), "Off Switch at 8 in a raid")
    assert(gets("FI", { de = 3, t = 1800 }) and not gets("FI", { de = 2, t = 1800 }), "Floor Inspector at 3")
    assert(gets("PG", { ju = 100, t = 1800 }) and not gets("PG", { ju = 99, t = 1800 }), "Pogo Stick at 100")
    assert(gets("SP", { dt = 180, t = 1800 }) and not gets("SP", { dt = 179, t = 1800 }), "Spectator at 180 s")
    assert(gets("NR", { ch = 15, t = 1800 }) and not gets("NR", { ch = 14, t = 1800 }), "Narrator at 15")
    do
      -- (five members: a fair share is a fifth, 1.25 of it a quarter)
      local function hd(top)
        local ms = { mem("S1", { dm = top, t = 1800 }) }
        for i = 2, 5 do ms[i] = mem("S" .. i, { dm = (100 - top) / 4, t = 1800 }) end
        return holder(A.Pick(ms, { n = 5, bosses = 1, runId = "s" }, ALL), "HD") ~= nil
      end
      assert(hd(25) and not hd(24), "Headliner at 1.25 fair shares")
    end
    -- the headline a GOLD STAR where one is eligible, however a shout-out scores; no repeats; at most two bloopers, and
    -- one where any is eligible; none in a report of two
    do
      local ms = { mem("Ha", { t = 1800, de = 0, ["in"] = 5 }), mem("Hb", { t = 1800, de = 0, ch = 90 }), mem("Hc", { t = 1800, de = 9, dt = 900, ju = 900 }),
        mem("Hd", { t = 1800, de = 8, wy = 9, fd = 10 }), mem("He", { t = 1800, de = 7, cn = 30 }) }
      local cards = A.Pick(ms, { n = 5, bosses = 2, runId = "h" }, ALL)
      assert(A.BY[cards[1][2]].kind == "star", "the headline a GOLD STAR: " .. codes(cards))
      local mm, aa, bl = {}, {}, 0
      for _, c in ipairs(cards) do
        assert(not mm[c[1]] and not aa[c[2]], "no member and no award twice: " .. codes(cards))
        mm[c[1]], aa[c[2]] = true, true
        if A.BY[c[2]].kind == "blooper" then bl = bl + 1 end
      end
      assert(#cards == 5 and bl >= 1 and bl <= 2, "five cards, one or two bloopers: " .. codes(cards))
      local two = A.Pick({ ms[3], ms[4] }, { n = 2, bosses = 2, runId = "h" }, ALL)
      for _, c in ipairs(two) do assert(A.BY[c[2]].kind ~= "blooper", "no blooper in a report of two: " .. codes(two)) end
      assert(#two == 2, "two cards for two: " .. codes(two))
      -- (a group of five where the shout-outs score highest still gets its one blooper)
      local fun = { mem("Fa", { t = 1800, de = 0, ch = 200 }), mem("Fb", { t = 1800, de = 0, cn = 90 }), mem("Fc", { t = 1800, de = 0, gd = 99999 }),
        mem("Fd", { t = 1800, de = 0, lv = 2 }), mem("Fe", { t = 1800, de = 1, wy = 1 }) }
      local f = A.Pick(fun, { n = 5, bosses = 1, runId = "f" }, ALL)
      assert(holder(f, "LO") == fun[5].sfx, "the one blooper placed before the shout-outs fill the last card: " .. codes(f))
      -- (the blooper's holder also holds a higher shout-out: the blooper still placed, right after the headline)
      local busy = { mem("Ia", { t = 1800, de = 0, dm = 9000 }), mem("Ib", { t = 1800, de = 3, ch = 200 }), mem("Ic", { t = 1800, de = 0, cn = 90 }),
        mem("Id", { t = 1800, de = 0, gd = 99999 }), mem("Ie", { t = 1800, de = 0, lv = 1 }) }
      local b = A.Pick(busy, { n = 5, bosses = 1, runId = "b" }, ALL)
      local nb = 0
      for _, c in ipairs(b) do if A.BY[c[2]].kind == "blooper" then nb = nb + 1 end end
      assert(#b == 5 and nb == 1 and holder(b, "FI") == busy[2].sfx, "a report with something to tease has its blooper: " .. codes(b))
    end
    -- a repeat in the scribe's last two reports scores lower; ties fall by the run id; the same input the same cards
    do
      local ms = { mem("Ra", { t = 1800, de = 0, dm = 5000, hl = 0 }), mem("Rb", { t = 1800, de = 0, hl = 5000, dm = 0 }), mem("Rc", { t = 1800, de = 0 }) }
      local facts = { n = 3, bosses = 1, runId = "r1" }
      local c1 = A.Pick(ms, facts, ALL)
      local first = c1[1][2]
      local hist = { { cards = { { c1[1][1], first, 1 } } } }
      local c2 = A.Pick(ms, { n = 3, bosses = 1, runId = "r1", history = hist }, ALL)
      assert(c2[1][2] ~= first, "the headline given last time scores less: " .. codes(c1) .. " then " .. codes(c2))
      -- (two reports with the member since: the repeat no longer counts)
      local old = { { cards = { { c1[1][1], "GC", 1 } } }, { cards = { { c1[1][1], "GC", 1 } } }, { cards = { { c1[1][1], first, 1 } } } }
      assert(A.Pick(ms, { n = 3, bosses = 1, runId = "r1", history = old }, ALL)[1][2] == first, "a repeat older than two reports with them counts not")
      assert(codes(A.Pick(ms, facts, ALL)) == codes(c1), "the same input, the same cards")
      -- two equal pairs (Off Switch and Clean Sweep, the same strength): which leads falls by the run id
      local eq = { mem("Ta", { t = 1800, de = 0, ["in"] = 6 }), mem("Tb", { t = 1800, de = 0, dp = 6 }), mem("Tc", { t = 1800, de = 0 }) }
      local orders = {}
      for i = 1, 12 do orders[A.Pick(eq, { n = 3, bosses = 1, runId = "tie" .. i }, ALL)[1][2]] = true end
      assert(orders.OS and orders.CW, "ties fall by the run id")
    end
    -- a closed field takes its awards off: Meter in runs Only you leaves no meter award
    do
      local ms = { mem("Ma", { t = 1800, de = 0, dm = 9000, ["in"] = 20 }), mem("Mb", { t = 1800, de = 5 }), mem("Mc", { t = 1800, de = 0 }) }
      local cards = A.Pick(ms, { n = 3, bosses = 1, runId = "m" }, function(code) return code ~= "rm" end)
      for _, c in ipairs(cards) do for _, code in ipairs(A.BY[c[2]].reads) do assert(code ~= "rm", "no meter award with Meter in runs closed: " .. codes(cards)) end end
    end
    -- a raid: five cards, up to ten mentions, no member twice
    do
      local ms = {}
      local keys = { "dm", "hl", "in", "dp", "tk", "ab", "ch", "yd", "ju", "cn", "gd", "wy", "dt", "de", "lv", "av" }
      for i = 1, 20 do
        local v = { t = 3600, de = 0 }
        local k = keys[(i - 1) % #keys + 1]
        v[k] = ({ dm = 90000, hl = 80000, ["in"] = 30, dp = 30, tk = 99000, ab = 9000, ch = 60, yd = 9000, ju = 400, cn = 20, gd = 50000, wy = 5, dt = 900, de = 9, lv = 1, av = 9000 })[k]
        if k == "tk" then v.de = 0 end
        ms[i] = mem("Raid" .. i, v)
      end
      local cards, mentions = A.Pick(ms, { n = 20, bosses = 4, runId = "raid" }, ALL)
      local mm = {}
      for _, c in ipairs(cards) do assert(not mm[c[1]]); mm[c[1]] = true end
      for _, c in ipairs(mentions) do assert(not mm[c[1]], "a mention's member on no card"); mm[c[1]] = true end
      assert(#cards == 5 and #mentions >= 5 and #mentions <= 10, "a raid: five cards, mentions: " .. #cards .. ", " .. #mentions)
    end
  end
  said[#said + 1] = "the choice: 26 awards each reachable, thresholds at their edges, a GOLD STAR headline, one or two bloopers and none in two, repeats score less, ties by the run id, a closed field no award, a raid's mentions"

  print("runs: " .. table.concat(said, "; "))
  -- (merge2) the group kit for the later rounds' run scenarios: a guild member and their client, the group wired, a
  -- loading screen, a fight, the group messages a client sent, its last report
  CUTE_RUNS_KIT = { gmember = gmember, gchar = gchar, group = group, zone = zone, fight = fight, rcount = rcount, lastReport = lastReport, disband = disband }
end runsStage() end

-- [stage: windows] that stage's tests go right below this line
-- W1 (the windows round, sub-project A). The leaks Cute_Quest's copy of Sync had: guild sharing is off at every load
-- (a hand-set true is off again), so nothing goes to GUILD and nothing is taken from it (a guild mate's 1L corrected
-- XP numbers on one voice); in a raid the party sync says nothing (the Bridge's noRaidSync: a guild raid reached members
-- the officers routed those values away from). And the game's map opens by QuestBank's tested path, OpenWorldMap and
-- HideUIPanel, never ToggleWorldMap, and never in a fight
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1), member("Pim", 3) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(c); tickAll(5)
    c.C.Modules.Set("Cute_Quest", true); tick(c, 6)
    local QB, s = c.addons[2].private, c.env.CuteQuestDB.settings
    assert(QB.noRaidSync == true and s.share.guild == false, "the copy: no RAID sync, no guild sharing")
    -- a guild mate's XP reading on GUILD: taken from nothing; the party's still heard
    local recorded, record = 0, QB.Live.Record
    QB.Live.Record = function(...) recorded = recorded + 1; return record(...) end
    local f = QB.Sync.frame
    f.__scripts.OnEvent(f, "CHAT_MSG_ADDON", "QuestBank", "1L|33:450:5", "GUILD", "Pim-Forever")
    f.__scripts.OnEvent(f, "CHAT_MSG_ADDON", "QuestBank", "1S|5|100|A|WARRIOR|0|0|0|-1|0|0|6.1.1|0000000000", "GUILD", "Pim-Forever")
    assert(recorded == 0 and next(QB.Sync.members) == nil, "a guild 1L and 1S change nothing")
    f.__scripts.OnEvent(f, "CHAT_MSG_ADDON", "QuestBank", "1L|33:450:5", "PARTY", "Pim-Forever")
    assert(recorded == 1, "the party's 1L is still heard")
    QB.Live.Record = record
    -- a guild raid: no 1S, 1Q or 1R on RAID, from a broadcast or a roster change
    c.o.group = true
    local inRaid = c.env.IsInRaid
    c.env.IsInRaid = function() return true end
    for k = #c.outbox, 1, -1 do c.outbox[k] = nil end
    QB.Sync.lastStatus, QB.Sync.lastQuests = nil, nil
    QB.Sync:Broadcast(false)
    fire(c, "GROUP_ROSTER_UPDATE"); tick(c, 30)
    for _, m in ipairs(c.outbox) do assert(m[3] ~= "RAID" and m[3] ~= "GUILD", "nothing of the engine's on RAID or GUILD: " .. tostring(m[3]) .. " " .. tostring(m[2]):sub(1, 30)) end
    c.env.IsInRaid = function() return false end
    QB.Sync.lastStatus, QB.Sync.lastQuests = nil, nil
    QB.Sync:Broadcast(false); tick(c, 10)
    local party = 0
    for _, m in ipairs(c.outbox) do if m[3] == "PARTY" then party = party + 1 end end
    assert(party > 0, "a party still hears the sync: " .. party)
    c.env.IsInRaid, c.o.group = inRaid, nil
    -- the game's map: OpenWorldMap, never ToggleWorldMap; a second ask on your own map keeps it; not in a fight
    local toggled = 0
    local toggle = c.env.ToggleWorldMap
    c.env.ToggleWorldMap = function(...) toggled = toggled + 1; return toggle(...) end
    for k = #c.panelCalls, 1, -1 do c.panelCalls[k] = nil end
    assert(QB.UI.OpenMap() == true and c.map.shown and c.panelCalls[1] == "open", "opened by OpenWorldMap: " .. table.concat(c.panelCalls, ","))
    assert(QB.UI.OpenMap(true) == false and not c.map.shown and c.panelCalls[2] == "hide", "shut by HideUIPanel when asked to toggle")
    c.combat = true
    local n0 = #c.chat
    assert(QB.UI.OpenMap() == false and #c.panelCalls == 2 and #c.chat == n0 + 1, "in a fight: nothing called, one line said")
    c.combat = false
    assert(toggled == 0, "ToggleWorldMap never called")
    c.env.ToggleWorldMap = toggle
    -- a 0.7 save whose guild sharing was turned on by hand after the first run: off again at the next load
    s.share.guild = true
    local db, qdb = c.env.CuteDB, c.env.CuteQuestDB
    leave(c)
    local d = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    d.env.CuteQuestDB = qdb
    login(d, db); tickAll(6)
    if not d.addons[2].loaded then d.C.Modules.Set("Cute_Quest", true); tick(d, 6) end
    assert(d.env.CuteQuestDB.settings.share.guild == false, "guild sharing off again at the next load")
    leave(d)
    print("windows W1: nothing to or from GUILD under Cute (a hand-set true off again), no RAID sync in a raid, the party still heard; the game's map by OpenWorldMap and HideUIPanel, never in a fight")
  end)
end

-- W2 (sub-project A): Settings never cuts. 0.7 gave a choice's options 42 px ("On my route" showed "On my..."), notes one
-- line and rows 20 px. Now a choice measures each option and wraps them under its label, labels and notes wrap and their
-- row grows, rows are 22 px, and a cut label anywhere in Settings is a layout problem (the gate) for both views, every
-- section, at both sizes; a choice's ticked option clicked again stays ticked (Role, which may be none, clears)
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1), member("Pim", 3) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(c); tickAll(5)
    c.C.Modules.Set("Cute_Quest", true); tick(c, 6)
    for _, key in ipairs({ "Cute_Quest:route", "Cute_Quest:map", "Cute_Quest:journal", "Cute_Quest:gear", "Cute_Quest:camp" }) do c.C.Modules.Set(key, true) end
    tick(c, 1)
    local s = c.env.CuteQuestDB.settings
    local function row(label) return checkBox(c, function(cb) return cb.label and cb.label:GetText() == label end) end
    local cuts0 = #problems
    c.C.UI:Open("settings", "quests")
    for _, size in ipairs({ { 1040, 640 }, { 760, 420 } }) do
      sizeAll(c, size[1], size[2])
      c.C.UI:Open("settings", "quests")
      for _, opt in ipairs({ "Off", "On my route", "Worth taking" }) do
        local r = row(opt)
        assert(r and not r.label.cuteCut and r:GetWidth() >= textWidth(opt, 13) + 20, "Accept for me's '" .. opt .. "' whole at " .. size[1] .. ": " .. tostring(r and r.label:GetText()))
      end
      local step = row("Step frame")
      assert(step and step:GetHeight() == 22, "a check row is 22 px: " .. tostring(step and step:GetHeight()))
      for _, sec in ipairs(c.C.SettingsPage.Sections(true)) do
        c.C.UI:Open("settings", sec.id)
        check(sframe(c), string.format("W2 settings %s at %dx%d", sec.id, size[1], size[2]))
      end
    end
    -- a long note wraps and its row grows: Who sees what's line about Guild Info at the small size
    c.C.UI:Open("settings", "vis")
    local wrapped
    for _, o in everything() do
      if o.__kind == "FontString" and visible(o) and o.__wrap and o.__text:find("Only you: whispered to the officers online", 1, true) and o.__parent and o.__parent.__client == c then wrapped = o end
    end
    assert(wrapped and not wrapped.cuteCut, "the visibility note shown whole, wrapping")
    -- a choice's ticked option clicked again stays ticked; Role clears
    c.C.UI:Open("settings", "quests")
    assert(s.autoAccept == "off" and row("Off"):GetChecked(), "Accept for me: Off")
    click(row("Off"))
    assert(s.autoAccept == "off" and row("Off"):GetChecked(), "the ticked option clicked again: still Off, still ticked")
    click(row("On my route"))
    assert(s.autoAccept == "route" and row("On my route"):GetChecked() and not row("Off"):GetChecked(), "On my route chosen, the section drawn again")
    click(row("On my route")); click(row("Off"))
    c.C.UI:Open("settings", "general")
    click(row("Tank"))
    assert(c.C.Char().role == "Tank", "a role")
    click(row("Tank"))
    assert(c.C.Char().role == "" and not row("Tank"):GetChecked(), "Role, which may be none: cleared")
    sizeAll(c, 1040, 640)
    assert(#problems == cuts0, "no cut label in Settings: " .. tostring(problems[cuts0 + 1]))
    leave(c)
    print("windows W2: Settings never cuts: options measured and wrapped, labels and notes wrap, rows 22 px, the cut gate on every section at both sizes; a ticked option stays ticked, Role clears")
  end)
end

-- W3 (sub-project C): the windows. J (CuteFrame, the guild's pages and a module addon's that says no window), L
-- (CuteQuestFrame, Cute_Quest's tabs) and Settings (CuteSettingsFrame) from one builder: a 30 px header that drags the
-- window, its title, the cog opening the window's group in Settings, the close, the game's size grabber in the corner,
-- Esc closing each; a place and size kept per window. Settings' section list: rows 22 px and heads 20 px at any size,
-- every section of an officer with every module on listed, scrolled at 760 x 420 and unscrolled at Settings' own
-- 800 x 560 (the owner's call, merge3). The Statistics page's categories in
-- a column of their own; no leader at 0
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1), member("Pim", 3) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest", "Cute_Example" }, addonState = {}, quest = true, withStats = true }))
    login(c); tickAll(6)
    local M, UI = c.C.Modules, c.C.UI
    for _, key in ipairs({ "Cute_Quest:map", "Cute_Quest:journal", "Cute_Quest:gear", "Cute_Quest:camp", "Cute_Example" }) do M.Set(key, true) end
    tick(c, 1)
    -- J, with a module addon's page among the guild's tabs (the registration API as it was)
    UI:Open("race")
    assert(c.env.CuteFrame == UI.frame and UI.head:GetHeight() == 30 and UI.title:GetText() == "Guild", "J: CuteFrame, a 30 px header titled Guild")
    assert(tabsShown(c) == "race prog shame game officers me example", "J's tabs, the module addon's after the guild's: " .. tabsShown(c))
    c.env.Cute.Open("example")
    assert(UI.page == "example" and UI.frame:IsShown(), "Cute.Open opens a module addon's page in J")
    -- L
    UI:Open("quests")
    local L = qwin(c)
    assert(c.env.CuteQuestFrame == L.frame and L.head:GetHeight() == 30 and L.title:GetText() == "Quests", "L: CuteQuestFrame titled Quests")
    -- the cogs: J's opens Settings at General, L's at Quests; each window's close; Esc closes each
    press(UI.cog)
    local S = UI.Window("settings")
    assert(S.frame:IsShown() and S.section == "general", "J's cog: Settings at General")
    press(L.cog)
    assert(S.section == "quests", "L's cog: Settings at Quests")
    for _, name in ipairs({ "CuteFrame", "CuteQuestFrame", "CuteSettingsFrame" }) do
      local found = false
      for _, n in ipairs(c.env.UISpecialFrames) do if n == name then found = true end end
      assert(found, name .. ": Esc closes it")
    end
    assert(S.frame:GetWidth() == 800 and S.frame:GetHeight() == 560 and not S.cog, "Settings 800 x 560, no cog of its own")
    for _, win in ipairs({ UI, L, S }) do
      assert(win.grip.__normalTex == "Interface\\ChatFrame\\UI-ChatIM-SizeGrabber-Up", "the game's size grabber in " .. win.key)
      press(win.close)
      assert(not win.frame:IsShown(), win.key .. ": the close closes it")
    end
    -- a place kept per window: L dragged by its header, J's own place untouched
    UI:Open("race"); UI:Open("quests")
    local jpos = c.env.CuteDB.pos
    L.frame.__left, L.frame.__top = 200, 700
    L.head.__scripts.OnDragStart(L.head); L.head.__scripts.OnDragStop(L.head)
    assert(c.env.CuteDB.winPos and c.env.CuteDB.winPos.quests and c.env.CuteDB.winPos.quests.left == 200 and c.env.CuteDB.pos == jpos, "L's place kept apart from J's")
    -- Settings' list at the smallest size: every section of an officer with every module on, rows 22 px and heads 20 px,
    -- each listed (the list scrolls there past thirteen, below)
    sizeAll(c, 760, 420)
    UI.OpenSettings("general")
    local heights, n = {}, 0
    for _, f in ipairs(c.frames) do if f.section and f:IsVisible() then n = n + 1; heights[f:GetHeight()] = true end end
    local sections = c.C.SettingsPage.Sections(true)
    assert(n == #sections and heights[22] and not heights[16] and not heights[20], "every section listed, each row 22 px: " .. n .. " of " .. #sections)
    assert(sectionsShown(c) == "general keys modules share columns vis rules example quests route map dungeons camp", "the sections by group: " .. sectionsShown(c))
    -- (merge2) Settings > Runs among them, under Guild after the guild's own (sectionsShown sets it aside for the runs
    -- stage); then the harness's own module addon (Cute_Example, the registration API's probe, which no player has) off:
    -- every section a player can have, the run report's with them (merge2 fitted thirteen unscrolled at 760 x 420: 16 +
    -- 60 + 13 x 22 of the 375 px the design gives the list)
    local ids = {}
    for _, sec in ipairs(sections) do ids[#ids + 1] = sec.id end
    -- (merge3) the cards round's Halls before it, under Guild; (fix-cute-ui) Achievements' and Records' guild switches
    -- are rows in Settings > Modules, no sections of their own
    assert(table.concat(ids, " "):find("vis rules halls runs example quests", 1, true), "Settings > Halls and Runs under Guild: " .. table.concat(ids, " "))
    M.Set("Cute_Example", false); tick(c, 1)
    UI.OpenSettings("general")
    -- (the hud round) Settings > Layout makes fourteen, and (merge3) the cards round's Halls fifteen ((fix-cute-ui)
    -- Achievements and Records have none): at 760 x 420 the list scrolls, its rows still 22 px, as the owner allows past
    -- thirteen; at Settings' own 800 x 560 every section fits unscrolled
    assert(#c.C.SettingsPage.Sections(true) == 15, "every section a player can have: " .. #c.C.SettingsPage.Sections(true))
    local navList
    for _, f in ipairs(c.frames) do if f.section and f:IsVisible() then navList = f.__parent.__scrollParent end end
    assert(navList and navList.bar:IsShown(), "fifteen at 760 x 420: the list scrolls")
    check(S.frame, "W3 settings at 760x420, every section listed")
    sizeAll(c, 800, 560)
    UI.OpenSettings("general")
    assert(not navList.bar:IsShown(), "the list fits unscrolled at 800 x 560")
    check(S.frame, "W3 settings at 800x560, every section listed")
    sizeAll(c, 1040, 640)
    -- the Statistics page: its categories in a column of their own (shown on that page alone); a leader only above 0
    UI:Open("game")
    assert(UI.catBox:IsShown() and UI.insetX and UI.insetX > 0, "the categories' column, the list beside it")
    for _, l in ipairs(UI.catLines.items) do if l:IsShown() and l.cat and l.cat.id == 133 then press(l) end end
    local daily
    for _, l in ipairs(UI.lines.items) do if l:IsShown() and l.def and l.def.id == "g2011" and not l.member then daily = l end end
    assert(daily and daily.who:GetText() == "-", "Daily quests completed, 0 for everyone: no leader: " .. tostring(daily and daily.who:GetText()))
    check(UI.frame, "W3 statistics, a statistic nobody has done")
    UI:Open("race")
    assert(not UI.catBox:IsShown() and (UI.insetX or 0) == 0, "the column goes with the page")
    -- (a quiet note from login, a client function this mock lacks, is no error of the windows')
    local errs = {}
    for _, e in ipairs(c.env.CuteDB.errors or {}) do if e.stack ~= "" then errs[#errs + 1] = tostring(e.where) .. ": " .. tostring(e.msg) end end
    assert(#(c.env.CuteQuestDB.errors or {}) == 0 and #errs == 0, "no error recorded: " .. table.concat(errs, "; "))
    leave(c)
    print("windows W3: J, L and Settings from one builder (30 px header, cog to the window's group, close, Esc, the game's size grabber, a place each); a module addon's page in J; Settings' list 22 px rows, scrolled at 760 x 420 and unscrolled at 800 x 560; the Statistics categories their own column; no leader at 0")
  end)
end

-- W4 (sub-project C): the reload rule. A box in Settings > Modules stages its change: nothing loads or goes, the box
-- shows it, the section says "Applies on reload." with Reload now and Undo. Reload now writes the choice and the game's
-- AddOns list and reloads; the login after it applies it. Closing Settings with a change staged asks the game's popup:
-- Reload, or Undo (Esc is Undo); in a fight Reload now is greyed and the question waits for the fight's end. The menu
-- offers "Reload to apply" meanwhile
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1) }, function()
    local state = {}
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = state, quest = true }))
    login(c); tickAll(6)
    local M = c.C.Modules
    local function row(label) return checkBox(c, function(cb) return cb.label and cb.label:GetText() == label end) end
    local function button(label) for _, b in ipairs(c.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == label then return b end end end
    c.C.UI:Open("settings", "modules")
    click(row("Gear tab"))
    assert(M.Staged() and M.staged["Cute_Quest:gear"] == true and not M.byId.gear.active and row("Gear tab"):GetChecked(), "staged: the box ticked, nothing on")
    assert(texts(c):find("Applies on reload.", 1, true) and button("Reload now") and button("Undo"), "the band line, Reload now and Undo:\n" .. texts(c))
    check(sframe(c), "W4 settings, modules, a change staged")
    press(button("Undo"))
    assert(not M.Staged() and not row("Gear tab"):GetChecked() and not texts(c):find("Applies on reload.", 1, true), "Undo: as it was")
    click(row("Gear tab"))
    press(button("Reload now"))
    local me = c.C.Me()
    assert(c.reloads == 1 and c.env.CuteDB.chars[me].modules["Cute_Quest:gear"] == true and not M.Staged(), "Reload now: the choice written, the interface reloaded")
    local db, qdb = c.env.CuteDB, c.env.CuteQuestDB
    leave(c)
    -- the reload's login applies it
    local d = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = state, quest = true }))
    d.env.CuteQuestDB = qdb
    login(d, db, true); tickAll(6)
    local M2 = d.C.Modules
    assert(M2.byId.gear and M2.byId.gear.active, "after the reload: the Gear tab on")
    -- closing Settings with a change staged: the game's popup, Reload or Undo; Esc (its OnCancel) undoes
    d.C.UI:Open("settings", "modules")
    click(checkBox(d, function(cb) return cb.label and cb.label:GetText() == "Gear tab" end))
    assert(M2.Staged(), "staged off")
    -- (the menu offers it meanwhile)
    d.C.Windows.Menu()
    local menu = d.contextMenus[#d.contextMenus]
    local offered = false
    for _, e in ipairs(menu) do if e.text == "Reload to apply" then offered = true end end
    assert(offered, "the menu: Reload to apply")
    sframe(d):Hide()
    assert(d.popups[#d.popups] == "CUTE_RELOAD" and d.env.StaticPopupDialogs.CUTE_RELOAD.text == "Cute reloads to apply your changes.", "closing asks: " .. tostring(d.popups[#d.popups]))
    local dlg = d.env.StaticPopupDialogs.CUTE_RELOAD
    assert(dlg.button1 == "Reload" and dlg.button2 == "Undo" and dlg.hideOnEscape and not dlg.button3, "Reload or Undo, no Later; Esc closes it as Undo")
    dlg.OnCancel()
    assert(not M2.Staged() and M2.byId.gear.active and d.reloads == 0, "Undo (Esc): nothing changed")
    -- in a fight: Reload now greyed, the question waits for its end
    d.C.UI:Open("settings", "modules")
    click(checkBox(d, function(cb) return cb.label and cb.label:GetText() == "Gear tab" end))
    d.combat = true
    sdraw(d)
    local rl
    for _, b in ipairs(d.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == "Reload now" then rl = b end end
    assert(rl and rl.__disabled, "in a fight Reload now is greyed")
    local p0 = #d.popups
    sframe(d):Hide()
    assert(#d.popups == p0, "closed in a fight: the question waits")
    d.combat = false
    fire(d, "PLAYER_REGEN_ENABLED")
    assert(d.popups[#d.popups] == "CUTE_RELOAD" and #d.popups == p0 + 1, "asked as the fight ends")
    dlg.OnAccept()
    assert(d.reloads == 1 and d.env.CuteDB.chars[me].modules["Cute_Quest:gear"] == false, "Reload: the change written, reloaded")
    leave(d)
    print("windows W4: a module box stages its change (the band line, Reload now, Undo); Reload now writes it and reloads, the login applies it; closing Settings asks Reload or Undo (Esc Undo), in a fight after it; the menu offers Reload to apply")
  end)
end

-- W5 (sub-project C): keys by override bindings that follow the game's own. Nothing taken before the character says so
-- (the setup card's Start, Settings > Keys); "follow" takes the game's key for its window (J for Guild & Communities, L
-- for the quest log) and moves with it when the player rebinds the game's; a hand-picked key says what it replaces;
-- Clear gives the game its key back; the Guild key waits for a guild; in a fight nothing is set until it ends. The key
-- box takes a key with its modifiers; Esc keeps the old one, Backspace clears it. The key clicks the window's button
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(c); tickAll(6)
    local K = c.C.Keys
    assert(next(c.overrides) == nil, "nothing taken before the character says so")
    K.Set("guild", "follow"); K.Set("quests", "follow")
    assert(c.overrides.J and c.overrides.J.button == "CuteGuildKey" and c.overrides.L and c.overrides.L.button == "CuteQuestsKey" and c.overrides.J.owner == c.env.CuteKeyOwner, "follow: J and L clicked Cute's buttons, held by CuteKeyOwner")
    assert(c.env.CuteDB.chars[c.C.Me()].keys.guild == "follow", "kept per character")
    -- the key clicks the window's button: L opens and shuts
    press(c.env.CuteQuestsKey)
    assert(qwin(c).frame:IsShown(), "L's key opens the quest window")
    press(c.env.CuteQuestsKey)
    assert(not qwin(c).frame:IsShown(), "and shuts it")
    -- the player rebinds the game's quest log to K: Cute's key moves with it
    c.bindings.TOGGLEQUESTLOG = { "K" }
    fire(c, "UPDATE_BINDINGS")
    assert(c.overrides.K and c.overrides.K.button == "CuteQuestsKey" and not c.overrides.L, "following the game's key: K now")
    -- a hand-picked key that does something else in the game says so (Settings > Keys)
    K.Set("quests", "5")
    c.C.UI:Open("settings", "keys")
    assert(c.overrides["5"] and texts(c):find("replaces Action Button 5", 1, true), "a hand-picked key, and what it replaces:\n" .. texts(c))
    check(sframe(c), "W5 settings, keys, a hand-picked key")
    -- the key box: a click, then a key with its modifiers; Esc keeps it; Backspace clears it
    local box
    for _, b in ipairs(c.frames) do if b.id == "quests" and b:IsVisible() and rawget(b, "Bind") then box = b end end
    assert(box and box.label:GetText() == "5", "the box shows the key: " .. tostring(box and box.label:GetText()))
    press(box)
    assert(box.waiting and box.label:GetText() == "Press a key", "a click: Press a key")
    box.__scripts.OnKeyDown(box, "LSHIFT")
    assert(box.waiting, "a modifier alone is no key")
    c.ctrl = true
    box.__scripts.OnKeyDown(box, "Q")
    c.ctrl = false
    assert(K.Get("quests") == "CTRL-Q" and c.overrides["CTRL-Q"] and not c.overrides["5"], "Ctrl-Q taken, 5 given back")
    for _, b in ipairs(c.frames) do if b.id == "quests" and b:IsVisible() and rawget(b, "Bind") then box = b end end
    press(box)
    box.__scripts.OnKeyDown(box, "ESCAPE")
    assert(not box.waiting and K.Get("quests") == "CTRL-Q", "Esc keeps the old key")
    press(box)
    box.__scripts.OnKeyDown(box, "BACKSPACE")
    assert(K.Get("quests") == false and not c.overrides["CTRL-Q"], "Backspace clears it: the game's L is the game's again")
    -- Follow ticked again goes back to the game's key
    click(checkBox(c, function(cb) return cb.label and cb.label:GetText() == "Follow the game's Quest log key" end))
    assert(K.Get("quests") == "follow" and c.overrides.K, "Follow ticked: the game's key again")
    -- in a fight: nothing set until it ends
    c.combat = true
    c.bindings.TOGGLEQUESTLOG = { "L" }
    fire(c, "UPDATE_BINDINGS")
    assert(c.overrides.K and not c.overrides.L, "in a fight the overrides wait")
    c.combat = false
    fire(c, "PLAYER_REGEN_ENABLED")
    assert(c.overrides.L and not c.overrides.K, "as it ends: L")
    -- no guild: no Guild key; joining one takes it
    c.inGuild = false
    fire(c, "PLAYER_GUILD_UPDATE")
    assert(not c.overrides.J and c.overrides.L, "out of a guild: J left to the game")
    c.inGuild = true
    fire(c, "PLAYER_GUILD_UPDATE")
    assert(c.overrides.J, "in a guild again: J taken")
    -- Clear: none taken, the game's key opens the game's window
    K.Set("guild", false)
    assert(not c.overrides.J, "cleared: J the game's")
    leave(c)
    print("windows W5: keys by override bindings: nothing before asked, follow the game's key (and its rebinding), a hand-picked key named with what it replaces, Clear, the box's capture (modifiers, Esc, Backspace), the Guild key in a guild alone, nothing set in a fight")
  end)
end

-- W6 (sub-project C): the right-click menu (MenuUtil) on the minimap button and the addon compartment: every window's
-- tabs (a parent opens its window when clicked), the on-screen switches, every Settings section; the officers' entries
-- for officers alone; a click on an entry opens that tab or section
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1), member("Pim", 3) }, function()
    local rone = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    local pim = newClient(charOf({ "Pim", 3, "Raider", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(rone); login(pim); tickAll(6)
    rone.C.Keys.Set("guild", "follow"); rone.C.Keys.Set("quests", "follow")
    local function menuOf(c, how)
      local n0 = #c.contextMenus
      if how == "compartment" then c.env.Cute_OnCompartment("Cute", "RightButton") else c.C.UI.mini.__scripts.OnClick(c.C.UI.mini, "RightButton") end
      assert(#c.contextMenus == n0 + 1, "a menu opened")
      return c.contextMenus[#c.contextMenus]
    end
    local function entry(list, text) for _, e in ipairs(list) do if e.text == text then return e end end end
    local function names(list) local out = {}; for _, e in ipairs(list) do out[#out + 1] = e.kind == "divider" and "---" or tostring(e.text) end; return table.concat(out, ", ") end
    local m = menuOf(rone)
    assert(m[1].kind == "title" and m[1].text == "Cute", "titled Cute")
    local g, q, s = entry(m, "Guild (J)"), entry(m, "Quests (L)"), entry(m, "Settings")
    assert(g and q and s and g.responds and q.responds and s.responds, "Guild (J), Quests (L) and Settings, each opening its window when clicked: " .. names(m))
    -- (merge2: the run report's Runs tab and its section among them; merge3: the cards round's Halls tab, the Hall of
    -- Shame retitled)
    assert(names(g.sub) == "Race, Prog, Halls, Runs, Statistics, Officers, Me", "the guild's tabs: " .. names(g.sub))
    assert(names(q.sub) == "Quests, Route, ---, Step frame, Direction arrow", "the quests' tabs and the on-screen switches: " .. names(q.sub))
    -- (merge3: the cards round's Halls before Runs; Reminders, on by default, after Route. fix-cute-ui: Achievements' and
    -- Records' guild switches are rows in Settings > Modules, no sections)
    assert(names(s.sub) == "General, Keys, Layout, Modules, Data you share, Columns, Who sees what, Rules, Halls, Runs, Quests, Route, Reminders", "every section: " .. names(s.sub))
    assert(entry(m, "Set up Cute...") and not entry(m, "Reload to apply"), "Set up Cute... before Start; no reload to apply")
    -- a click opens: a tab, the window, a section; a switch flips the engine's setting
    entry(g.sub, "Statistics").set()
    assert(rone.C.UI.page == "game" and rone.C.UI.frame:IsShown(), "Guild > Statistics")
    entry(q.sub, "Route").set()
    assert(qwin(rone).page == "route" and qwin(rone).frame:IsShown(), "Quests > Route")
    q.set()
    assert(qwin(rone).frame:IsShown(), "Quests (L) clicked: its window")
    entry(s.sub, "Keys").set()
    assert(rone.C.UI.Window("settings").section == "keys", "Settings > Keys")
    local sw = entry(q.sub, "Direction arrow")
    assert(sw.kind == "check" and sw.get() == true, "the arrow's switch, on")
    sw.set()
    assert(rone.env.CuteQuestDB.settings.arrow == false, "flipped off")
    sw.set()
    -- the member: no Officers, no Rules
    local pm = menuOf(pim, "compartment")
    assert(names(entry(pm, "Guild").sub) == "Race, Prog, Halls, Runs, Statistics, Me" and not names(entry(pm, "Settings").sub):find("Rules", 1, true), "the member's menu: no officers' entries: " .. names(entry(pm, "Guild").sub))
    -- the compartment's click: the guild window
    pim.env.Cute_OnCompartment("Cute", "LeftButton")
    assert(pim.C.UI.frame:IsShown(), "the compartment's click: J")
    -- the minimap button's tooltip
    local tip = tipOf(rone.C.UI.mini)
    assert(tip:find("Click: guild. Right-click: menu. Drag: move.", 1, true), "its tooltip: " .. tip)
    -- the toc names the compartment's function
    local toc = assert(io.open(HERE .. "/Cute/Cute.toc")):read("*a")
    assert(toc:find("## AddonCompartmentFunc: Cute_OnCompartment", 1, true), "the toc names it")
    leave(rone); leave(pim)
    print("windows W6: the menu on the minimap button and the compartment: Guild (J), Quests (L) and Settings with every tab, switch and section, parents opening their windows; the officers' entries for officers; a click opens its part")
  end)
end

-- W7 (sub-project C): the first-run card, once per character, from its own saved choices. A 0.7 character with Gear off
-- and Accept for me "On my route": the rows start there, the keys from the game's (J, L), a hand-picked key says what
-- it replaces; in a fight Start is greyed; Start writes what it showed and nothing else, marks the rows answered, keeps
-- the keys and reloads, and the quest window opens once after; the card never comes back. Not now changes nothing, the
-- card does not come back by itself, the menu keeps "Set up Cute..."
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1), member("Pim", 3) }, function()
    local state = {}
    local function client(name, rank) return newClient(charOf({ name, rank, rank <= 1 and "Officer" or "Raider", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = state, quest = true, card = true })) end
    local c = client("Rone", 1)
    -- a 0.7 save: Gear off, Journal and Map on, Camp off; the engine's Accept for me on the route
    local db = { version = "0.7.1", chars = { ["Rone-Forever"] = { counters = {}, modules = { ["Cute_Quest:gear"] = false, ["Cute_Quest:journal"] = true, ["Cute_Quest:map"] = true, ["Cute_Quest:camp"] = false } } } }
    c.env.CuteQuestDB = { settings = { autoAccept = "route", autoTurnIn = false, guide = { on = true, frame = true }, cuteDefaults = true } }
    login(c, db)
    local card = c.env.CuteSetupFrame
    assert(not (card and card:IsShown()), "not before 3 s")
    tick(c, 3)
    card = c.env.CuteSetupFrame
    assert(card and card:IsShown(), "the card, 3 s after the loading screen")
    local function row(label) return checkBox(c, function(cb) return cb.label and cb.label:GetText() == label end) end
    assert(row("Dungeons tab"):GetChecked() and not row("Gear tab"):GetChecked() and row("Map"):GetChecked(), "the tabs as 0.7 left them: Gear off (the map's row Map, its window's from sub-project F)")
    -- (merge3) the light its own row, from the light: on in this save (the engine's default, no 0.7 keeping), so ticked;
    -- Camp off unticks Reminders alone
    assert(not row("Reminders"):GetChecked() and row("Interact light"):GetChecked() and row("Step frame and arrow"):GetChecked(), "Camp off, the light on as the save has it, the step frame on")
    assert(row("On my route"):GetChecked() and not row("Off"):GetChecked() and not row("Hand finished quests in for me"):GetChecked(), "Accept for me: On my route")
    local keys = {}
    for _, b in ipairs(c.frames) do if rawget(b, "Bind") and b:IsVisible() and b.id then keys[b.id] = b end end
    assert(keys.guild and keys.guild.label:GetText() == "J" and keys.quests and keys.quests.label:GetText() == "L", "the keys from the game's: J and L")
    assert(texts(c):find("for Rone", 1, true) and texts(c):find("Window and tab changes reload; the rest applies at once.", 1, true), "the card's words:\n" .. texts(c))
    check(card, "W7 the setup card")
    -- a hand-picked key for the quests: what it replaces, under its row
    press(keys.quests)
    keys.quests.__scripts.OnKeyDown(keys.quests, "5")
    assert(texts(c):find("replaces Action Button 5", 1, true), "a hand-picked key says what it replaces:\n" .. texts(c))
    check(card, "W7 the setup card, a hand-picked key")
    -- in a fight Start is greyed
    c.combat = true
    fire(c, "PLAYER_REGEN_DISABLED")
    local start
    for _, b in ipairs(c.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == "After combat" then start = b end end
    assert(start and start.__disabled, "Start greyed in a fight, After combat")
    c.combat = false
    fire(c, "PLAYER_REGEN_ENABLED")
    -- Start: what it showed, nothing else
    local menuBefore
    c.C.Windows.Menu()
    for _, e in ipairs(c.contextMenus[#c.contextMenus]) do if e.text == "Set up Cute..." then menuBefore = true end end
    assert(menuBefore, "the menu has Set up Cute... until Start")
    for _, b in ipairs(c.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == "Start" then start = b end end
    press(start)
    local ch, s = c.env.CuteDB.chars["Rone-Forever"], c.env.CuteQuestDB.settings
    assert(c.reloads == 1 and not card:IsShown(), "Start reloads")
    assert(ch.modules["Cute_Quest:gear"] == false and ch.modules["Cute_Quest:journal"] == true and ch.modules["Cute_Quest:map"] == true and ch.modules["Cute_Quest:camp"] == false, "the modules as shown")
    assert(s.autoAccept == "route" and s.autoTurnIn == false and s.guide.frame == true, "the engine's choices as shown")
    assert(ch.keys.guild == "follow" and ch.keys.quests == "5", "the keys: J follows the game's, the quests' 5")
    for _, id in ipairs({ "guild", "quests", "dungeons", "gear", "mapwin", "step", "camp", "light", "accept", "handin" }) do assert(ch.setup[id] == true, "answered: " .. id) end
    assert(ch.openAfter == "quests", "the quest window to open after the reload")
    local db2, qdb = c.env.CuteDB, c.env.CuteQuestDB
    leave(c)
    -- the reload: the quest window opens once, the card never again, the keys taken
    local d = client("Rone", 1)
    d.env.CuteQuestDB = qdb
    login(d, db2, true); tickAll(6)
    assert(qwin(d).frame and qwin(d).frame:IsShown() and d.env.CuteDB.chars["Rone-Forever"].openAfter == nil, "the quest window opened once after Start")
    assert(not (d.env.CuteSetupFrame and d.env.CuteSetupFrame:IsShown()) and d.overrides["5"] and d.overrides.J, "no card again; the keys taken")
    assert(not d.C.Setup.Pending(), "nothing left to answer")
    leave(d)
    -- Not now: nothing changes, the card waits for the menu
    local p = client("Pim", 3)
    login(p); tickAll(5)
    assert(p.env.CuteSetupFrame and p.env.CuteSetupFrame:IsShown(), "a fresh character's card")
    local later
    for _, b in ipairs(p.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == "Not now" then later = b end end
    local before = p.env.CuteDB.chars["Pim-Forever"].modules and next(p.env.CuteDB.chars["Pim-Forever"].modules)
    press(later)
    assert(not p.env.CuteSetupFrame:IsShown() and p.reloads == 0 and next(p.overrides) == nil and (p.env.CuteDB.chars["Pim-Forever"].modules and next(p.env.CuteDB.chars["Pim-Forever"].modules)) == before, "Not now: nothing changed, no key taken")
    assert(p.C.Setup.Pending(), "the menu keeps Set up Cute...")
    local pdb, pqdb = p.env.CuteDB, p.env.CuteQuestDB
    leave(p)
    local p2 = client("Pim", 3)
    p2.env.CuteQuestDB = pqdb
    login(p2, pdb); tickAll(6)
    assert(not (p2.env.CuteSetupFrame and p2.env.CuteSetupFrame:IsShown()), "the card does not come back by itself")
    p2.env.SlashCmdList.CUTE("setup")
    assert(p2.env.CuteSetupFrame and p2.env.CuteSetupFrame:IsShown(), "/cute setup brings it")
    leave(p2)
    print("windows W7: the setup card from each character's own choices (a 0.7 save's Gear off and Accept on the route), the game's keys, a hand-picked key's 'replaces', Start greyed in a fight, Start writing what it showed, reloading and the quest window opening once; Not now changing nothing, the card not coming back by itself")
  end)
end

-- W8 (sub-project C): the quest to read. A quest row's click in the quest window gives way to the quest (its name, the
-- game's text for a quest in the log, its objectives, the hand-in, its buttons); Back returns to the list where it was.
-- Ctrl-click shows it on the arrow instead. Share only in a group and for a quest the game lets you share (the game's
-- QuestLogPushQuest of its log index); Abandon asks the game's question (the engine's ConfirmAbandon); a quest not taken
-- has the pick-up list. The band's step reads its quest
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true, log = { [7] = 2 } }))
    login(c); tickAll(6)
    local QB = c.addons[2].private
    local L = qwin(c)
    c.C.UI:Open("quests")
    -- the band's step reads its quest
    local steps = QB.Guide.Steps()
    local s1 = steps[1]
    assert(s1 and s1.qid, "a step with a quest")
    local band = L.bandKit and L.bandKit.step
    assert(band and band:IsShown() and band.fn, "the band's step")
    band.__scripts.OnClick(band, "LeftButton")
    local q = QB.Quest.Get(s1.qid)
    assert(L.reading and L.reading.id == s1.qid and texts(c):find(q.name, 1, true) and texts(c):find("Back", 1, true), "the step's click reads its quest:\n" .. texts(c))
    check(L.frame, "W8 the quest to read, from the band")
    local back
    for _, b in ipairs(L.bandButtons.items) do if b:IsShown() and b.label:GetText() == "Back" then back = b end end
    press(back)
    assert(not L.reading, "Back: the list again")
    -- a quest in the log: its text, objectives, Share only in a group and when pushable, Abandon through the engine
    local id = next(c.o.log)
    local held = QB.Quest.Get(id)
    assert(held and QB.state.log[id], "a quest of the catalog in the log: " .. tostring(id))
    do
      QB.Reader.Read(L, held)
      local t = texts(c)
      assert(t:find("The words of quest " .. id .. ".", 1, true) and t:find("Objectives", 1, true) and t:find("Abandon", 1, true) and not t:find("Share", 1, true), "a held quest: its text, objectives, Abandon, no Share alone:\n" .. t)
      c.party = { { "Bo", "MAGE", 5 } }
      c.pushable = { [id] = true }
      redraw(c)
      local share, abandon
      for _, b in ipairs(L.buttons.items) do if b:IsShown() then if b.label:GetText() == "Share" then share = b elseif b.label:GetText() == "Abandon" then abandon = b end end end
      assert(share, "in a group and shareable: Share")
      press(share)
      assert(c.pushed[#c.pushed] == QB.state.log[id].index, "Share pushes its log index: " .. tostring(c.pushed[#c.pushed]))
      local m0 = #c.contextMenus
      press(abandon)
      assert(#c.contextMenus == m0 + 1 and (c.contextMenus[#c.contextMenus][1].text or ""):find("Abandon", 1, true), "Abandon asks the game's question first")
      check(L.frame, "W8 a held quest to read, in a group")
      c.party, c.pushable = nil, nil
      press((function() for _, b in ipairs(L.bandButtons.items) do if b:IsShown() and b.label:GetText() == "Back" then return b end end end)())
    end
    -- a list row: click reads; Ctrl-click shows it on the arrow and reads nothing
    -- (the windows round: a quest's row is the one with a level, pattern A)
    local row
    for _, r in ipairs(L.hosts.quests.pool.items) do if r:IsShown() and r.fn and r.tip and r.lvl:IsShown() then row = row or r end end
    assert(row, "a quest's row on the Quests tab")
    if row then
      L.scroll.bar:SetMinMaxValues(0, 100); L.scroll.bar:SetValue(20)
      local at = L.scroll.bar:GetValue()
      press(row)
      assert(L.reading, "a quest row's click reads it")
      local back2
      for _, b in ipairs(L.bandButtons.items) do if b:IsShown() and b.label:GetText() == "Back" then back2 = b end end
      press(back2)
      assert(not L.reading and L.scroll.bar:GetValue() == math.min(at, select(2, L.scroll.bar:GetMinMaxValues())), "and Back, to the list where it was")
      c.ctrl = true
      press(row)
      c.ctrl = false
      assert(not L.reading, "Ctrl-click: on the arrow, nothing read")
    end
    assert(#(c.env.CuteQuestDB.errors or {}) == 0, "no engine error recorded")
    leave(c)
    print("windows W8: the quest to read from the band and the list, Back, Ctrl-click to the arrow; a held quest's text and objectives, Share in a group when shareable (its log index), Abandon through the game's question")
  end)
end

-- W9 (sub-project C): the header's buttons to the game's own windows: secure click buttons on the game's micro buttons
-- (SecureActionButtonTemplate, type click), no child of the window (Cute's windows open in a fight), placed over their
-- stand-in while the window shows and out of combat, hidden as a fight begins and placed again after; none where a UI
-- addon removed the micro button
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1), member("Pim", 3) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(c); tickAll(6)
    c.C.UI:Open("race"); c.C.UI:Open("quests")
    local W = c.C.Windows
    local g, q = W.secure.guild, W.secure.quests
    -- (J and L apart, so neither header stands under the other window: W19 weighs a window in front)
    c.C.UI.frame.__left, c.C.UI.frame.__top, c.C.UI.gameStand.__left, c.C.UI.gameStand.__top = 0, 1000, 800, 994
    qwin(c).frame.__left, qwin(c).frame.__top, qwin(c).gameStand.__left, qwin(c).gameStand.__top = 0, 300, 860, 294
    if W.PlaceAll then W.PlaceAll() end
    assert(g and q and g.__template:find("SecureActionButtonTemplate", 1, true), "secure buttons for both")
    assert(g:GetAttribute("type") == "click" and g:GetAttribute("clickbutton") == c.env.GuildMicroButton and q:GetAttribute("clickbutton") == c.env.QuestLogMicroButton, "a click on the game's micro buttons")
    assert(g.__parent == c.env.UIParent and g:IsShown() and q:IsShown(), "parented to UIParent, shown with their windows")
    local said = {}
    for _, l in ipairs(c.C.Diag()) do said[#said + 1] = l end
    assert(said[#said]:find("^diag windows: game buttons guild shown, quests shown") and said[#said]:find("menus yes", 1, true), "/cute diag's last line, the game buttons: " .. said[#said])
    assert(c.C.UI.gameStand.label:GetText() == "Guild & Communities" and qwin(c).gameStand.label:GetText() == "Quest log", "named as the game's windows")
    c.combat = true
    fire(c, "PLAYER_REGEN_DISABLED")
    assert(not g:IsShown() and not q:IsShown(), "hidden as a fight begins")
    local d = c.C.Windows.DiagLine()
    assert(d:find("game buttons guild hidden, quests hidden", 1, true) and d:find("in combat yes", 1, true) and not d:find("Rone", 1, true), "/cute diag says the buttons' state, no name: " .. d)
    c.C.UI.frame:Hide(); c.C.UI:Toggle()
    assert(c.C.UI.frame:IsShown() and not g:IsShown(), "J opens in a fight, the secure button waits")
    c.combat = false
    fire(c, "PLAYER_REGEN_ENABLED")
    assert(g:IsShown(), "placed again after the fight")
    hideAll(c)
    assert(not g:IsShown() and not q:IsShown(), "hidden with their windows")
    leave(c)
    local p = newClient(charOf({ "Pim", 3, "Raider", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true, noMicro = true }))
    login(p); tickAll(6)
    p.C.UI:Open("race")
    assert(not p.C.UI.gameStand and not p.C.Windows.secure.guild, "no micro button: no header button")
    check(p.C.UI.frame, "W9 J without the game's micro buttons")
    leave(p)
    print("windows W9: the header's game buttons are secure clicks on the micro buttons, outside the windows, shown with them out of combat, hidden in a fight and back after; none without the micro button")
  end)
end

-- W10 (sub-project C): the step frame's click on a quest reads it in the quest window (the engine names the quest,
-- UI.scrollToQuest, and opens tab 1; the Bridge reads it), Ctrl-click puts it on the arrow without opening anything; the
-- tracker's row greyed while the step frame is off; a guild window's redraw with nothing new sorts nothing (the sorted
-- members kept until the roster, the sort or the offline switch changes), and a module's refresh leaves the guild's own
-- pages alone
do
  local function member(name, rank, level) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = level or 5, online = true } end
  isolated({ member("Rone", 1), member("Pim", 3, 9), member("Tova", 3, 3) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(c); tickAll(6)
    local QB = c.addons[2].private
    local L = qwin(c)
    local step = c.env.QuestBankStep
    local s1 = QB.Guide.Steps()[1]
    assert(step and step.rows and s1 and s1.qid, "the step frame and a quest step")
    assert(not (L.frame and L.frame:IsShown()), "the quest window closed")
    press(step.rows[1])
    assert(L.frame:IsShown() and L.page == "quests" and L.reading and L.reading.id == s1.qid, "the step frame's click reads its quest in the quest window")
    assert(QB.UI.scrollToQuest == nil, "the quest named once")
    check(L.frame, "W10 the step frame's quest, read")
    L.frame:Hide()
    L.reading = nil
    c.ctrl = true
    press(step.rows[1])
    c.ctrl = false
    assert(not L.frame:IsShown() and not L.reading, "Ctrl-click: on the arrow, no window")
    -- the tracker's row follows the step frame's
    c.C.UI.OpenSettings("quests")
    local function trackerRow()
      for _, f in ipairs(c.frames) do
        if f:IsVisible() and f.label and f.label.GetText and (f.label:GetText() or ""):find("^Hide the game's quest tracker") and f.Set then return f end
      end
    end
    local s = c.env.CuteQuestDB.settings
    assert(s.guide.frame == true and trackerRow() and trackerRow():IsEnabled(), "the frame on: the tracker's row to tick")
    s.guide.frame = false
    sdraw(c)
    assert(trackerRow() and not trackerRow():IsEnabled(), "the frame off: the tracker's row greyed")
    s.guide.frame = true
    hideAll(c)
    -- J's Race: a redraw with nothing new sorts nothing; a roster change, a sort, the offline switch sort again
    local UI = c.C.UI
    UI:Open("race")
    local sorts, realSort = 0, table.sort
    local function counted(fn)
      sorts = 0
      table.sort = function(t, f) if type(t[1]) == "table" and t[1].tier ~= nil then sorts = sorts + 1 end; return realSort(t, f) end
      local ok, err = pcall(fn)
      table.sort = realSort
      assert(ok, err)
      return sorts
    end
    local function order()
      local out = {}
      for _, w in ipairs(UI.rows.items) do if w:IsShown() and w.row then out[w.idx] = w.row.name end end
      return table.concat(out, " ")
    end
    assert(counted(function() UI:Draw() end) == 0, "a redraw with nothing new sorts nothing")
    local before = order()
    assert(counted(function() c.C.Roster:Changed(); UI:Draw() end) == 1, "a roster change sorts again")
    local header
    for _, h in ipairs(UI.headerCells.items) do if h:IsShown() and h.id == "level" then header = h end end
    assert(counted(function() press(header) end) == 1, "a new sort sorts again")
    assert(order() ~= before, "and the order follows it: " .. before .. " / " .. order())
    assert(counted(function() UI:Draw() end) == 0, "and keeps it")
    -- a module's refresh: the quest window draws again, the guild's own page waits for the guild's news
    UI:Open("quests")
    UI.refreshing, L.refreshing = false, false
    c.env.Cute.Refresh()
    assert(L.refreshing and not UI.refreshing, "Cute.Refresh: the quest window again, not Race")
    tick(c, 2)
    assert(#(c.env.CuteQuestDB.errors or {}) == 0, "no engine error recorded")
    leave(c)
    print("windows W10: the step frame's quest read in the quest window (Ctrl: the arrow, no window); the tracker's row greyed with the frame off; a guild redraw with nothing new sorts nothing; a module's refresh leaves the guild's own pages alone")
  end)
end

-- W11 (sub-project D): the step frame in Cute's look, in place of the game's tracker: a stop of the route standing on the
-- world with no backdrop (its menu brings Cute's flat one back), its text outlined and shadowed, the step's words at
-- 15 px; the first run lists three of the quests you hold under it, and Settings > Quests' "Quests under the step" sets
-- how many (0 to 10), at once
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true,
      log = { [7] = 2, [33] = 1, [18] = 1, [15] = 1, [21] = 1, [47] = 1, [60] = 1 } }))
    login(c); tickAll(6)
    local s = c.env.CuteQuestDB.settings
    local f = c.env.QuestBankStep
