  -- K11: the finds in the officers' word. The officers keep Finds: a find sure now is said half an hour on (never where
  -- two members stood a minute ago), by one officer (the other's copy covered), past the word's newest 48 too (a find
  -- leaving the word takes nothing back), a word that changed in its finds alone five minutes after the last at the
  -- soonest, its key the same when a third voice moves the find's mean. Finds open: a find sure now sends no word
  local function partsOf(c, from)
    local n, finds = 0, 0
    for i = from or 1, #c.sent do
      local m = c.sent[i]
      if m.msg:sub(1, 3) == "1N|" then n = n + 1; for _ in m.msg:gmatch("[|;]f[bkhx]") do finds = finds + 1 end end
    end
    return n, finds
  end
  isolated({ fmember("Ofa", 0), fmember("Oli", 1), fmember("Mia", 3), fmember("Ann", 3), fmember("Cy", 3) }, function()
    local closed = { gc_finds = "self" }
    local ofa, oli, mia, ann, cy = fchar("Ofa", 0), fchar("Oli", 1), fchar("Mia", 3), fchar("Ann", 3), fchar("Cy", 3)
    login(ofa, fpol(true, closed)); login(oli, fpol(nil, closed)); login(mia, fpol(nil, closed)); login(ann, fpol(nil, closed)); login(cy, fpol(nil, closed))
    tickAll(130)
    local F = ofa.C.Finds
    -- the officers hear Mia's and Ann's chests whispered, ten a message
    local function hear(list, from)
      for _, o in ipairs({ ofa, oli }) do
        for _, who in ipairs(from) do
          local parts = {}
          for _, en in ipairs(list) do parts[#parts + 1] = F.Pack(en) end
          for i = 1, #parts, 10 do o.C.Finds:Receive(table.concat(parts, ";", i, math.min(#parts, i + 9)), who.sender, true) end
        end
      end
    end
    local list = {}
    for i = 1, 50 do list[i] = { k = "h", id = 20000 + i, m = 1429, x = (i % 25) * 40, y = math.floor(i / 25) * 40 + 20 } end
    local o0, l0 = #ofa.sent, #oli.sent
    hear(list, { mia, ann })
    tickAll(600)
    local _, f1 = partsOf(ofa, o0 + 1)
    local _, f2 = partsOf(oli, l0 + 1)
    assert(f1 + f2 == 0, "ten minutes on: no find in the word yet")
    tickAll(1300)
    _, f1 = partsOf(ofa, o0 + 1)
    _, f2 = partsOf(oli, l0 + 1)
    assert((f1 == 48) ~= (f2 == 48) and f1 + f2 == 48, "half an hour on: the newest 48, said by one officer: " .. f1 .. " and " .. f2)
    tickAll(10)
    assert(rowOf(cy, 1429, 20050) and rowOf(cy, 1429, 20050).sure, "Cy has them, sure")
    -- the 51st: the oldest leaves the word, which takes nothing back: one officer says it, five minutes after the last
    local o1, l1 = #ofa.sent, #oli.sent
    local t1 = ofa.clock
    hear({ { k = "h", id = 20051, m = 1436, x = 500, y = 500 } }, { mia, ann })
    tickAll(1900)
    local n1, g1 = partsOf(ofa, o1 + 1)
    local n2, g2 = partsOf(oli, l1 + 1)
    assert((g1 > 0) ~= (g2 > 0), "the 51st said by one officer, the other covered: " .. g1 .. " and " .. g2)
    local first
    for _, c in ipairs({ ofa, oli }) do for i = (c == ofa and o1 or l1) + 1, #c.sent do if c.sent[i].msg:sub(1, 3) == "1N|" then first = math.min(first or math.huge, c.sent[i].at) end end end
    assert(first and first - t1 >= 1740, "half an hour after it became sure (kept to the minute): " .. tostring(first and first - t1))
    assert(rowOf(cy, 1436, 20051) and rowOf(cy, 1436, 20051).sure and rowOf(cy, 1429, 20003) and rowOf(cy, 1429, 20003).sure, "Cy has the 51st, and keeps the one that left the word")
    -- two words that changed in their finds alone: five minutes apart at the least
    local o2, l2 = #ofa.sent, #oli.sent
    hear({ { k = "h", id = 20052, m = 1436, x = 600, y = 500 } }, { mia, ann })
    tickAll(1830)
    hear({ { k = "h", id = 20053, m = 1436, x = 700, y = 500 } }, { mia, ann })
    tickAll(1900)
    local at = {}
    for _, c in ipairs({ ofa, oli }) do for i = (c == ofa and o2 or l2) + 1, #c.sent do local m = c.sent[i]; if m.msg:sub(1, 3) == "1N|" then at[#at + 1] = m.at end end end
    table.sort(at)
    local words = {}
    for _, t in ipairs(at) do if #words == 0 or t - words[#words] > 30 then words[#words + 1] = t end end
    assert(#words >= 2, "two words: " .. #words)
    for i = 2, #words do assert(words[i] - words[i - 1] >= 300, "a finds-only word five minutes after the last at the soonest: " .. (words[i] - words[i - 1])) end
    -- a third voice moving the mean: the word's key stays
    local before = table.concat(F:WordParts(), ";")
    F:Receive(F.Pack({ k = "h", id = 20051, m = 1436, x = 510, y = 505 }), cy.sender, true)
    assert(table.concat(F:WordParts(), ";") == before, "a third voice moving the mean leaves the word as it was")
    for _, c in ipairs({ ofa, oli, mia, ann, cy }) do leave(c) end
  end)
  -- Finds open: a find sure now sends no word, nor does anything else asking for one (Rules.lua's), the change being
  -- the finds' alone; a member who logs in later and asks has it in the answer
  isolated({ fmember("Ofa", 0), fmember("Mia", 3), fmember("Ann", 3), fmember("Lat", 3) }, function()
    for _, m in ipairs(GUILD) do if m.guid == guidOf("Lat") then m.online = false end end
    local ofa, mia, ann = fchar("Ofa", 0), fchar("Mia", 3), fchar("Ann", 3)
    login(ofa, fpol(true, {})); login(mia, fpol()); login(ann, fpol())
    tickAll(130)
    local o0 = #ofa.sent
    fnoted(mia, "h", 9201, 1429, 500, 500)
    tickAll(65)
    fnoted(ann, "h", 9201, 1429, 506, 500)
    tickAll(400)
    assert(rowOf(ofa, 1429, 9201).sure and select(1, partsOf(ofa, o0 + 1)) == 0, "Finds open: sure on the officer's client, no word sent for it")
    ofa.C.Comm:WordSoon()
    tickAll(400)
    assert(select(1, partsOf(ofa, o0 + 1)) == 0, "nor when something else asks for a word, the finds alone changed")
    for _, m in ipairs(GUILD) do if m.guid == guidOf("Lat") then m.online = true end end
    local lat = fchar("Lat", 3)
    login(lat, fpol())
    fire(ofa, "GUILD_ROSTER_UPDATE")
    tickAll(120)
    local r = rowOf(lat, 1429, 9201)
    assert(r and r.sure, "a member who logs in later: the find in the answer to its ask")
    for _, c in ipairs({ ofa, mia, ann, lat }) do leave(c) end
    said[#said + 1] = "the finds in the officers' word: half an hour after sure where the officers keep them, by one officer, past the newest 48 nothing taken back, five minutes apart, a key a third voice leaves; open, no word for them"
  end)
  -- K12: the officers keep Finds and none is online: a member's finds wait (no whisper to nobody, nothing lost, the
  -- hour's count untouched), and go to the first officer who comes online
  isolated({ fmember("Ofa", 0), fmember("Mia", 3) }, function()
    local closed = { gc_finds = "self" }
    for _, m in ipairs(GUILD) do if m.guid == guidOf("Ofa") then m.online = false end end
    local mia = fchar("Mia", 3)
    login(mia, fpol(nil, closed))
    tickAll(130)
    local m0 = #mia.sent
    fnoted(mia, "h", 9201, 1429, 500, 500)
    tickAll(300)
    local out = mia.env.CuteDB.chars["Mia-Forever"].findsOut
    assert(#said1X(mia, m0 + 1) == 0 and #out == 1 and (mia.C.Finds.sent or 0) == 0, "no officer online: nothing sent, the chest waits")
    local line
    for _, l in ipairs(mia.C.Diag()) do if l:find("^diag finds:") then line = l end end
    assert(line and line:find("no officer online", 1, true), "/cute diag says why: " .. tostring(line))
    -- Ofa comes online
    for _, m in ipairs(GUILD) do if m.guid == guidOf("Ofa") then m.online = true end end
    local ofa = fchar("Ofa", 0)
    login(ofa, fpol(true, closed))
    tickAll(10)
    fire(mia, "GUILD_ROSTER_UPDATE")
    tickAll(130)
    local w = said1X(mia, m0 + 1)
    assert(#w == 1 and w[1].channel == "WHISPER" and w[1].target == ofa.sender and #out == 0, "an officer online: the chest whispered to Ofa")
    assert(rowOf(ofa, 1429, 9201), "Ofa has it")
    leave(mia); leave(ofa)
    said[#said + 1] = "the officers keep Finds and none is online: the finds wait, then go to the first officer online"
  end)
  -- K13: "Share finds with the guild" off on an officer's client: its own finds are no voice (one guild mate's find it
  -- saw too stays one voice, and out of its word), so nothing of where it stood goes out
  isolated({ fmember("Ofa", 0), fmember("Mia", 3) }, function()
    local ofa, mia = fchar("Ofa", 0), fchar("Mia", 3)
    login(ofa, fpol(true, {})); login(mia, fpol())
    tickAll(130)
    ofa.C.Settings().shareFinds = false
    fnoted(ofa, "h", 9201, 1429, 500, 500)
    fnoted(mia, "h", 9201, 1429, 506, 500)
    tickAll(65)
    local e
    for _, x in ipairs(ofa.env.CuteDB.known.finds.list) do if x.id == 9201 then e = x end end
    assert(e and e.v[guidOf("Ofa")] == nil and not ofa.C.Finds.Sure(e), "sharing off: the officer's own find no voice, Mia's alone not sure")
    assert(#ofa.C.Finds:WordParts() == 0, "and nothing of it in the officers' word")
    ofa.C.Settings().shareFinds = nil
    leave(ofa); leave(mia)
    said[#said + 1] = "sharing off: your own finds are no voice, nothing of them in the officers' word"
  end)
  -- K14: the store at its cap of 2,000: a find heard puts the oldest out and keeps its index (no rebuild of 2,000
  -- groups a find): ten new finds make little garbage, and a find heard again is found as it was
  isolated({ fmember("Ann", 3), fmember("Ben", 3) }, function()
    local ann, ben = fchar("Ann", 3), fchar("Ben", 3)
    login(ann, fpol()); login(ben, fpol())
    tickAll(10)
    local F = ben.C.Finds
    local g = guidOf("Ann")
    -- (two voices each: one member's lone finds stop at 300)
    for i = 1, 2000 do
      local en = { k = "h", id = 30000 + i, m = 1443, x = i % 1000, y = 2 + math.floor(i / 1000) * 100 }
      F.Voice(g, en); F.Voice("Player-4242-0F0000AA", en)
    end
    local list = ben.env.CuteDB.known.finds.list
    assert(#list == 2000, "the store full: " .. #list)
    collectgarbage("collect"); collectgarbage("collect")
    collectgarbage("stop")
    local k0 = collectgarbage("count")
    for i = 1, 10 do F.Voice(g, { k = "h", id = 50000 + i, m = 1444, x = i * 30, y = 3 }) end
    local used = collectgarbage("count") - k0
    collectgarbage("restart")
    print(string.format("map K14: ten finds heard into a full store of 2,000: %.1f KB of garbage", used))
    assert(used < 48, string.format("ten finds into a full store: %.1f KB of garbage, the index built again each time", used))
    assert(#list == 2000, "still 2,000")
    local e = F.Voice(guidOf("Ben"), { k = "h", id = 50005, m = 1444, x = 152, y = 4 })
    local n = 0
    for _ in pairs(e.v) do n = n + 1 end
    assert(n == 2 and #list == 2000 and F.Sure(e), "a find heard again found as it was: two voices, sure")
    leave(ann); leave(ben)
    said[#said + 1] = string.format("the store at its cap: ten finds heard put the oldest out with %.1f KB of garbage, the index kept", used)
  end)
  -- K15: an officer's /reload while a find waits out its half hour: the word says it all the same
  isolated({ fmember("Ofa", 0), fmember("Mia", 3), fmember("Ann", 3), fmember("Cy", 3) }, function()
    local closed = { gc_finds = "self" }
    local ofa, mia, ann, cy = fchar("Ofa", 0), fchar("Mia", 3), fchar("Ann", 3), fchar("Cy", 3)
    login(ofa, fpol(true, closed)); login(mia, fpol(nil, closed)); login(ann, fpol(nil, closed)); login(cy, fpol(nil, closed))
    tickAll(130)
    local F = ofa.C.Finds
    local en = { k = "h", id = 9201, m = 1429, x = 500, y = 500 }
    F:Receive(F.Pack(en), mia.sender, true); F:Receive(F.Pack(en), ann.sender, true)
    tickAll(60)
    local db = ofa.env.CuteDB
    leave(ofa)
    local o2 = fchar("Ofa", 0)
    login(o2, db, true)
    tickAll(1900)
    local said2 = false
    for _, m in ipairs(o2.sent) do if m.msg:sub(1, 3) == "1N|" and m.msg:find("fh", 1, true) then said2 = true end end
    assert(said2 and rowOf(cy, 1429, 9201) and rowOf(cy, 1429, 9201).sure, "after the officer's /reload the word says it half an hour on")
    for _, c in ipairs({ o2, mia, ann, cy }) do leave(c) end
    said[#said + 1] = "an officer's /reload keeps the half-hour word"
  end)
  print("map K: " .. table.concat(said, "; "))
end

-- [stage: hud] that stage's tests go right below this line
-- The hud round: Reminders in Cute (docs/superpowers/specs/2026-10-21-reminders-design.md, section 10, case 17). One
-- engine, Remind.lua, copied byte for byte; the Reminders module (id camp, its saved state kept) the master switch over
-- remind.on alone, its section the engine's rows and the light's two.
-- H1: a fresh character: the interact light off until the first-run card says (the engine's default is on and the
-- light changes the game's soft-target settings); the card's Reminders row ticked; Start with it: Reminders on screen.
-- H2: a 0.7 save whose Camp module was off: its kept cuteOff.camp (campBar, the two buffs rows, the light) rewritten,
-- the module follows remind.on alone and the rows go back as kept; on again, Reminders back.
-- H3: QuestBank loaded: its reminders are its own: the section greyed, nothing written.
-- H4: the engine files byte-identical; Reminders eight rows, Quests eight at most.
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1) }, function()
    local said = {}
    local state = {}
    local function client(card) return newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = state, quest = true, card = card })) end
    -- H1
    local c = client(true)
    login(c); tick(c, 3)
    local s = c.env.CuteQuestDB.settings
    local QB = c.addons[2].private
    -- (merge3: the module on by default, so Reminders are on before the card is answered; the light stays off until its
    -- row says)
    assert(QB.Remind and s.remind.v == 2 and s.glow.on == false and s.remind.on == true and c.C.Modules.byId.camp.active, "fresh: the light off, Reminders on with the module (on by default): " .. tostring(s.remind.on))
    local card = c.env.CuteSetupFrame
    assert(card and card:IsShown(), "the first-run card")
    local function row(label) return checkBox(c, function(cb) return cb.label and cb.label:GetText() == label end) end
    assert(row("Reminders"):GetChecked() and row("Interact light"):GetChecked(), "the card: Reminders' row and the light, ticked")
    local start
    for _, b in ipairs(c.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == "Start" then start = b end end
    press(start)
    local ch = c.env.CuteDB.chars["Rone-Forever"]
    assert(ch.modules["Cute_Quest:camp"] == true and s.remind.on == true and s.glow.on == true and (s.cuteOff == nil or s.cuteOff.camp == nil), "Start: the module on, Reminders on screen, the light as its row said")
    local db, qdb = c.env.CuteDB, c.env.CuteQuestDB
    leave(c)
    local d = client()
    d.env.CuteQuestDB = qdb
    login(d, db, true); tickAll(6)
    local ds = d.env.CuteQuestDB.settings
    assert(d.C.Modules.byId.camp.active and ds.remind.on == true and ds.glow.on == true and d.env.QuestBankCampBar and d.env.QuestBankBuffBanner, "after the reload: on, both pieces made")
    said[#said + 1] = "a fresh character: the light off until the card, Start puts Reminders on screen"
    leave(d)
    -- H2
    local o = client()
    o.env.CuteQuestDB = { settings = { cuteDefaults = 2, v544 = true, v600 = true, campBar = false, guide = { on = true, frame = true },
      remind = { camp = true, food = false, bag = true, fire = true, quietInstance = true, buffs = false, sit = true, wood = true, bagChain = true, party = false },
      glow = { on = false, style = "sparkle" }, cuteOff = { camp = { campBar = true, ["remind.buffs"] = true, ["remind.party"] = true, ["glow.on"] = true } } } }
    -- (0.7's Camp module was off by default: a kept light of an account that never chose the module is the engine's
    -- default, not a choice, and stays off until the first-run card's Interact light row; one that chose it, on some
    -- character, gets it back as kept)
    local save07 = o.env.CuteQuestDB
    local function copy(t) if type(t) ~= "table" then return t end local out = {}; for k, v in pairs(t) do out[k] = copy(v) end; return out end
    local fresh07 = copy(save07)
    login(o); tickAll(6)
    local so = o.env.CuteQuestDB.settings
    -- (merge3: the module on by default for a character with nothing saved, as this 0.7 one: Reminders on with it, the
    -- kept switch given back)
    assert(so.remind.buffs == true and so.remind.party == true and so.glow.on == false and so.remind.on == true and so.cuteOff.camp == nil
      and so.remind.never.eat == "Eat", "0.7's kept switch rewritten: the rows back as kept, Reminders on with the module (on by default), the food's switch a Never, the light off until asked")
    o.C.Modules.Set("Cute_Quest:camp", true); tick(o, 1)
    assert(so.remind.on == true and so.cuteOff.camp == nil and so.glow.on == false, "the module on: Reminders back, the light its own")
    o.C.Modules.Set("Cute_Quest:camp", false); tick(o, 1)
    assert(so.remind.on == false and so.remind.buffs == true and so.glow.on == false, "off again: Reminders alone off")
    leave(o)
    local o2 = client()
    o2.env.CuteQuestDB = fresh07
    login(o2, { chars = { ["Alt-Forever"] = { modules = { ["Cute_Quest:camp"] = false } } } }); tickAll(6)
    assert(o2.env.CuteQuestDB.settings.glow.on == true, "a character of the account chose the Camp module once: the light back as kept")
    said[#said + 1] = "a 0.7 save's kept Camp switch rewritten to remind.on alone, its rows back, the light only where the module was chosen"
    leave(o2)
    -- H3
    local q = client()
    local isLoaded = q.env.C_AddOns.IsAddOnLoaded
    q.env.C_AddOns.IsAddOnLoaded = function(x) if x == "QuestBank" then return true, true end return isLoaded(x) end
    local writes = 0
    local rset = { on = true, buffs = true, party = true, camp = true, upkeep = true, class = true, instance = "buffs", never = { eat = "Eat" } }
    local settings = { guide = { on = true, frame = true }, arrow = true, mapIcons = true, pins = true, glow = { on = true, style = "sparkle" }, remind = rset, share = { party = true }, djShow = { boss = true, rare = true, trash = false, other = true } }
    q.env.QuestBankAPI = {
      version = "6.2.0", logReady = true, state = { level = 5, log = {} }, routeNow = { legs = {}, xp = 0, level = 5, t = 0 },
      Settings = function() return settings end, MarkDirty = function() end, Comma = tostring, Short = tostring,
      Model = { Busy = function() return false end }, Data = { CAT = {} }, Quest = { Get = function() return nil end },
      Guide = { Steps = function() return {} end, Text = function(st) return st.text end, TimeToLevel = function() return nil end, MemberSteps = function() return {} end },
      StepFrame = { Menu = function() end, Apply = function() end }, Arrow = { Set = function() end },
      UI = { PlaceGroups = function() return {}, {}, nil, nil, nil end, Candidates = function() return {} end, QuestClick = function() end, QuestTooltip = function() end },
      Target = { Route = function() return { legs = {}, xp = 0, level = 5, t = 0 } end }, Run = { Get = function() return nil end },
      DMap = { Attach = function() end, Refresh = function() end }, Gear = { Attach = function() end, Refresh = function() end, RefreshSoon = function() end },
      Remind = { ROWS = QB.Remind.ROWS, ON_LABEL = QB.Remind.ON_LABEL, Settings = function() return rset end, Hidden = function() return { { "eat", "Eat" } } end,
                 SetRow = function() writes = writes + 1 end, SetNever = function() writes = writes + 1 end, Refresh = function() end },
    }
    login(q); tickAll(5)
    q.C.Modules.Set("Cute_Quest", true); tick(q, 6)
    q.C.Modules.Set("Cute_Quest:camp", true); tick(q, 1)
    q.C.UI:Open("settings", "camp")
    local t = texts(q)
    assert(t:find("QuestBank is loaded: its reminders are its own.", 1, true), "QuestBank loaded: said so:\n" .. t)
    local box = checkBox(q, function(cb) return cb.label and cb.label:GetText() == "Your buffs and weapon" end)
    assert(box and box.__disabled, "its rows greyed")
    click(box)
    q.C.Modules.Set("Cute_Quest:camp", false); tick(q, 1)
    assert(writes == 0 and rset.on == true and settings.glow.on == true, "nothing written: QuestBank's own")
    check(sframe(q), "Reminders, QuestBank loaded")
    said[#said + 1] = "QuestBank loaded: the section greyed, nothing written"
    leave(q)
    -- H4
    for _, f in ipairs({ "Remind.lua", "Camp.lua", "Guide.lua", "StepFrame.lua", "Glow.lua" }) do
      local a = assert(io.open(HERE .. "/../questbank/QuestBank/" .. f, "rb")):read("*a")
      local b = assert(io.open(HERE .. "/Cute_Quest/" .. f, "rb")):read("*a")
      assert(a == b, f .. ": Cute_Quest's copy is QuestBank's, byte for byte (build.py)")
    end
    local r = client()
    login(r); tickAll(6)
    local Mr = r.C.Modules
    for _, key in ipairs({ "Cute_Quest:camp" }) do Mr.Set(key, true) end
    local function rowsOf(id)
      local n = 0
      local col = setmetatable({}, { __index = function(_, k) return function() if k == "Check" or k == "Choice" or k == "Step" or k == "Edit" then n = n + 1 end end end })
      Mr.byId[id].settings(Mr.byId[id], col)
      return n
    end
    assert(rowsOf("camp") == 8, string.format("Reminders eight rows: %d", rowsOf("camp")))
    -- (each row's note under it, DIM; under a row that keeps reminders hidden for good, one DIM line naming them with its
    -- own Show, which brings back that row's alone)
    local RQ = r.addons[2].private.Remind
    RQ.SetNever("eat", "Eat"); RQ.SetNever("sit", "Sit"); RQ.SetNever("buff:168", "Frost Armor")
    r.C.UI:Open("settings", "camp")
    local rt = texts(r)
    for _, note in ipairs({ "In a party, not a raid. Thorns only on the tank.", "Each adds XP on Forever. The sleeping bag's quest line too.", "Ammo and the hearthstone with them." }) do
      assert(rt:find(note, 1, true), "the note under its row: " .. note .. "\n" .. rt)
    end
    assert(rt:find("Hidden: Eat, Sit", 1, true) and rt:find("Hidden: Frost Armor", 1, true) and not rt:find("\nEat\n", 1, true), "one Hidden line a row:\n" .. rt)
    assert(rowsOf("camp") == 8, "still eight rows")
    -- (the Show beside the camp row's line: the visible one level with it)
    local function showOf(words)
      local line
      for _, o in everything() do if o.__kind == "FontString" and o.__shown and o.__text == words and visible(o) and o.__parent and o.__parent.__client == r then line = o end end
      for _, b in ipairs(r.frames) do
        if line and b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == "Show"
          and math.abs((b.__points[1].y or 0) - (line.__points[1].y or 0)) <= 6 then return b end
      end
    end
    assert(showOf("Hidden: Eat, Sit"), "a Show beside the line")
    for _, size in ipairs({ { 1040, 640 }, { 760, 420 } }) do
      sizeAll(r, size[1], size[2])
      r.C.UI:Open("settings", "camp")
      check(sframe(r), string.format("Settings > Reminders with Hidden lines, %dx%d", size[1], size[2]))
    end
    sizeAll(r, 1040, 640)
    r.C.UI:Open("settings", "camp")
    press(showOf("Hidden: Eat, Sit"))
    local nv = RQ.Settings().never
    assert(nv.eat == nil and nv.sit == nil and nv["buff:168"] == "Frost Armor", "its own Show: the camp row's alone back")
    for _, size in ipairs({ { 1040, 640 }, { 760, 420 } }) do
      sizeAll(r, size[1], size[2])
      r.C.UI:Open("settings", "camp")
      check(sframe(r), string.format("Settings > Reminders, %dx%d", size[1], size[2]))
    end
    sizeAll(r, 1040, 640)
    assert(#(r.env.CuteQuestDB.errors or {}) == 0, "no engine error recorded")
    said[#said + 1] = "the engine's five files byte for byte; Reminders eight rows at both sizes"
    leave(r)
    print("hud: " .. table.concat(said, "; "))
  end)
end

-- The hud round, part 2: layout mode (the windows design's section 6, its testing's E): the on-screen pieces moved,
-- scaled, shown and locked from Cute (Layout.lua) over the engine's movers (QB.Movers), each character its own layout.
-- E1 /cute layout: a mover for every piece that is on (the step frame, the arrow, Reminders, Buffs), none for a window
--    nor for a piece that is off; each its name and its scale; the bar at the top's middle (Move frames, Snap, Reset
--    all, Done); the layout checks of the bar and the movers
-- E2 a drag: the 8 px grid from the screen's middle; another mover's edge within 6 px wins; Shift moves freely; the drop
--    writes the engine's place and this character's layout
-- E3 the wheel: 5 % a notch, 50 to 200 %; the arrow's frame in QuestBank's look, its dial (compassSize) in the compass
-- E4 the arrow keys nudge the mover under the mouse by 1 px and take the key; any other key goes on to the game; Esc is
--    Done: hidden, saved, locked, and the account's starting layout written
-- E5 a mover's right-click: Reset, 80 / 100 / 120 / 150 %, Hide and Show (the piece's own switch)
-- E6 a fight: Move frames refused and greyed in the menu; a fight's start ends layout mode, saved
-- E7 the lock: locked by default; the engine's drags ask Cute's lock (the step frame stays); the menu's Lock frames and
--    Settings > Layout's row unlock it (the step frame drags); the minimap always the game's (QB.LayoutLocked)
-- E8 per character: a new character takes the account's starting layout; another's places never written over its
--    own; Copy from takes another's; logout writes back a place the engine moved itself
-- E9 Reset windows: every window at its default size, centred, their kept places gone
-- E10 the game's Edit Mode opens and closes it, taking no key of the game's
-- E11 QuestBank loaded: no mover, nothing of QuestBank's settings written, the menu entry and the rows greyed with
--    "QuestBank is loaded"
-- E12 Settings > Layout at both sizes; Settings > Keys names the Move frames key (the game's Key Bindings)
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1), member("Pim", 3), member("Quill", 3) }, function()
    local said = {}
    local state = {}
    local function client(name, rank) return newClient(charOf({ name, rank or 1, (rank or 1) <= 1 and "Officer" or "Raider", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = state, quest = true })) end
    local function near(a, b) return a and b and math.abs(a - b) < 0.01 end
    local function lastMenu(c) return c.contextMenus[#c.contextMenus] end
    local function entry(list, text) for _, e in ipairs(list or {}) do if e.text == text then return e end end end
    local function cursorAt(c, x, y) c.env.GetCursorPosition = function() return x, y end end
    -- a drag of a mover from a point inside it to a point on the screen
    local function drag(c, mv, toX, toY)
      cursorAt(c, mv.l + 10, mv.t - 10)
      mv.__scripts.OnDragStart(mv)
      cursorAt(c, toX + 10, toY - 10)
      mv.__scripts.OnUpdate(mv, 0.016)
      mv.__scripts.OnDragStop(mv)
    end
    local function up(c)
      login(c); tickAll(6)
      c.C.Modules.Set("Cute_Quest:camp", true); tick(c, 1)
      local QB = c.addons[2].private
      QB.Arrow:Set(true)
      QB.Remind.Refresh()
      return QB
    end
    -- E1
    local c = client("Rone")
    local QB = up(c)
    local L, s = c.C.Layout, c.env.CuteQuestDB.settings
    assert(QB.LayoutLocked == c.env.Cute.Layout.Locked and QB.SetLayoutLocked == c.env.Cute.Layout.SetLocked and L.pieces == QB.Movers, "the engine's lock and movers are Cute's (Bridge.lua)")
    c.env.SlashCmdList.CUTE("layout")
    assert(L.on, "/cute layout: layout mode")
    local shown = {}
    for key, mv in pairs(L.movers) do if mv:IsShown() then shown[#shown + 1] = key .. "=" .. mv.name:GetText() end end
    table.sort(shown)
    assert(table.concat(shown, ", ") == "arrow=Arrow, buffs=Buffs, camp=Reminders, step=Step frame", "a mover for each piece on, none for a window: " .. table.concat(shown, ", "))
    for key, mv in pairs(L.movers) do
      local l, t, w, h = QB.Movers[key].rect()
      assert(near(mv.l, l) and near(mv.t, t) and near(mv:GetWidth(), w) and mv.scaleText:GetText() == "100%", key .. ": over its piece at 100%")
      assert(mv.__bdc and near(mv.__bdc[4], 0.88) and mv.__bdb and near(mv.__bdb[1], 0.42), key .. ": PANEL at 0.88, a 1 px EDGE")
      check(mv, "E1 the " .. key .. " mover")
    end
    local bar = c.env.CuteLayoutBar
    assert(bar and bar:IsShown() and bar.__points[1].point == "TOP" and bar.__points[1].relPoint == "TOP", "the bar at the top's middle")
    local bt = texts(c)
    for _, w in ipairs({ "Move frames", "Snap", "Reset all", "Done" }) do assert(bt:find(w, 1, true), "the bar says " .. w) end
    check(bar, "E1 the layout mode bar")
    -- (/cute diag: each piece, the lock, the mode and the keys, numbers only)
    local d0 = #c.chat
    c.env.SlashCmdList.CUTE("diag")
    local diag = table.concat(c.chat, "\n", d0 + 1)
    -- (merge3: the clock, off, among the pieces)
    assert(diag:find("diag layout: step on 100%, arrow on 100%, camp on 100%, buffs on 100%, clock off 100%; locked yes; mode on; keys nudged 0, done 0, passed 0", 1, true), "/cute diag's layout line:\n" .. diag)
    -- (the render pass: the whole screen in layout mode, the movers over their pieces)
    if LAYOUT_OUT then GEN = GEN + 1; layouts[#layouts + 1] = dumpLayout(c.env.UIParent, "E1 layout mode: the movers over the step frame, the arrow, Reminders and Buffs") end
    said[#said + 1] = "a mover for each of the four pieces on, none for a window; the bar"
    -- E2
    local mv, arrowMv = L.movers.camp, L.movers.arrow
    -- (a spot no other mover's edge is within 6 px of, off the grid: x across, y up)
    local function clear(lo, size, axis)
      for v = lo, lo + 400 do
        local ok = (v - (axis == "x" and 800 or 500)) % 8 ~= 0
        for _, o in pairs(L.movers) do
          if o ~= mv and o:IsShown() then
            local e1, e2 = axis == "x" and o.l or o.t - o.h, axis == "x" and o.l + o.w or o.t
            for _, mine in ipairs({ v, v + size }) do if math.abs(mine - e1) <= 6 or math.abs(mine - e2) <= 6 then ok = false end end
          end
        end
        if ok then return v end
      end
    end
    local gx, gb = clear(300, mv.w, "x"), clear(150, mv.h, "y")
    drag(c, mv, gx, gb + mv.h)
    assert((mv.l - 800) % 8 == 0 and (mv.t - mv.h - 500) % 8 == 0 and math.abs(mv.l - gx) <= 4 and math.abs(mv.t - mv.h - gb) <= 4,
      "snapped to the 8 px grid from the middle: " .. mv.l .. ", " .. mv.t .. " from " .. gx .. ", " .. (gb + mv.h))
    local rp = s.remind.pos
    local l, t, w, h = QB.Movers.camp.rect()
    assert(rp and near(l, mv.l) and near(t, mv.t), "dropped: Reminders moved there")
    local ch = c.env.CuteDB.chars["Rone-Forever"]
    assert(ch.layout and ch.layout.pieces.camp and ch.layout.pieces.camp.point == "CENTER" and near(ch.layout.pieces.camp.x, rp.x - 800), "the drop in this character's layout")
    -- (a spot whose left edge is 3 to 5 px off the arrow's, and no other edge near either of its own)
    local near6
    for _, d in ipairs({ 4, -4, 3, -3, 5, -5 }) do
      local v, ok = arrowMv.l + d, true
      for _, o in pairs(L.movers) do
        if o ~= mv and o:IsShown() then
          for _, e in ipairs({ o.l, o.l + o.w }) do
            for _, mine in ipairs({ v, v + mv.w }) do
              if not (o == arrowMv and e == o.l and mine == v) and math.abs(mine - e) <= 6 then ok = false end
            end
          end
        end
      end
      if ok then near6 = v break end
    end
    assert(near6, "a spot beside the arrow's edge alone")
    drag(c, mv, near6, gb + mv.h)
    assert(mv.l == arrowMv.l, "an edge within 6 px of the arrow's: on it: " .. mv.l .. " vs " .. arrowMv.l)
    c.shift = true
    drag(c, mv, gx, gb + mv.h)
    c.shift = false
    assert(mv.l == gx and mv.t == gb + mv.h, "Shift: free: " .. mv.l .. ", " .. mv.t)
    said[#said + 1] = "a drag snaps to the grid and to an edge within 6 px, Shift frees it; the drop writes the place and the layout"
    -- E3
    for _ = 1, 4 do mv.__scripts.OnMouseWheel(mv, 1) end
    assert(near(s.remind.scale, 1.2) and mv.scaleText:GetText() == "120%" and near(ch.layout.pieces.camp.scale, 1.2), "four notches up: 120%")
    for _ = 1, 40 do mv.__scripts.OnMouseWheel(mv, 1) end
    assert(near(s.remind.scale, 2) and mv.scaleText:GetText() == "200%", "200% at most")
    for _ = 1, 60 do mv.__scripts.OnMouseWheel(mv, -1) end
    assert(near(s.remind.scale, 0.5) and mv.scaleText:GetText() == "50%", "50% at least")
    for _ = 1, 10 do mv.__scripts.OnMouseWheel(mv, 1) end
    assert(s.remind.scale == nil and mv.scaleText:GetText() == "100%", "back at 100%")
    for _ = 1, 10 do arrowMv.__scripts.OnMouseWheel(arrowMv, 1) end
    assert(near(s.arrowScale, 1.5) and near(c.env.QuestBankArrow:GetScale(), 1.5) and arrowMv.scaleText:GetText() == "150%", "the arrow at 150%: its frame, in QuestBank's look")
    s.arrowStyle = "compass"; QB.Arrow:Restyle()
    for _ = 1, 10 do arrowMv.__scripts.OnMouseWheel(arrowMv, -1) end
    assert(s.compassSize == 48 and near(c.env.QuestBankArrow:GetScale(), 1), "the compass: its dial by compassSize, its frame at 100%")
    for _ = 1, 10 do arrowMv.__scripts.OnMouseWheel(arrowMv, 1) end
    assert(s.compassSize == 72 and arrowMv.scaleText:GetText() == "150%", "the compass at 150%: a 72 px dial")
    for _ = 1, 10 do arrowMv.__scripts.OnMouseWheel(arrowMv, -1) end
    s.arrowStyle = "questbank"; QB.Arrow:Restyle()
    said[#said + 1] = "the wheel 5% a notch from 50 to 200%, the arrow's frame or its compass's dial"
    -- E4
    mv.__scripts.OnEnter(mv)
    local l0, t0 = mv.l, mv.t
    bar.__scripts.OnKeyDown(bar, "LEFT")
    assert(mv.l == l0 - 1 and mv.t == t0 and bar.__propagate == false, "LEFT over a mover: 1 px left, the key taken")
    bar.__scripts.OnKeyDown(bar, "UP")
    assert(mv.t == t0 + 1 and near(QB.Movers.camp.rect(), l0 - 1), "UP: 1 px up, the piece with it")
    bar.__scripts.OnKeyDown(bar, "W")
    assert(bar.__propagate == true, "W goes on to the game")
    mv.__scripts.OnLeave(mv)
    bar.__scripts.OnKeyDown(bar, "LEFT")
    assert(mv.l == l0 - 1 and bar.__propagate == true, "no mover under the mouse: the arrow keys are the game's")
    L.SetLocked(false)
    bar.__scripts.OnKeyDown(bar, "ESCAPE")
    assert(not L.on and not mv:IsShown() and not bar:IsShown() and ch.layout.locked == true, "Esc: Done, hidden, locked")
    local def = c.env.CuteDB.layoutDefault
    assert(def and def.pieces.camp and near(def.pieces.camp.x, ch.layout.pieces.camp.x), "Done: the account's starting layout")
    said[#said + 1] = "the arrow keys nudge the mover under the mouse and the rest go on; Esc is Done, locked, the starting layout written"
    -- E5
    L.Enter()
    local step = L.movers.step
    step.__scripts.OnClick(step, "RightButton")
    local m = lastMenu(c)
    assert(m[1].kind == "title" and m[1].text == "Step frame" and entry(m, "Reset") and entry(m, "80%") and entry(m, "100%  (now)") and entry(m, "120%") and entry(m, "150%") and entry(m, "Hide"),
      "the mover's menu: Reset, 80/100/120/150%, Hide")
    entry(m, "120%").set()
    assert(near(s.guide.scale, 1.2) and step.scaleText:GetText() == "120%", "120%: the step frame's scale")
    entry(m, "Reset").set()
    assert(s.guide.x == nil and near(s.guide.scale or 1, 1) and step.scaleText:GetText() == "100%", "Reset: its default place at 100%")
    entry(m, "Hide").set()
    assert(s.guide.frame == false and not c.env.QuestBankStep:IsShown() and step:IsShown() and near(step.__alpha, 0.5) and step.scaleText:GetText():find("Hidden", 1, true), "Hide: the piece's own switch off, its mover dimmed")
    step.__scripts.OnClick(step, "RightButton")
    entry(lastMenu(c), "Show").set()
    assert(s.guide.frame == true and c.env.QuestBankStep:IsShown() and near(step.__alpha, 1), "Show: back")
    said[#said + 1] = "a mover's menu: Reset, four sizes, Hide and Show"
    -- E6
    c.combat = true
    fire(c, "PLAYER_REGEN_DISABLED")
    assert(not L.on and not step:IsShown(), "a fight's start ends it")
    local n0 = #c.chat
    assert(L.Enter() == false and table.concat(c.chat, "\n", n0 + 1):find("after combat", 1, true), "in a fight: refused, said")
    c.C.UI.mini.__scripts.OnClick(c.C.UI.mini, "RightButton")
    local mm = lastMenu(c)
    local move = entry(mm, "Move frames...")
    assert(move and move.off and entry(mm, "Lock frames"), "the menu: Lock frames, and Move frames... greyed in a fight")
    c.combat = false
    said[#said + 1] = "a fight ends it saved; in one it is refused and greyed"
    -- E7
    local sf = c.env.QuestBankStep
    local starts = 0
    rawset(sf, "StartMoving", function() starts = starts + 1 end)
    assert(L.Locked("step") and QB.LayoutLocked("step") and QB.LayoutLocked("minimap"), "locked by default; the minimap always the game's")
    sf.__scripts.OnDragStart(sf)
    assert(starts == 0, "locked: the step frame stays")
    c.C.UI.mini.__scripts.OnClick(c.C.UI.mini, "RightButton")
    local lock = entry(lastMenu(c), "Lock frames")
    assert(lock.kind == "check" and lock.get() == true, "the menu's Lock frames, ticked")
    lock.set()
    assert(not L.Locked("step") and ch.layout.locked == false, "unticked: unlocked")
    sf.__scripts.OnDragStart(sf); sf.__scripts.OnDragStop(sf)
    assert(starts == 1, "unlocked: the step frame drags where it stands")
    s.guide.x, s.guide.y = nil, nil; QB.StepFrame.Apply()
    c.C.UI:Open("settings", "layout")
    local row = checkBox(c, function(cb) return cb.label and cb.label:GetText() == "Lock frames" end)
    assert(row and not row:GetChecked(), "Settings > Layout: Lock frames, unticked")
    click(row)
    assert(L.Locked("step"), "ticked in Settings: locked")
    said[#said + 1] = "locked by default; the engine's drag asks it; the menu and Settings unlock it; the minimap the game's"
    -- E8
    local db, qdb = c.env.CuteDB, c.env.CuteQuestDB
    local ronePos = { x = s.remind.pos.x, y = s.remind.pos.y }
    leave(c)
    local p = client("Pim", 3)
    p.env.CuteQuestDB = qdb
    login(p, db, true); tickAll(6)
    local pch = p.env.CuteDB.chars["Pim-Forever"]
    local ps = p.env.CuteQuestDB.settings
    assert(pch.layout and pch.layout.locked == true and near(pch.layout.pieces.camp.x, def.pieces.camp.x) and near(ps.remind.pos.x, ronePos.x), "a new character: the account's starting layout, locked")
    local PL = p.C.Layout
    p.C.Modules.Set("Cute_Quest:camp", true); tick(p, 1)
    assert(PL.Enter() and PL.movers.camp:IsShown(), "Pim's layout mode, Reminders on")
    drag(p, PL.movers.camp, 200, 200)
    PL.Done()
    local pimPos = { x = ps.remind.pos.x, y = ps.remind.pos.y }
    assert(not near(pimPos.x, ronePos.x), "Pim moved Reminders")
    leave(p)
    local r2 = client("Rone")
    r2.env.CuteQuestDB = qdb
    login(r2, db, true); tickAll(6)
    local rs = r2.env.CuteQuestDB.settings
    assert(near(rs.remind.pos.x, ronePos.x) and near(rs.remind.pos.y, ronePos.y), "Rone again: Rone's own places, never Pim's")
    local others = r2.C.Layout.Others()
    assert(#others == 1 and others[1][1] == "Pim-Forever", "Copy from: the other characters with a layout")
    r2.C.Layout.CopyFrom("Pim-Forever")
    assert(near(rs.remind.pos.x, pimPos.x) and near(r2.env.CuteDB.chars["Rone-Forever"].layout.pieces.camp.x, pimPos.x - 800), "Copy from: Pim's places, kept as Rone's")
    rs.arrowPos = { "TOP", -333, -444 }
    fire(r2, "PLAYER_LOGOUT")
    local ap = r2.env.CuteDB.chars["Rone-Forever"].layout.pieces.arrow
    assert(ap.point == "TOP" and ap.x == -333 and ap.y == -444, "logout: a place the engine moved itself written back")
    said[#said + 1] = "a new character takes the starting layout; each keeps its own; Copy from; logout writes back"
    -- E9
    r2.C.UI:Open("quests")
    local Lw = qwin(r2)
    Lw.frame.__left, Lw.frame.__top = 200, 700
    Lw.head.__scripts.OnDragStart(Lw.head); Lw.head.__scripts.OnDragStop(Lw.head)
    Lw.frame:SetSize(900, 500)
    assert(r2.env.CuteDB.winPos and r2.env.CuteDB.winPos.quests, "L's place kept")
    r2.C.UI:Open("settings", "layout")
    local reset
    for _, b in ipairs(r2.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == "Reset windows" then reset = b end end
    press(reset)
    local sp = r2.C.UI.SPEC.quests
    assert(r2.env.CuteDB.winPos == nil and r2.env.CuteDB.pos == nil and Lw.frame.__w == sp.w and Lw.frame.__h == sp.h and Lw.frame.__points[1].point == "CENTER", "Reset windows: default size, centred, no kept place")
    said[#said + 1] = "Reset windows: every window at its default size, centred"
    -- E10
    r2.env.EventRegistry:TriggerEvent("EditMode.Enter")
    local RL = r2.C.Layout
    assert(RL.on and RL.from == "edit" and RL.movers.step:IsShown() and r2.env.CuteLayoutBar.__keyboard == false, "the game's Edit Mode: the movers, no key taken")
    r2.env.EventRegistry:TriggerEvent("EditMode.Exit")
    assert(not RL.on and not RL.movers.step:IsShown(), "its exit: done")
    -- the Move frames key (Bindings.xml, the game's Key Bindings under Cute)
    local bindings = assert(io.open(HERE .. "/Cute/Bindings.xml")):read("*a")
    assert(bindings:find('<Binding name="CUTE_LAYOUT" category="BINDING_HEADER_CUTE">Cute.Layout.Toggle()</Binding>', 1, true) and r2.env.BINDING_NAME_CUTE_LAYOUT == "Move frames", "the Move frames key")
    r2.env.Cute.Layout.Toggle()
    assert(RL.on and RL.from == nil and r2.env.CuteLayoutBar.__keyboard == true, "the key: layout mode, the bar taking keys")
    r2.env.Cute.Layout.Toggle()
    assert(not RL.on, "again: done")
    said[#said + 1] = "the game's Edit Mode opens and closes it; so does the Move frames key"
    -- E12
    for _, size in ipairs({ { 1040, 640 }, { 760, 420 } }) do
      sizeAll(r2, size[1], size[2])
      r2.C.UI:Open("settings", "layout")
      local t = texts(r2)
      assert(t:find("The step frame, the arrow, Reminders, Buffs and the clock. Windows always move by their header.", 1, true) and t:find("Snap to the grid", 1, true), "Settings > Layout's rows:\n" .. t)
      check(sframe(r2), string.format("Settings > Layout, %dx%d", size[1], size[2]))
      r2.C.UI:Open("settings", "keys")
      assert(texts(r2):find("Move frames", 1, true), "Settings > Keys: the Move frames key")
      check(sframe(r2), string.format("Settings > Keys, %dx%d", size[1], size[2]))
    end
    sizeAll(r2, 1040, 640)
    assert(#(r2.env.CuteQuestDB.errors or {}) == 0, "no engine error recorded")
    said[#said + 1] = "Settings > Layout and Keys at both sizes"
    leave(r2)
    -- E11
    local q = client("Quill", 3)
    local isLoaded = q.env.C_AddOns.IsAddOnLoaded
    q.env.C_AddOns.IsAddOnLoaded = function(x) if x == "QuestBank" then return true, true end return isLoaded(x) end
    local settings = { guide = { on = true, frame = true, scale = 1 }, arrow = true, remind = { on = true }, share = { party = true } }
    local snapshot = {}
    local function keysOf(t, pre) for k, v in pairs(t) do snapshot[pre .. tostring(k)] = type(v) == "table" and "table" or v; if type(v) == "table" then keysOf(v, pre .. tostring(k) .. ".") end end end
    keysOf(settings, "")
    q.env.QuestBankAPI = {
      version = "6.2.0", logReady = true, state = { level = 5, log = {} }, routeNow = { legs = {}, xp = 0, level = 5, t = 0 },
      Settings = function() return settings end, MarkDirty = function() end, Comma = tostring, Short = tostring,
      Model = { Busy = function() return false end }, Data = { CAT = {} }, Quest = { Get = function() return nil end },
      Guide = { Steps = function() return {} end, Text = function(st) return st.text end, TimeToLevel = function() return nil end, MemberSteps = function() return {} end },
      StepFrame = { Menu = function() end, Apply = function() end }, Arrow = { Set = function() end },
      UI = { PlaceGroups = function() return {}, {}, nil, nil, nil end, Candidates = function() return {} end, QuestClick = function() end, QuestTooltip = function() end },
      Target = { Route = function() return { legs = {}, xp = 0, level = 5, t = 0 } end }, Run = { Get = function() return nil end },
      DMap = { Attach = function() end, Refresh = function() end }, Gear = { Attach = function() end, Refresh = function() end, RefreshSoon = function() end },
      Remind = { ROWS = QB.Remind.ROWS, ON_LABEL = QB.Remind.ON_LABEL, Settings = function() return settings.remind end, Hidden = function() return {} end,
                 SetRow = function() end, SetNever = function() end, Refresh = function() end },
    }
    login(q); tickAll(5)
    local QL = q.C.Layout
    assert(QL.pieces == nil and QL.Why() == "QuestBank is loaded: its frames are its own.", "QuestBank loaded: no pieces")
    n0 = #q.chat
    q.env.SlashCmdList.CUTE("layout")
    assert(not QL.on and table.concat(q.chat, "\n", n0 + 1):find("QuestBank is loaded", 1, true), "/cute layout says why")
    n0 = #q.chat
    q.env.EventRegistry:TriggerEvent("EditMode.Enter")
    assert(not QL.on and #q.chat == n0, "the game's Edit Mode: nothing to move, nothing said")
    q.env.EventRegistry:TriggerEvent("EditMode.Exit")
    q.C.UI.mini.__scripts.OnClick(q.C.UI.mini, "RightButton")
    assert(entry(lastMenu(q), "Move frames...").off, "the menu's Move frames... greyed")
    q.C.UI:Open("settings", "layout")
    assert(texts(q):find("QuestBank is loaded: its frames are its own.", 1, true), "Settings > Layout says so")
    local qrow = checkBox(q, function(cb) return cb.label and cb.label:GetText() == "Lock frames" end)
    assert(qrow and qrow.__disabled, "its rows greyed")
    check(sframe(q), "Settings > Layout, QuestBank loaded")
    fire(q, "PLAYER_LOGOUT")
    local after = {}
    for k in pairs(snapshot) do after[k] = true end
    local function same(t, pre) for k, v in pairs(t) do local key = pre .. tostring(k); assert(snapshot[key] ~= nil and (type(v) == "table" or snapshot[key] == v), "QuestBank's setting " .. key .. " untouched"); if type(v) == "table" then same(v, key .. ".") end end end
    same(settings, "")
    said[#said + 1] = "QuestBank loaded: no mover, nothing of its settings written, the entry and the rows greyed"
    leave(q)
    print("hud layout: " .. table.concat(said, "; "))
  end)
end

-- The hud review: the Reminders module is Reminders' and Buffs' only master. H5 the module on with remind.on left off
-- (a 0.7 camp bar switch, a mover's Hide before this): on at the load. H6 the first-run card's Reminders row unticked
-- with the light ticked: wherever the module ends up, Reminders follow it. H7 a mover's Hide on Reminders turns the
-- module off and Show on, Buffs shown while it is off turns it on too, and the next Move frames has the mover again
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1) }, function()
    local said = {}
    local state = {}
    local function client(card) return newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = state, quest = true, card = card })) end
    local function lastMenu(c) return c.contextMenus[#c.contextMenus] end
    local function entry(list, text) for _, e in ipairs(list or {}) do if e.text == text then return e end end end
    -- H5
    local c = client()
    c.env.CuteQuestDB = { settings = { cuteDefaults = 2, v544 = true, v600 = true, campBar = false, guide = { on = true, frame = true },
      remind = { v = 2, on = false, never = {} }, glow = { on = false, style = "sparkle" } } }
    login(c, { chars = { ["Rone-Forever"] = { modules = { ["Cute_Quest:camp"] = true } } } }); tickAll(6)
    local s = c.env.CuteQuestDB.settings
    assert(c.C.Modules.byId.camp.active and s.remind.on == true and s.campBar == true, "the module on: Reminders on screen, whatever was left off: " .. tostring(s.remind.on))
    said[#said + 1] = "the module on: Reminders on, whatever was left off"
    -- H7
    local QB = c.addons[2].private
    QB.Remind.Refresh()
    local L = c.C.Layout
    assert(L.Enter() and L.movers.camp:IsShown() and L.movers.buffs:IsShown(), "layout mode: Reminders and Buffs")
    local mv, bmv = L.movers.camp, L.movers.buffs
    mv.__scripts.OnClick(mv, "RightButton")
    entry(lastMenu(c), "Hide").set()
    assert(not c.C.Modules.byId.camp.active and s.remind.on == false and bmv.scaleText:GetText():find("Hidden", 1, true), "Hide on Reminders: the module off, Buffs' mover says so too")
    bmv.__scripts.OnClick(bmv, "RightButton")
    entry(lastMenu(c), "Show").set()
    assert(c.C.Modules.byId.camp.active and s.remind.on == true and mv.scaleText:GetText() == "100%", "Show on Buffs: the module on, both back")
    mv.__scripts.OnClick(mv, "RightButton"); entry(lastMenu(c), "Hide").set()
    mv.__scripts.OnClick(mv, "RightButton"); entry(lastMenu(c), "Show").set()
    assert(c.C.Modules.byId.camp.active and s.remind.on == true, "Hide and Show on Reminders: the module off and on")
    mv.__scripts.OnClick(mv, "RightButton"); entry(lastMenu(c), "Hide").set()
    L.Done()
    c.C.Modules.Set("Cute_Quest:camp", true); tick(c, 1)
    assert(s.remind.on == true and L.Enter() and L.movers.camp:IsShown(), "the module on again: Reminders back, its mover at the next Move frames")
    L.Done()
    said[#said + 1] = "a mover's Hide and Show are the module's"
    leave(c)
    -- H6
    local d = client(true)
    login(d); tick(d, 3)
    local function row(label) return checkBox(d, function(cb) return cb.label and cb.label:GetText() == label end) end
    local rem = row("Reminders")
    assert(rem and rem:GetChecked() and row("Interact light"):GetChecked(), "the card: Reminders' row and the light, ticked")
    click(rem)
    local start
    for _, b in ipairs(d.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == "Start" then start = b end end
    press(start)
    local db, qdb = d.env.CuteDB, d.env.CuteQuestDB
    leave(d)
    local e = client()
    e.env.CuteQuestDB = qdb
    login(e, db, true); tickAll(6)
    local es = e.env.CuteQuestDB.settings
    assert((e.C.Modules.byId.camp.active == true) == (es.remind.on == true), "after the reload: Reminders follow the module: " .. tostring(e.C.Modules.byId.camp.active) .. " / " .. tostring(es.remind.on))
    said[#said + 1] = "the card's unticked Reminders: Reminders follow the module"
    leave(e)
    print("hud review: " .. table.concat(said, "; "))
  end)
end

-- [stage: merge3] that stage's tests go right below this line
----------------------------------------------------------------------------
-- The third merge round: what the cards, map and hud rounds left for the merge, Cute's side.
-- P1. The first-run card's row is "Reminders" (QuestBank loaded: "its step frame, arrow and Reminders are its own."), and
--     it alone chooses the Camp module: unticked with the light ticked, the module off and the light on; ticked with
--     the light unticked, the module on, Reminders on screen and the light off
-- P2. Cute_Quest's camp module starts on (its default kept, the one module addon's default Cute keeps): a character who
--     answers the card Not now has Reminders all the same; another module addon's default is dropped; no module takes
--     the id layout (Settings > Layout's)
-- P3. The dashboard reads what Reminders reads: talents_free from the talent frame's own question (HasUnspentTalentPoints:
--     points waiting while the old count reads 0 are 1, none are 0), bags_free the general bags' free slots (a
--     profession's bag left out), and your own row's Ready "gaps" at best while Before the pull shows something, its
--     names in the tooltip, what is sent unchanged
-- P4. Cute's band draws the step frame's line (G.Reminder) under the next steps: its words and minutes; a click shows its
--     place on the arrow, a right-click is Remind's menu, its tooltip Remind's; drawn again when the line changes. The
--     minimap's Alt-drag stays (Cute's lock keeps it the game's); the clock is a piece of layout mode: its mover, its
--     place kept, its drag held by the lock
----------------------------------------------------------------------------
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1) }, function()
    local said = {}
    local state = {}
    local function client(card, extra)
      local o = { modules = { "Cute_Quest" }, addonState = state, quest = true, card = card }
      for k, v in pairs(extra or {}) do o[k] = v end
      return newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, o))
    end
    local function button(c, label) for _, b in ipairs(c.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == label then return b end end end
    local function row(c, label) return checkBox(c, function(cb) return cb.label and cb.label:GetText() == label end) end
    -- P1
    local c = client(true)
    login(c); tick(c, 3)
    assert(c.env.CuteSetupFrame and c.env.CuteSetupFrame:IsShown() and row(c, "Reminders") and row(c, "Interact light"), "the card's rows: Reminders and Interact light")
    do
      local q = c.C.API.QuestSetup
      c.C.API.QuestSetup = nil
      local line
      for _, r in ipairs(c.C.Setup.Rows()) do if r.id == "dormant" then line = r.label end end
      c.C.API.QuestSetup = q
      assert(line == "QuestBank is loaded: its step frame, arrow and Reminders are its own.", "QuestBank loaded: the card's line: " .. tostring(line))
    end
    check(c.env.CuteSetupFrame, "merge3 the setup card's Reminders row")
    click(row(c, "Reminders"))
    press(button(c, "Start"))
    local ch, s = c.env.CuteDB.chars["Rone-Forever"], c.env.CuteQuestDB.settings
    assert(ch.modules["Cute_Quest:camp"] == false and s.glow.on == true, "Reminders unticked, the light ticked: the module off, the light on: " .. tostring(ch.modules["Cute_Quest:camp"]))
    leave(c)
    local d = client(true)
    login(d); tick(d, 3)
    click(row(d, "Interact light"))
    press(button(d, "Start"))
    ch, s = d.env.CuteDB.chars["Rone-Forever"], d.env.CuteQuestDB.settings
    assert(ch.modules["Cute_Quest:camp"] == true and s.remind.on == true and s.glow.on == false, "Reminders ticked, the light unticked: the module on, Reminders on screen, the light off")
    leave(d)
    said[#said + 1] = "the card's Reminders row alone chooses the module; the light its own"
    -- P2
    local e = client(true)
    login(e); tick(e, 3)
    press(button(e, "Not now"))
    tickAll(2)
    local es = e.env.CuteQuestDB.settings
    assert(e.C.Modules.byId.camp.active and e.C.Modules.byId.camp.default == true and es.remind.on == true and (e.env.CuteDB.chars["Rone-Forever"].modules or {})["Cute_Quest:camp"] == nil,
      "Not now: Reminders on by the module's default, nothing chosen")
    assert(e.env.Cute:RegisterModule({ id = "probe", addon = "Cute_Probe", title = "Probe", default = true }) and e.C.Modules.byId.probe.default == nil and not e.C.Modules.byId.probe.active,
      "another module addon's default dropped")
    assert(e.C:RegisterModule({ id = "layout", title = "Layout", builtin = true }) == false and e.env.Cute:RegisterModule({ id = "layout", addon = "Cute_Probe", title = "Layout" }) == false,
      "no module takes the id layout")
    leave(e)
    said[#said + 1] = "Reminders on for a character who answers Not now; another addon's default dropped; layout reserved"
    -- P3
    local f = client(false, { talents = 0 })
    local has = true
    f.env.C_ClassTalents = { HasUnspentTalentPoints = function() return has end }
    login(f); tickAll(6)
    local S = f.C.Sample
    S:Read("talents_free")
    assert(S:Value("talents_free") == 1, "points waiting, the old count 0: 1: " .. tostring(S:Value("talents_free")))
    f.o.talents = 3
    S:Read("talents_free")
    assert(S:Value("talents_free") == 3, "the count where the old call gives one: " .. tostring(S:Value("talents_free")))
    has = false
    S:Read("talents_free")
    assert(S:Value("talents_free") == 0, "none waiting: 0, whatever the old call says")
    local QBf = f.addons[2].private
    local saved = f.env.C_Container.GetContainerNumFreeSlots
    f.env.C_Container.GetContainerNumFreeSlots = function(b) if b == 3 then return 6, 32 end return b == 0 and 4 or 2, 0 end
    S:Read("bags_free")
    assert(S:Value("bags_free") == 10 and QBf.API.FreeSlots() == 10, "the general bags' free slots, a herb bag's left out: " .. tostring(S:Value("bags_free")))
    f.env.C_Container.GetContainerNumFreeSlots = saved
    S:Read("bags_free")
    S:Read("ready")
    local sent = S:Value("ready")
    f.C.UI:Open("prog")
    local own = rowOf(f, "Rone")
    local cell = own and cellOf(own, "ready")
    assert(cell, "your own row's Ready")
    local before = cell.label:GetText()
    local pull = QBf.Remind.Pull
    QBf.Remind.Pull = function() return { { name = "Elixir of the Mongoose" }, { name = "Well Fed" } }, true end
    f.C.UI:Draw()
    own = rowOf(f, "Rone"); cell = cellOf(own, "ready")
    assert(cell.label:GetText() == (before == "ready" and "gaps" or before), "Before the pull shows two: your Ready gaps at best: " .. tostring(before) .. " -> " .. tostring(cell.label:GetText()))
    assert(tipOf(cell):find("Before the pull: Elixir of the Mongoose, Well Fed.", 1, true), "its tooltip names them")
    assert(S:Value("ready") == sent, "what is sent unchanged")
    QBf.Remind.Pull = function() return {}, false end
    f.C.UI:Draw()
    own = rowOf(f, "Rone"); cell = cellOf(own, "ready")
    assert(cell.label:GetText() == before and not tipOf(cell):find("Before the pull", 1, true), "off: as it was")
    QBf.Remind.Pull = pull
    check(f.C.UI.frame, "merge3 Prog, your own Ready")
    leave(f)
    said[#said + 1] = "talents_free and bags_free read what Reminders read; your own Ready waits on Before the pull"
    -- P4
    local g = client(false)
    login(g); tickAll(6)
    local QB = g.addons[2].private
    local cur = { text = "Train: 2 new spells \194\183 Llane Beshere", tex = 131146, mins = 3, word = "3 min", name = "Training", why = "Your trainer has new spells.",
      go = { name = "Llane Beshere", c = 0, wx = -8918, wy = -208 }, clickWord = "show Llane Beshere on the arrow" }
    local reminder = QB.Guide.Reminder
    QB.Guide.Reminder = function() return cur end
    local went, menued, tipped
    local go, menu, tip = QB.Remind.Go, QB.Remind.Menu, QB.Remind.Tip
    QB.Remind.Go = function(rec) went = rec end
    QB.Remind.Menu = function(b) menued = b.rec end
    QB.Remind.Tip = function(_, rec) tipped = rec end
    g.C.UI:Open("quests")
    local L = qwin(g)
    local rr = L.bandKit and L.bandKit.remind
    assert(rr and rr:IsShown() and rr.text:GetText() == cur.text and rr.mins:GetText() == "3 min", "the band: the step frame's line, its words and minutes:\n" .. texts(g))
    press(rr)
    assert(went == cur, "its click shows its place on the arrow")
    rr.__scripts.OnClick(rr, "RightButton")
    assert(menued == cur, "its right-click: Remind's menu")
    rr.__scripts.OnEnter(rr)
    assert(tipped == cur, "its tooltip: Remind's")
    check(L.frame, "merge3 the Quests band with the step frame's line")
    sizeAll(g, 760, 420); g.C.UI:Open("quests")
    check(L.frame, "merge3 the Quests band with the step frame's line, 760x420")
    sizeAll(g, 1040, 640)
    local nxt = { text = "Learn the flight path: Sentinel Hill", tex = 132239, atlas = "FlightPath", desat = true, mins = 2, word = "2 min", name = "Flight path" }
    cur = nxt
    QB.StepFrame.RemindChanged(nxt)
    tick(g, 1) -- (a window's refresh: once a second at most, UI:Refresh)
    assert(rr:IsShown() and rr.text:GetText() == nxt.text, "the line changed: the band drawn again")
    cur = nil
    QB.StepFrame.RemindChanged(nil)
    tick(g, 1)
    assert(not rr:IsShown(), "no line: none in the band")
    QB.Guide.Reminder, QB.Remind.Go, QB.Remind.Menu, QB.Remind.Tip = reminder, go, menu, tip
    -- the minimap stays the game's under Cute's lock
    local MC = g.env.MinimapCluster
    local moves = 0
    rawset(MC, "StartMoving", function() moves = moves + 1 end)
    local alt = g.env.IsAltKeyDown
    g.env.IsAltKeyDown = function() return true end
    QB.Mini.DragStart("LeftButton")
    assert(moves == 0 and not QB.Mini.dragging and g.C.Layout.Locked("minimap"), "the minimap's Alt-drag: Cute's lock keeps it the game's")
    g.env.IsAltKeyDown = alt
    -- the clock: a piece of layout mode
    local Ly = g.C.Layout
    QB:Settings().clock.show = true; QB.Timer.Apply()
    local clockF = QB.Timer.frame
    assert(clockF and clockF:IsShown() and Ly.pieces.clock == QB.Movers.clock, "the clock shown, its mover Cute's")
    local drags = 0
    rawset(clockF, "StartMoving", function() drags = drags + 1 end)
    clockF.__scripts.OnDragStart(clockF); clockF.__scripts.OnDragStop(clockF)
    assert(drags == 0, "locked: the clock stays")
    assert(Ly.Enter() and Ly.movers.clock and Ly.movers.clock:IsShown() and Ly.movers.clock.name:GetText() == "Clock", "Move frames: a mover for the clock")
    check(Ly.movers.clock, "merge3 the clock's mover")
    QB.Movers.clock.move(300, 500)
    Ly.Done()
    assert(Ly.Get().pieces.clock and Ly.Get().pieces.clock.point == "CENTER", "Done: its place in this character's layout")
    local d0 = #g.chat
    g.env.SlashCmdList.CUTE("diag")
    assert(table.concat(g.chat, "\n", d0 + 1):find("clock on 100% moved", 1, true), "/cute diag names the clock")
    Ly.SetLocked(false)
    clockF.__scripts.OnDragStart(clockF); clockF.__scripts.OnDragStop(clockF)
    assert(drags == 1, "unlocked: the clock drags")
    Ly.SetLocked(true)
    QB:Settings().clock.show = false; QB.Timer.Apply()
    assert(#(g.env.CuteQuestDB.errors or {}) == 0, "no engine error recorded")
    leave(g)
    said[#said + 1] = "the band draws the step frame's line (click, right-click, tooltip, drawn again); the minimap the game's; the clock a piece of layout mode"
    print("merge3: " .. table.concat(said, "; "))
  end)
end
----------------------------------------------------------------------------
-- The merge3 review's findings, Cute's side.
-- P5. Your own Ready and its tooltip agree while Before the pull shows something: from no gap (durability 80%, potions
--     in the bags) the cell reads "gaps" and the tooltip names the pull in place of "No gaps."; drawn again when Before
--     the pull starts and when it ends (Reminders' refresh tells Band.lua), with no other draw
-- P6. With the addon QuestBank loaded, Cute's band follows QuestBank's step-frame line: a hook after QuestBank's own
--     RemindChanged (hooksecurefunc, its function left as it is) draws the band again, its minutes and its going
-- P7. The setup card's light row starts from the light, never from the Camp module's choice: on, ticked (a 0.8
--     character who unticked Camp keeps the light through Start); off only until the card says (a fresh install's Not
--     now, then the menu's card), ticked; turned off in Settings > Reminders, unticked
-- P8. Under Cute's lock the minimap's place is Edit Mode's: a place kept from an Alt-drag of 0.8 let go at the first
--     apply, never put back; a Ctrl-wheel keeps the size alone
-- P9. A card's toast clears the clock strip at 100%, 150% and 200%; the clock hidden, the toast at its own place
----------------------------------------------------------------------------
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  isolated({ member("Rone", 1) }, function()
    local said = {}
    local state = {}
    local function client(card, extra)
      local o = { modules = { "Cute_Quest" }, addonState = state, quest = true, card = card }
      for k, v in pairs(extra or {}) do o[k] = v end
      return newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, o))
    end
    local function button(c, label) for _, b in ipairs(c.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == label then return b end end end
    local function row(c, label) return checkBox(c, function(cb) return cb.label and cb.label:GetText() == label end) end
    -- P5
    local h = client(false)
    login(h); tickAll(6)
    local Sh = h.C.Sample
    Sh:Read("ready")
    assert(Sh:Value("ready") == 2, "no gap: durability 80%, potions in the bags: " .. tostring(Sh:Value("ready")))
    local QBh = h.addons[2].private
    h.C.UI:Open("prog")
    local function own() return cellOf(rowOf(h, "Rone"), "ready") end
    assert(own() and own().label:GetText() == "ready", "your Ready: ready")
    local flask = false
    local pull = QBh.Remind.Pull
    QBh.Remind.Pull = function() if flask then return { { name = "Flask of the Titans" } }, true end return {}, false end
    -- a ready check: Before the pull shows a flask, and Reminders' refresh tells the step frame (Remind.lua flushNow)
    flask = true
    QBh.Remind.Refresh()
    tick(h, 1.5)
    assert(own().label:GetText() == "gaps", "Before the pull shows a flask: your Ready gaps, drawn again with no other draw: " .. tostring(own().label:GetText()))
    local tip = tipOf(own())
    assert(not tip:find("No gaps.", 1, true) and tip:find("Before the pull: Flask of the Titans.", 1, true), "its tooltip agrees with the cell:\n" .. tip)
    check(h.C.UI.frame, "merge3 Prog, your own Ready gaps before the pull")
    -- the pull over (10 s after the ready check ends, R.PullEnd): ready again, drawn again
    flask = false
    QBh.Remind.Refresh()
    tick(h, 1.5)
    tip = tipOf(own())
    assert(own().label:GetText() == "ready" and tip:find("No gaps.", 1, true) and not tip:find("Before the pull", 1, true), "the pull over: ready and No gaps.:\n" .. tip)
    QBh.Remind.Pull = pull
    leave(h)
    said[#said + 1] = "your own Ready and its tooltip agree before the pull, drawn again as it starts and ends"
    -- P6
    local q = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    local isLoaded = q.env.C_AddOns.IsAddOnLoaded
    q.env.C_AddOns.IsAddOnLoaded = function(x) if x == "QuestBank" then return true, true end return isLoaded(x) end
    local settings = { guide = { on = true, frame = true }, arrow = true, glow = { on = true, style = "sparkle" }, remind = { on = true }, share = { party = true }, djShow = { boss = true, rare = true, trash = false, other = true } }
    local line = { text = "Train: 2 new spells \194\183 Llane Beshere", tex = 131146, mins = 3, word = "3 min", name = "Training" }
    local told = 0
    q.env.QuestBankAPI = {
      version = "6.3.0", logReady = true, state = { level = 5, log = {} }, routeNow = { legs = {}, xp = 0, level = 5, t = 0 },
      Settings = function() return settings end, MarkDirty = function() end, Comma = tostring, Short = tostring,
      Model = { Busy = function() return false end }, Data = { CAT = {} }, Quest = { Get = function() return nil end },
      Guide = { Steps = function() return { { kind = "objective", qid = 7, text = "Kill Kobold Vermin 3/8" } } end, Text = function(st) return st.text end,
        TimeToLevel = function() return nil end, MemberSteps = function() return {} end, Reminder = function() return line end },
      StepFrame = { Menu = function() end, Apply = function() end, RemindChanged = function() told = told + 1 end }, Arrow = { Set = function() end },
      UI = { PlaceGroups = function() return {}, {}, nil, nil, nil end, Candidates = function() return {} end, QuestClick = function() end, QuestTooltip = function() end },
      Target = { Route = function() return { legs = {}, xp = 0, level = 5, t = 0 } end }, Run = { Get = function() return nil end },
      DMap = { Attach = function() end, Refresh = function() end }, Gear = { Attach = function() end, Refresh = function() end, RefreshSoon = function() end },
      Remind = { Pull = function() return {}, false end },
    }
    local API = q.env.QuestBankAPI
    local sfChanged = API.StepFrame.RemindChanged
    login(q); tickAll(5)
    q.C.Modules.Set("Cute_Quest", true); tick(q, 6)
    assert(q.addons[2].private.dormant == true, "QuestBank loaded: the copy sleeps")
    openGuide(q)
    local Lq = qwin(q)
    local rq = Lq.bandKit and Lq.bandKit.remind
    assert(rq and rq:IsShown() and rq.text:GetText() == line.text and rq.mins:GetText() == "3 min", "the band: QuestBank's step-frame line:\n" .. texts(q))
    local hook = q.hooks.RemindChanged
    assert(type(hook) == "function" and API.StepFrame.RemindChanged == sfChanged, "a hook after QuestBank's own RemindChanged (hooksecurefunc), its function left as it is")
    -- QuestBank's Reminders refresh as you walk: the minutes, then the line gone once the trainer is visited
    line = { text = line.text, tex = 131146, mins = 2, word = "2 min", name = "Training" }
    API.StepFrame.RemindChanged(line); hook(line)
    tick(q, 1)
    assert(rq:IsShown() and rq.mins:GetText() == "2 min", "the minutes drawn again: " .. tostring(rq.mins:GetText()))
    line = nil
    API.StepFrame.RemindChanged(nil); hook(nil)
    tick(q, 1)
    assert(not rq:IsShown() and told == 2, "no line: none in the band; QuestBank's own step frame told each time")
    check(Lq.frame, "merge3 the Quests band beside QuestBank")
    leave(q)
    said[#said + 1] = "with QuestBank loaded the band follows its step-frame line"
    -- P7: a 0.8 character, Not now on the card, the Camp module unticked later in Settings > Modules: 0.8's switch kept
    -- the light (on) in its keeping, which this build gives back (Bridge.lua campChosen)
    local k = client(false)
    k.env.CuteQuestDB = { settings = { cuteDefaults = 2, v544 = true, v600 = true, campBar = false, guide = { on = true, frame = true },
      glow = { on = false, style = "sparkle" }, cuteOff = { camp = { campBar = true, ["glow.on"] = true } } } }
    login(k, { chars = { ["Rone-Forever"] = { counters = {}, setupLater = true, modules = { ["Cute_Quest:camp"] = false } } } }); tickAll(6)
    local ks = k.env.CuteQuestDB.settings
    assert(ks.glow.on == true, "the light on, given back as 0.8 kept it")
    assert(k.C.Setup.Show(true) and row(k, "Interact light") and row(k, "Interact light"):GetChecked() and not row(k, "Reminders"):GetChecked(),
      "the menu's card: the light's row ticked, as the light is; Reminders unticked, as the module is")
    press(button(k, "Start"))
    assert(ks.glow.on == true and k.env.CuteDB.chars["Rone-Forever"].modules["Cute_Quest:camp"] == false, "Start: the light still on, the module still off")
    leave(k)
    -- a fresh install's Not now, a reload, then the menu's card: the light off only until its row says, so ticked
    local m = client(true)
    login(m); tick(m, 3)
    press(button(m, "Not now"))
    assert(m.env.CuteQuestDB.settings.glow.on == false, "a fresh install: the light off until the card's row")
    local mdb, mq = m.env.CuteDB, m.env.CuteQuestDB
    leave(m)
    local m2 = client(false)
    m2.env.CuteQuestDB = mq
    login(m2, mdb, true); tickAll(6)
    assert(m2.C.Setup.Show(true) and row(m2, "Interact light"):GetChecked(), "after Not now and a reload, the menu's card: the light's row at its default, ticked")
    press(button(m2, "Start"))
    assert(m2.env.CuteQuestDB.settings.glow.on == true, "Start: the light on as its row said")
    leave(m2)
    -- the light turned off in Settings > Reminders: the card's row unticked
    local n = client(false)
    n.env.CuteQuestDB = { settings = { cuteDefaults = 2, v544 = true, v600 = true, guide = { on = true, frame = true }, glow = { on = true, style = "sparkle" } } }
    login(n); tickAll(6)
    n.C.UI:Open("settings", "camp")
    click(row(n, "Interact light"))
    assert(n.env.CuteQuestDB.settings.glow.on == false, "Settings > Reminders: the light off")
    hideAll(n)
    assert(n.C.Setup.Show(true) and not row(n, "Interact light"):GetChecked(), "the menu's card: the light's row unticked, as the player left it")
    check(n.env.CuteSetupFrame, "merge3 the setup card, the light off")
    leave(n)
    said[#said + 1] = "the card's light row starts from the light, never from the Camp module"
    -- P8
    local p = client(false)
    login(p); tickAll(6)
    local QBp = p.addons[2].private
    local Mini, MC = QBp.Mini, p.env.MinimapCluster
    local free = Mini.FreeDB()
    free.x, free.y = 300, 300
    MC:ClearAllPoints(); MC:SetPoint("TOPRIGHT", p.env.UIParent, "TOPRIGHT", -40, -40)
    Mini.ApplyFree()
    local mp = MC.__points[1]
    assert(p.C.Layout.Locked("minimap") and mp.point == "TOPRIGHT" and mp.x == -40 and free.x == nil and free.y == nil,
      "Cute's lock: the minimap where Edit Mode put it, the place kept from 0.8 let go: " .. tostring(mp.point))
    Mini.SetScale(1.2)
    mp = MC.__points[1]
    assert(mp.point == "TOPRIGHT" and mp.x == -40 and free.x == nil and math.abs((free.scale or 0) - 1.2) < 0.01, "a Ctrl-wheel: the size kept, never a place")
    Mini.ApplyFree()
    assert(MC.__points[1].point == "TOPRIGHT", "applied again: still Edit Mode's")
    Mini.ResetFree()
    leave(p)
    said[#said + 1] = "under Cute's lock the minimap's place is Edit Mode's"
    -- P9
    local t = client(false)
    login(t); tickAll(6)
    local QBt = t.addons[2].private
    local Mc = QBt.Movers.clock
    QBt:Settings().clock.show = true; QBt.Timer.Apply()
    local Ht = t.C.Halls
    -- (the test announcement's toast alone: the cards' own pictures are the cards stage's)
    local function toast() Ht.toastNow = nil; Ht:ShowToast(Ht.TestSet(false), true) end
    for _, scale in ipairs({ 1, 1.5, 2 }) do
      Mc.scale(scale)
      toast()
      local tf = Ht.toastFrame
      GEN = GEN + 1
      local r = tf and rectOf(tf)
      local l, top, w, hh = Mc.rect()
      assert(tf:IsShown() and r and not overlap(r, { l = l, r = l + w, t = top, b = top - hh }, 0),
        string.format("the toast clears the clock at %d%%: toast %s to %s, clock %s to %s", scale * 100, tostring(r and r.t), tostring(r and r.b), tostring(top), tostring(top - hh)))
    end
    check(Ht.toastFrame, "merge3 the toast under the clock at 200%")
    QBt:Settings().clock.show = false; QBt.Timer.Apply()
    toast()
    assert(Ht.toastFrame.__points[1].y == -20, "the clock hidden: the toast at its own place")
    Mc.set(nil)
    leave(t)
    said[#said + 1] = "a card's toast clears the clock strip"
    print("merge3 review: " .. table.concat(said, "; "))
  end)
end

-- [stage: fix-cute-core] that stage's tests go right below this line
----------------------------------------------------------------------------
-- fix-cute-core: the launch audit's findings on Cute's core (the channel, the roster, the rules, the first hour).
-- C1. A login a day on is answered by what changed since its last logout from each guild mate whose whole record it
--     heard in its last session, though that mate logged out and in again meanwhile (its record whole again, unheard),
--     its statistics pass too; a mate online in none of that session answers whole, as a 0.9 ask (no window) is.
--     What went is kept from login to login: a value unchanged since the last session is not sent again
-- C2. What a client deleted of others' records and may want back (a stat the officers closed and opened again) leaves it
--     no hold, so its next login asks every record whole; so does a registry grown since its last ask
-- C3. A brand-new member who presses Start on the first-run card at once: the welcome after the reload, never the
--     changelog line written for upgraders
-- C4. A member's file keeps none of the halls' store the officers keep: the weekly values of a stat they close, the
--     Queue's run cards, earns and firsts, a card locked to them, the firsts ledger and the earns remembered
-- C5. A book's title is one two of its voices gave alike: an edited copy's first title, joined by an honest member who
--     read the book, is never drawn or said in the officers' word
-- C6. What comes before the roster first reads is taken fifty a frame once it does, and what comes meanwhile goes behind
--     it, so an older record never lands after a newer delta
-- C7. A login, logout, Away or zone change in the guild reads that one member (its club event names it), another club's
--     event nothing; an online flip walks no record and builds no identity, a rank moved reads the guild
-- C8. A guild mate's loot waits for the next build (thirty seconds), not three; a build walks the records fifty a frame
----------------------------------------------------------------------------
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "MAGE", level = 30, online = true } end
  local function char(name, rank, extra) return newClient(charOf({ name, rank, rank <= 1 and "Officer" or "Raider", "MAGE", 30 }, extra)) end
  -- (the record chunks a client sent after the n-th message)
  local function chunks(c, n) local out = {}; for i = (n or 0) + 1, #c.sent do local m = c.sent[i].msg; if m:sub(1, 3) == "1F|" then out[#out + 1] = m end end return out end
  local function askOf(c) for _, m in ipairs(c.sent) do if m.msg:sub(1, 3) == "1R|" then return m.msg end end end
  local said = {}
  -- C1
  isolated({ member("Coraline", 1), member("Cobb", 3), member("Cyra", 3), member("Cato", 3) }, function()
    local off, a, b = char("Coraline", 1), char("Cobb", 3), char("Cyra", 3, { withStats = true })
    local adb, bdb = {}, {}
    login(off); login(a, adb); login(b, bdb)
    tickAll(200)
    assert(adb.roster[b.sender] and adb.roster[b.sender].stats.g2001 == 1234, "Cobb has Cyra's record and pass")
    -- Cobb logs out; Cyra logs out and in again while he is away (her record whole again, unheard by him), then moves
    fire(a, "PLAYER_LOGOUT"); leave(a)
    local held = adb.chars[a.name].hold
    assert(type(held) == "table" and tonumber(held.from) and tonumber(held.from) <= held.at, "the hold keeps where his session began: " .. tostring(held and held.from))
    tickAll(30)
    fire(b, "PLAYER_LOGOUT"); leave(b)
    tickAll(100)
    local b2 = char("Cyra", 3, { withStats = true })
    login(b2, bdb)
    tickAll(200)
    b2.o.zone = "Feralas"
    fire(b2, "ZONE_CHANGED_NEW_AREA")
    tickAll(30)
    -- Cato logs in only now: online in none of Cobb's session
    local d = char("Cato", 3, { withStats = true })
    login(d)
    tickAll(200)
    local b0, d0 = #b2.sent, #d.sent
    local a2 = char("Cobb", 3)
    login(a2, adb)
    tickAll(200)
    local ask = askOf(a2)
    local hex = ask and ask:match("^1R|[^|]*|%d+|%d*|(%x*)$")
    assert(hex and #hex == 32 and tonumber(hex:sub(17, 24), 16) == held.at and tonumber(hex:sub(25, 32), 16) == math.floor(held.from),
      "the ask carries his last session: since, and from when: " .. tostring(ask))
    local s1, s2, fp7 = ask:match("^1R|[^|]*|(%d+)|?(%d*)|?(%x*)$")
    assert(tonumber(s1) and tonumber(s2) and #fp7 ~= 16, "a 0.7 client reads its stamps, and no fingerprint")
    local fs = chunks(b2, b0)
    assert(#fs >= 1 and #fs <= 2, "Cyra answers with a part, not her whole record: " .. #fs .. " chunks: " .. table.concat(fs, " / "))
    for _, m in ipairs(fs) do assert(m:find("^1F|%d+|%d+|%d+s|"), "marked since: " .. m) end
    local all = table.concat(fs, " ")
    assert(all:find("zone=Feralas", 1, true), "with the zone she moved to: " .. all)
    assert(not all:find("level=", 1, true) and not all:find("g2001=", 1, true), "and nothing unchanged since he left, her statistics pass included: " .. all)
    local rec = a2.env.CuteDB.roster[b2.sender]
    assert(rec and rec.stats.zone == "Feralas" and rec.stats.level == 30 and rec.stats.g2001 == 1234, "Cobb holds her record as it is")
    -- Cato, online in none of his session, answers whole
    local ds = chunks(d, d0)
    assert(ds[1] and ds[1]:find("^1F|1|%d+|%d+|") and table.concat(ds, " "):find("level=", 1, true), "Cato answers whole: " .. tostring(ds[1]))
    -- a 0.9 ask, a since and no window: whole, her record having gone whole this login after it
    local b1 = #b2.sent
    b2.C.Comm:Receive("1R|" .. guidOf("Cato") .. "|0|0|" .. b2.C.Policy:Fp() .. string.format("%x", held.at), "GUILD", "Cato-Forever")
    tickAll(60)
    local w9 = chunks(b2, b1)
    assert(w9[1] and w9[1]:find("^1F|1|%d+|%d+|") and table.concat(w9, " "):find("level=", 1, true), "a 0.9 ask with no window: whole: " .. tostring(w9[1]))
    for _, x in ipairs({ off, b2, d, a2 }) do leave(x) end
  end)
  said[#said + 1] = "a login a day on: what changed since, from a mate who was online in its last session though she relogged; whole from one who was not, and for a 0.9 ask"
  -- C2
  isolated({ member("Coraline", 1), member("Cobb", 3), member("Cyra", 3) }, function()
    local off, a, b = char("Coraline", 1), char("Cobb", 3), char("Cyra", 3)
    local adb, bdb = {}, {}
    login(off); login(a, adb); login(b, bdb)
    tickAll(200)
    fire(b, "PLAYER_LOGOUT"); leave(b)
    -- the officers close Zone and open it again while Cyra is away: Cobb deleted her zone meanwhile
    off.C.Policy:Set("zone", "self"); off.C.Comm:SendPolicy()
    tickAll(10)
    assert(adb.roster[b.sender].stats.zone == nil, "Zone closed: Cobb deleted her zone")
    off.C.Policy:Set("zone", "all"); off.C.Comm:SendPolicy()
    tickAll(10)
    fire(a, "PLAYER_LOGOUT"); leave(a)
    assert(adb.chars[a.name].hold == nil, "Cobb keeps no hold: he deleted what he wants back")
    local b2 = char("Cyra", 3)
    login(b2, bdb)
    tickAll(200)
    local a2 = char("Cobb", 3)
    login(a2, adb)
    tickAll(200)
    local hex = askOf(a2):match("|(%x*)$")
    assert(#hex == 16, "his next ask whole: " .. askOf(a2))
    assert(adb.roster[b2.sender].stats.zone == "Duskwood", "and he has her zone again: " .. tostring(adb.roster[b2.sender].stats.zone))
    fire(a2, "PLAYER_LOGOUT"); leave(a2)
    -- a registry that grew since his last ask (a module switched on, a newer Cute): his next ask whole
    local hold = adb.chars[a.name].hold
    assert(type(hold) == "table" and hold.from and hold.reg == a2.C.Comm.Reg(), "a hold again, with what he takes on the wire: " .. tostring(hold and hold.reg))
    hold.reg = "1:1"
    local a3 = char("Cobb", 3)
    login(a3, adb)
    tickAll(30)
    assert(#(askOf(a3):match("|(%x*)$")) == 16, "a registry changed since: his ask whole: " .. askOf(a3))
    for _, x in ipairs({ off, b2, a3 }) do leave(x) end
  end)
  said[#said + 1] = "a stat closed and opened again, or a registry that grew, leaves the next login asking whole"
  -- C3
  isolated({ member("Coraline", 1), member("Cobb", 3) }, function()
    local db = {}
    local c = char("Cobb", 3, { card = true })
    login(c, db)
    tick(c, 4)
    local start
    for _, x in ipairs(c.frames) do if x.__kind == "Button" and x:IsVisible() and x.label and x.label.GetText and x.label:GetText() == "Start" then start = x end end
    assert(start, "the first-run card, Start on it")
    press(start)
    assert(c.reloads == 1, "Start reloads")
    leave(c)
    local c2 = char("Cobb", 3)
    login(c2, db, true)
    tick(c2, 15)
    local welcome, news = 0, 0
    for _, l in ipairs(c2.chat) do
      if l:find("/cute or the elf on the minimap opens the guild window.", 1, true) then welcome = welcome + 1 end
      if l:find("Cute " .. c2.C.version .. "|r: ", 1, true) then news = news + 1 end
    end
    assert(welcome == 1 and news == 0 and db.toldChanges == c2.C.version, "a Start in the first seconds: the welcome after the reload, no changelog:\n" .. table.concat(c2.chat, "\n"))
    leave(c2)
  end)
  said[#said + 1] = "a new member's Start in the first seconds: the welcome after the reload, never the changelog"
  -- C4
  isolated({ member("Ofa", 0), member("Mo", 3), member("Ann", 3) }, function()
    local ofa = char("Ofa", 0)
    local g = guidOf("Ann")
    local db = { policy = { vis = { deaths_week = "self" }, by = "Ofa-Forever", rank = 0, at = EPOCH, threshold = 1 },
      halls = { ["7"] = { weeks = { [g] = { n = 100, v = { deaths_week = 5, quests_week = 3 }, p = { n = 99, v = { deaths_week = 2, quests_week = 1 } } } },
        queue = { { id = "r1", src = "run", what = "a run card" }, { id = "x1", src = "record", what = "a record", lock = true },
          { id = "d:ach:1", digest = "ach", day = 1, entries = { { id = "a1", src = "ach", what = "an earn" } } },
          { id = "f1", src = "first", what = "a guild first" }, { id = "dr", src = "draft", what = "my draft" } },
        firsts = { e = { a12 = { g = g, n = "Ann", t = EPOCH } }, n = 1 }, achSeen = { [g .. ":12"] = 1 }, achSeenN = 1, sets = {}, gone = {} } } }
    login(ofa, { policy = { vis = { deaths_week = "self" }, by = "Ofa-Forever", mine = true, rank = 0, at = EPOCH, threshold = 1 } })
    local mo = char("Mo", 3)
    login(mo, db)
    tickAll(60)
    local d = db.halls["7"]
    -- (merge4: fix-cards' H.PurgeWeeks then takes a member's weekly store whole, the closed stat's values with the rest)
    assert(next(d.weeks) == nil, "a member's file keeps no weekly value, of a stat the officers keep or any: " .. json(d.weeks))
    local left = {}
    for _, r in ipairs(d.queue) do left[#left + 1] = r.id end
    assert(table.concat(left, ",") == "dr" and d.firsts == nil and d.achSeen == nil, "nor the officers' queue, ledger or earns: " .. table.concat(left, ","))
    for _, x in ipairs({ ofa, mo }) do leave(x) end
  end)
  said[#said + 1] = "a member's file keeps none of the halls' store the officers keep: weekly values of a closed stat, the queue's run cards, earns and firsts, the ledger"
  -- C5
  isolated({ member("Ann", 3), member("Ben", 3), member("Cy", 3), member("Dee", 3) }, function()
    local cy = char("Cy", 3)
    login(cy); tickAll(10)
    local F = cy.C.Finds
    local function rowOf(m, id) for _, r in ipairs(F.door.Rows(m)) do if r.id == id then return r end end end
    local function book(t, x) return { k = "b", id = 9401, m = 1429, x = x, y = 300, t = t } end
    -- an edited copy names a book first; an honest member who read it joins the find
    F.Voice(guidOf("Ann"), book("Ann was here and so on", 300))
    F.Voice(guidOf("Ben"), book("The Drowned Ledger", 304))
    F:Bump()
    local r = rowOf(1429, 9401)
    assert(r and r.sure and r.name == nil, "two voices, two titles: sure, and no title shown: " .. tostring(r and r.name))
    assert(#F:WordParts() == 0, "nor said in a word: " .. table.concat(F:WordParts(), ";"))
    -- a second honest voice: the title two of them gave
    F.Voice(guidOf("Dee"), book("The Drowned Ledger", 302))
    F:Bump()
    r = rowOf(1429, 9401)
    assert(r and r.name == "The Drowned Ledger", "two voices alike: their title: " .. tostring(r and r.name))
    local word = table.concat(F:WordParts(), ";")
    assert(word:find("=The Drowned Ledger", 1, true) and not word:find("Ann was here", 1, true), "said by the title two gave: " .. word)
    leave(cy)
  end)
  said[#said + 1] = "a book's title is one two voices gave alike: an edited copy's first title is never drawn or said"
  -- C6
  do
    local guild = { member("Ofa", 0) }
    for i = 1, 20 do guild[#guild + 1] = member("Rr" .. i, 3) end
    isolated(guild, function()
      local ofa = char("Ofa", 0)
      local real, slow = ofa.env.C_Club.GetClubMembers, true
      ofa.env.C_Club.GetClubMembers = function(...) if slow then return {} end return real(...) end
      login(ofa)
      tickAll(10)
      -- 120 records and deltas before the roster reads (C_Club slow after a restart)
      local b36 = ofa.C.Comm.b36
      for k = 1, 6 do
        for i = 1, 20 do
          local msg = k == 1 and ("1F|1|1|4|guid=" .. guidOf("Rr" .. i) .. ";deaths=" .. b36(1)) or ("1D|4|deaths=" .. b36(k))
          ofa.C.Comm:Receive(msg, "GUILD", "Rr" .. i .. "-Forever")
        end
      end
      assert(#ofa.C.Comm.early == 120, "kept until the roster reads: " .. #ofa.C.Comm.early)
      local R = ofa.C.Roster
      local applied, realApply = 0, R.Apply
      R.Apply = function(...) applied = applied + 1; return realApply(...) end
      slow = false
      fire(ofa, "GUILD_ROSTER_UPDATE")
      assert(applied > 0 and applied <= 50, "the roster read: the first fifty taken in that frame, not all: " .. applied)
      -- a delta heard while the rest waits its frame goes behind them, so Rr1's newer count is the one kept
      ofa.C.Comm:Receive("1D|4|deaths=" .. b36(7), "GUILD", "Rr1-Forever")
      tick(ofa, 1)
      local db = ofa.env.CuteDB.roster
      assert(applied == 121 and db["Rr1-Forever"].stats.deaths == 7 and db["Rr20-Forever"].stats.deaths == 6 and not db["Rr1-Forever"].suspect,
        "all taken over the next frames, in order: " .. applied .. ", deaths " .. tostring(db["Rr1-Forever"].stats.deaths))
      assert(#ofa.C.Comm.early == 0 and not ofa.C.Comm.replaying, "and the buffer empty")
      R.Apply = realApply
      leave(ofa)
    end)
  end
  said[#said + 1] = "what came before the roster read is taken fifty a frame, what comes meanwhile behind it"
  -- C7
  do
    local guild = { member("Ofa", 0) }
    for i = 1, 30 do guild[#guild + 1] = member("Pq" .. i, 3) end
    isolated(guild, function()
      local c = char("Ofa", 0)
      login(c); tickAll(40)
      local R = c.C.Roster
      local calls = { sweep = 0, identity = 0 }
      local rs, ri = R.Sweep, R.Identity
      R.Sweep = function(...) calls.sweep = calls.sweep + 1; return rs(...) end
      R.Identity = function(...) calls.identity = calls.identity + 1; return ri(...) end
      local reads0, ver0 = c.memberReads or 0, R.version
      -- Pq5 logs out, Pq6 goes Away, Pq7 changes zone: each event names its member
      guild[6].online = false
      fire(c, "CLUB_MEMBER_PRESENCE_UPDATED", 7, 6, 3)
      fire(c, "CLUB_MEMBER_PRESENCE_UPDATED", 7, 7, 4)
      guild[8].zone = "Tanaris"
      fire(c, "CLUB_MEMBER_UPDATED", 7, 8)
      -- another club's (a community): nothing of the guild's
      fire(c, "CLUB_MEMBER_PRESENCE_UPDATED", 99, 9, 3)
      assert((c.memberReads or 0) - reads0 == 3 and not R.soon, "each event read its member alone, no full read booked: " .. ((c.memberReads or 0) - reads0) .. " reads")
      assert(calls.sweep == 0 and calls.identity == 0 and R.version > ver0, "no identity built again, no record walked; the rows drawn again")
      assert(R.byGuid[guidOf("Pq5")].online == false and R.byGuid[guidOf("Pq7")].zone == "Tanaris", "Pq5 offline, Pq7 in Tanaris")
      -- a full read that finds an online flip alone: no identity, no sweep, the rows drawn again
      guild[9].online = false
      local ver1 = R.version
      fire(c, "GUILD_ROSTER_UPDATE")
      assert(calls.sweep == 0 and calls.identity == 0 and R.byGuid[guidOf("Pq8")].online == false and R.version > ver1, "a full read with an online flip alone: rows only")
      -- a rank changed: the full read, who is who again
      guild[10].rank = 1
      fire(c, "CLUB_MEMBER_UPDATED", 7, 10)
      assert(R.soon, "a rank moved: the full read booked")
      tick(c, 3)
      assert(calls.identity >= 1 and R.byGuid[guidOf("Pq9")].rank == 1, "and who is who built again: " .. calls.identity)
      R.Sweep, R.Identity = rs, ri
      leave(c)
    end)
  end
  said[#said + 1] = "a login, logout, Away or zone change reads that one member, a rank the guild; an online flip walks no record"
  -- C8
  do
    local guild = { member("Ofa", 0) }
    for i = 1, 299 do guild[#guild + 1] = { name = "Pw" .. i .. "-Forever", guid = string.format("Player-4242-%08X", 0x0D000000 + i), rank = 3, rankName = "Raider", class = "MAGE", level = 30, online = false } end
    isolated(guild, function()
      local roster = {}
      for i = 2, 300 do
        local st = { guid = guild[i].guid, level = 30, addon_ver = "0.9.0", zone = "Duskwood" }
        for j = 1, 100 do st["g" .. (3000 + j)] = i + j end
        for j = 1, 5 do st["e" .. (5000 + j)] = 1; st["k" .. (5000 + j)] = 20 + j end
        roster[guild[i].name] = { seen = EPOCH + 900, online = false, stats = st, at = {}, ch = true }
      end
      local c = char("Ofa", 0)
      login(c, { roster = roster })
      tickAll(120)
      local Rules = c.C.Rules
      tick(c, 40)
      -- a build just now; a guild mate's loot seen: it waits for the next build, not three seconds
      Rules:Rebuild()
      Rules.due, Rules.dueGen = false, (Rules.dueGen or 0) + 1
      assert(Rules.LearnLoot(5001, { 1234 }, false, guild[5].guid), "a guild mate's loot, new")
      assert(Rules.due and Rules.dueAt - c.C.Now() >= 25, "a guild mate's loot waits for the next build: " .. tostring(Rules.dueAt and (Rules.dueAt - c.C.Now())))
      -- that build: the walk over 299 records in slices of fifty, a frame each, then the model
      local zero, realAfter = 0, c.env.C_Timer.After
      c.env.C_Timer.After = function(sec, f) if sec == 0 then zero = zero + 1 end return realAfter(sec, f) end
      local at0 = Rules.model.at
      tick(c, 31)
      c.env.C_Timer.After = realAfter
      assert(zero >= 5 and Rules.model.at > at0 and Rules.model.bosses ~= nil, "the build's walk in slices, then the model: " .. zero .. " frames after the first")
      leave(c)
    end)
  end
  said[#said + 1] = "a guild mate's loot waits for the next build; a build walks the records fifty a frame"
  print("fix-cute-core review: " .. table.concat(said, "; "))
end

-- [stage: fix-cute-ui] that stage's tests go right below this line
----------------------------------------------------------------------------
-- The launch audit's cute-ui findings, Cute's side.
-- U1. The setup card asks about Runs: "Run reports after dungeons, raids and long groups", ticked, under Guild (the
--     run-report design's 14 and 18: Runs sends run values to the group, so the card asks); Start chooses the module.
--     A character who answered every other row sees the card once more with this row alone, unindented
----------------------------------------------------------------------------
-- (this stage's helpers, in one table: the main chunk's locals are near Lua's limit)
local UIX = {}
function UIX.member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
function UIX.row(c, label) return checkBox(c, function(cb) return cb.label and cb.label:GetText() == label end) end
function UIX.button(c, label) for _, b in ipairs(c.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == label then return b end end end
function UIX.rowIds(c) local out = {}; for _, r in ipairs(c.C.Setup.Rows()) do out[#out + 1] = r.id end return table.concat(out, " ") end
do
  local uiMember, uiRow, uiButton, uiRowIds = UIX.member, UIX.row, UIX.button, UIX.rowIds
  isolated({ uiMember("Rone", 1), uiMember("Pim", 3) }, function()
    local said = {}
    local state = {}
    local function client(name, rank) return newClient(charOf({ name, rank, rank <= 1 and "Officer" or "Raider", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = state, quest = true, card = true })) end
    local RUNS = "Run reports after dungeons, raids and long groups"
    -- a fresh character: the row, ticked, under Guild; unticked and Start, Runs is off and the row answered
    local c = client("Rone", 1)
    login(c); tick(c, 3)
    local r = uiRow(c, RUNS)
    assert(c.env.CuteSetupFrame and c.env.CuteSetupFrame:IsShown() and r and r:GetChecked(), "a fresh character's card asks about Runs, ticked: " .. uiRowIds(c))
    local g = checkBox(c, function(cb) return cb.label and cb.label:GetText():find("^Guild") end)
