-- U10. Settings > Modules lists the modules by window: Guild (always) with Runs, Achievements and Records under it;
--     Quests and Route (always) with the Dungeons and Gear tabs under it; then Map and Reminders. One reload line, at
--     the top ("Module boxes apply on reload; the guild switches apply at once." since fix2-cute-ui V5, "Applies on
--     reload." with Reload now and Undo once a change waits); none
--     in the rows' tooltips
-- the check rows a Settings section shows, top to bottom: { label, x }
function UIX.rows(c)
  local out = {}
  GEN = GEN + 1
  for _, fr in ipairs(c.frames) do
    if fr.checkRow and fr:IsVisible() and fr.label then local r = rectOf(fr); out[#out + 1] = { label = fr.label:GetText(), x = r.l, t = r.t, row = fr } end
  end
  table.sort(out, function(a, b) return a.t > b.t end)
  return out
end
do
  isolated({ UIX.member("Rone", 1) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(c); tickAll(6)
    c.C.UI:Open("settings", "modules")
    local rows, labels, x = UIX.rows(c), {}, {}
    for _, r in ipairs(rows) do labels[#labels + 1] = r.label; x[r.label] = r.x end
    -- (each guild switch under its module: U11)
    local want = { "Guild", "Runs", "Achievements", "Achievements for the whole guild", "Records", "Records for the whole guild", "Quests and Route", "Dungeons tab", "Gear tab", "Map", "Reminders" }
    assert(table.concat(labels, ", ") == table.concat(want, ", "), "Settings > Modules by window: " .. table.concat(labels, ", "))
    local g, q = x["Guild"], x["Quests and Route"]
    assert(x.Runs == g + 20 and x.Achievements == g + 20 and x.Records == g + 20, "Runs, Achievements and Records under Guild")
    assert(q == g and x["Dungeons tab"] == q + 20 and x["Gear tab"] == q + 20 and x.Map == g and x.Reminders == g, "the tabs under Quests and Route; Map and Reminders on their own")
    local function reloadLines() local n = 0; for l in texts(c):gmatch("[^\n]+") do if l ~= "Reload now" and l:lower():find("reload", 1, true) then n = n + 1 end end return n end
    assert(reloadLines() == 1 and texts(c):find("Module boxes apply on reload; the guild switches apply at once.", 1, true), "one reload line:\n" .. texts(c))
    for _, r in ipairs(rows) do assert(not tipOf(r.row):lower():find("reload", 1, true), "no reload in the tooltip of " .. r.label) end
    check(sframe(c), "fix-cute-ui U10 Settings > Modules by window")
    click(UIX.row(c, "Gear tab"))
    assert(reloadLines() == 1 and texts(c):find("Applies on reload.", 1, true), "a change waiting: still one reload line:\n" .. texts(c))
    c.C.Modules.Undo()
    leave(c)
    print("fix-cute-ui U10: Settings > Modules by window, Guild's modules under Guild and the quest tabs under Quests and Route; one reload line")
  end)
end

-- U11. Achievements' and Records' guild switches sit beside their module's row in Settings > Modules ("Achievements
--     for the whole guild" under Achievements), greyed for a member with "Set by the officers"; Settings has no
--     one-row Achievements or Records section. An officer's click applies at once, as the section's did
do
  isolated({ UIX.member("Rone", 1), UIX.member("Pim", 3) }, function()
    local o = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    local m = newClient(charOf({ "Pim", 3, "Raider", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(o); login(m); tickAll(60)
    for _, c in ipairs({ o, m }) do
      local ids = {}
      for _, sec in ipairs(c.C.SettingsPage.Sections(c.C.Roster:MeOfficer())) do ids[#ids + 1] = sec.id end
      local list = " " .. table.concat(ids, " ") .. " "
      assert(not list:find(" ach ", 1, true) and not list:find(" records ", 1, true), "no Achievements or Records section:" .. list)
      c.C.UI:Open("settings", "modules")
      local rows = UIX.rows(c)
      for _, t in ipairs({ "Achievements", "Records" }) do
        local at
        for i, r in ipairs(rows) do if r.label == t then at = i end end
        local sw = at and rows[at + 1]
        assert(sw and sw.label == t .. " for the whole guild" and sw.x == rows[at].x + 20, "the guild switch under " .. t .. ": " .. tostring(sw and sw.label))
        if c == m then
          assert(sw.row.__disabled and texts(c):find("Set by the officers", 1, true), "greyed for a member, who sets it said")
        else
          assert(not sw.row.__disabled, "the officer's to click")
        end
        -- (an officer's note under a switch, why guild news cannot vouch here: under the switch's label)
        local why = c == o and t == "Achievements" and c.C.Achievements and c.C.Achievements.NewsWords and c.C.Achievements.NewsWords()
        if why then
          local f = UIX.text(c, why)
          GEN = GEN + 1
          assert(f and rectOf(f).l >= sw.x + 18, "the switch's note under its label: " .. tostring(f and rectOf(f).l) .. " against " .. sw.x)
        end
      end
      check(sframe(c), "fix-cute-ui U11 Settings > Modules with the guild switches, " .. (c == o and "officer" or "member"))
    end
    click(UIX.row(o, "Records for the whole guild"))
    assert(o.C.Rules.Get("recGuild") == 0 and not UIX.row(o, "Records for the whole guild"):GetChecked(), "an officer's click: off for the guild at once")
    click(UIX.row(o, "Records for the whole guild"))
    assert(o.C.Rules.Get("recGuild") ~= 0, "and on again")
    leave(o); leave(m)
    print("fix-cute-ui U11: Achievements' and Records' guild switches under their rows in Settings > Modules, greyed for members; no one-row sections")
  end)
end

-- U12. Settings' long lists take two columns once the window is 1040 px wide or more (the windows design's 7): Columns'
--     lists (Race, Prog, Hall of Shame cards, Officers) and an officer's Who sees what, each list whole in one column,
--     the shorter column taking the next; Everyone and Only you over each column's boxes. Under 1040, one column
do
  isolated({ UIX.member("Rone", 1) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }))
    login(c); tickAll(60)
    local win = c.C.UI.Window("settings")
    local function xs(list)
      local seen, n = {}, 0
      for _, x in ipairs(list) do if not seen[x] then seen[x] = true; n = n + 1 end end
      return n
    end
    local function rowXs() local out = {}; for _, r in ipairs(UIX.rows(c)) do out[#out + 1] = r.x end return out end
    local function boxXs()
      local out = {}
      GEN = GEN + 1
      for _, fr in ipairs(c.frames) do if fr.__kind == "CheckButton" and fr:IsVisible() and fr.statId and fr.vis == "all" then out[#out + 1] = rectOf(fr).l end end
      return out
    end
    local function heads(word) local n = 0; for l in texts(c):gmatch("[^\n]+") do if l == word then n = n + 1 end end return n end
    for _, size in ipairs({ { 1100, 640 }, { 1040, 560 }, { 800, 560 } }) do
      c.C.UI:Open("settings", "columns")
      win.frame:SetSize(size[1], size[2]); sdraw(c)
      local two = size[1] >= 1040
      assert(xs(rowXs()) == (two and 2 or 1), string.format("Columns at %d px: %d column(s) of rows", size[1], xs(rowXs())))
      check(win.frame, string.format("fix-cute-ui U12 Settings > Columns at %dx%d", size[1], size[2]))
      c.C.UI:Open("settings", "vis")
      sdraw(c)
      assert(xs(boxXs()) == (two and 2 or 1) and heads("Everyone") == (two and 2 or 1) and heads("Only you") == (two and 2 or 1),
        string.format("Who sees what at %d px: %d column(s) of boxes, %d Everyone heads", size[1], xs(boxXs()), heads("Everyone")))
      check(win.frame, string.format("fix-cute-ui U12 Settings > Who sees what at %dx%d", size[1], size[2]))
    end
    leave(c)
    print("fix-cute-ui U12: Columns and Who sees what in two columns from 1040 px, one under it")
  end)
end

-- U13. A section's one head is its name in the list: Settings > Halls headed "Halls", Runs "Runs". The step frame's
--     right-click menu names the sayXP switch as Settings > Quests does: "Say XP after each hand-in: off"
do
  isolated({ UIX.member("Rone", 1) }, function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(c); tickAll(6)
    -- a head in the column (not the list of sections, whose rows carry their section's id)
    local function head(t)
      for _, o in everything() do
        if o.__kind == "FontString" and o.__shown and o.__text == t and visible(o) and o.__parent and o.__parent.__client == c then
          local inList = false
          for _, a in ipairs(ancestors(o)) do if rawget(a, "section") then inList = true end end
          if not inList then return o end
        end
      end
    end
    for _, sec in ipairs({ { "halls", "Halls", "Announcements" }, { "runs", "Runs", "Run reports" } }) do
      c.C.UI:Open("settings", sec[1])
      assert(head(sec[2]) and not head(sec[3]), "Settings > " .. sec[2] .. " headed " .. sec[2] .. ":\n" .. texts(c))
    end
    local QB = c.addons[2].private
    local n0 = #c.contextMenus
    QB.StepFrame:Menu(nil)
    local item
    for _, e in ipairs(c.contextMenus[#c.contextMenus] or {}) do if e.text and e.text:find("XP", 1, true) then item = e end end
    assert(#c.contextMenus == n0 + 1 and item and item.text == "Say XP after each hand-in: off", "the step frame's menu in Settings' words: " .. tostring(item and item.text))
    item.set()
    assert(c.env.CuteQuestDB.settings.sayXP == true, "its click: on")
    QB.StepFrame:Menu(nil)
    for _, e in ipairs(c.contextMenus[#c.contextMenus]) do if e.text and e.text:find("XP", 1, true) then item = e end end
    assert(item.text == "Say XP after each hand-in: on", "and says so: " .. item.text)
    leave(c)
    print("fix-cute-ui U13: Settings > Halls and Runs headed by their names; the step frame's menu says Say XP after each hand-in")
  end)
end

-- [stage: fix-engine] that stage's tests go right below this line
----------------------------------------------------------------------------
-- The launch audit's engine findings, Cute's side (Cute and QuestBank launch, 4 November). Each case in FECASES failed
-- on 0.9.0's files; every case runs, and the block fails at its end naming each one that did not hold
----------------------------------------------------------------------------
do
  local FECASES = {}
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 20, online = true } end
  local function quest(name, extra)
    local o = { modules = { "Cute_Quest" }, addonState = {}, quest = true }
    for k, v in pairs(extra or {}) do o[k] = v end
    return newClient(charOf({ name, 1, "Officer", "WARRIOR", 20 }, o))
  end
  -- (a case that fails inside isolated() still gives the harness its guild and clients back)
  local function inGuild(guild, fn)
    local ok, err = true, nil
    isolated(guild, function() ok, err = pcall(fn) end)
    if not ok then error(err, 0) end
  end
  local function button(c, label) for _, b in ipairs(c.frames) do if b.__kind == "Button" and b:IsVisible() and b.label and b.label.GetText and b.label:GetText() == label then return b end end end
  local function row(c, label) return checkBox(c, function(cb) return cb.label and cb.label:GetText() == label end) end
  -- a route of one stop, kind its way there (Target.Route as the Route tab reads it)
  local function oneStop(QB, stop, kind)
    local was = QB.Target.Route
    QB.Target.Route = function() return { legs = { { stop = stop, kind = kind, travel = 1, rows = {}, leave = 20.4 } }, xp = 0, level = 20, t = 1 } end
    return function() QB.Target.Route = was end
  end

  -- M1 (trust, must). A secret chain's next step showed on every guild mate's map, dim, as soon as one guild mate opened
  -- its lock (1X carried no mark; build() drew any find a guild mate saw). The engine tells a find opened carrying a
  -- secret chain's key as secret (QuestBank's Finds.lua, D.SECRETKEY); Cute sends it marked ("s" before its kind: an older
  -- Cute passes it by), still a voice, and draws a marked find only once two guild mates found it (or you did)
  FECASES[#FECASES + 1] = { "M1: a secret find shows on a guild mate's map only once two guild mates found it", function()
    inGuild({ member("Ann", 3), member("Ben", 3), member("Cy", 3) }, function()
      local function char(name)
        local c = newClient(charOf({ name, 3, "Raider", "WARRIOR", 20 }))
        c.env.C_Map = c.env.C_Map or {}
        local was = c.env.C_Map.GetMapInfo
        c.env.C_Map.GetMapInfo = function(m) if type(m) ~= "number" or m >= 99000 then return nil end return was and was(m) or { mapID = m, name = "Map " .. m, mapType = 3 } end
        return c
      end
      local ann, ben, cy = char("Ann"), char("Ben"), char("Cy")
      for _, c in ipairs({ ann, ben, cy }) do login(c) end
      tickAll(30)
      local F, b36 = ben.C.Finds, ben.C.Comm.b36
      local function rowOf(c, id) for _, r in ipairs(c.C.Finds.door.Rows(1429)) do if r.id == id then return r end end end
      local kv = F.Pack({ k = "k", id = 9501, m = 1429, x = 600, y = 400, sec = true })
      local back = F.Parse(kv)
      assert(back and back.k == "k" and back.id == 9501 and back.sec == true, "a secret find packed and parsed back as one: " .. tostring(kv))
      assert(kv:sub(1, 2) == "sk" and F.Pack({ k = "k", id = 9501, m = 1429, x = 600, y = 400 }):sub(1, 1) == "k", "marked before its kind; an ordinary one as before")
      assert(F.Parse("s" .. F.Pack({ k = "r", id = 7, m = 1429, x = 1, y = 1, lv = 20 })) == nil, "a rare or a crossing is never secret")
      F:Receive(kv, ann.sender, false)
      assert(rowOf(ben, 9501) == nil, "one guild mate's secret find: nothing on Ben's map, not even dim")
      F:Receive(F.Pack({ k = "k", id = 9502, m = 1429, x = 100, y = 100 }), ann.sender, false)
      assert(rowOf(ben, 9502) and not rowOf(ben, 9502).sure, "an ordinary find: dim with one voice, as before")
      F:Receive(F.Pack({ k = "k", id = 9501, m = 1429, x = 603, y = 401, sec = true }), cy.sender, false)
      local r = rowOf(ben, 9501)
      assert(r and r.sure and r.mates == 2, "two guild mates found it: drawn whole")
      -- your own, told secret by the engine: a voice that goes marked
      ann.C.Finds.door.Noted("k", 9601, 1429, 300, 300, nil, false, true)
      tickAll(130)
      local marked = false
      for _, m in ipairs(ann.sent) do if m.msg:sub(1, 3) == "1X|" and m.msg:find("sk" .. b36(9601) .. "@", 1, true) then marked = true end end
      assert(marked, "Ann's own secret lock goes out marked")
      assert(rowOf(ben, 9601) == nil and rowOf(cy, 9601) == nil, "and shows on no guild mate's map with her voice alone")
      for _, c in ipairs({ ann, ben, cy }) do leave(c) end
    end)
  end }

  -- M3 (owner, must). L > Route worded the Rut'theran portal as the mage spell: "portal to Darnassus, 1 min" under the icon
  -- of Portal: Darnassus (135741), the 6.1.1 complaint the engine's Travel.lua fixed. A portal leg says where the portal
  -- stands, "Portal in Rut'theran Village to <place>", under the world portal's art (portalpurple, 134492)
  FECASES[#FECASES + 1] = { "M3: L > Route words the Rut'theran portal as the walk-in portal it is", function()
    inGuild({ member("Rone", 1) }, function()
      local c = quest("Rone")
      login(c); tickAll(6)
      local QB = c.addons[2].private
      local art = c.env.Cute.Look.ART.portal
      assert(art[1] == "portalpurple" and art[2] == 134492, "the portal's art: the world portal's, never the mage spell's: " .. tostring(art[1]) .. " " .. tostring(art[2]))
      local undo = oneStop(QB, { m = 1457, x = 40, y = 50, name = "Darnassus" }, "portal")
      c.C.UI:Open("route")
      local tx = texts(c)
      undo()
      assert(tx:find("Portal in Rut'theran Village to ", 1, true) and tx:find(", 1 min", 1, true) and not tx:find("portal to ", 1, true), "the way line:\n" .. tx)
      leave(c)
    end)
  end }

  -- S1 (firsthour, owner, look). Route's map button opened the game's world map with Cute's Map on, and in a fight said
  -- "In a fight only the game's own map key opens the map." The design: "Open in the map" (opens M), on the route's
  -- first stop; M opens in a fight. With Map off it stays the game's map ("Open the map": the windows round's W19)
  FECASES[#FECASES + 1] = { "S1: Route's Open in the map opens Cute's map on the route, in a fight too", function()
    inGuild({ member("Rone", 1) }, function()
      local c = quest("Rone")
      login(c); tickAll(6)
      local QB = c.addons[2].private
      c.C.Modules.Set("Cute_Quest:map", true); tick(c, 1)
      local undo = oneStop(QB, { m = 1429, x = 42, y = 65, name = "Goldshire" }, "foot")
      c.C.UI:Open("route")
      local open = button(c, "Open in the map")
      assert(open, "Route's button with Map on:\n" .. texts(c))
      local went
      local go = QB.MapPage.Go
      QB.MapPage.Go = function(m, why) went = { m, why }; return true end
      c.combat = true
      local n0 = #c.chat
      press(open)
      c.combat = false
      QB.MapPage.Go = go
      undo()
      local M = c.C.UI.Window("map")
      assert(rawget(M, "frame") and M.frame:IsShown() and not (c.map and c.map.shown), "M opened, not the game's map")
      assert(went and went[1] == 1429 and went[2] == "user", "M on the route's first stop: " .. tostring(went and went[1]))
      assert(not table.concat(c.chat, "\n", n0 + 1):find("In a fight", 1, true), "nothing said in a fight")
      leave(c)
    end)
  end }

  -- S5 (firsthour, owner). The Route band's "Start run" always showed, with no tooltip: under Cute a run is J's Runs (a
  -- dungeon's report), and J's "End run" ends the group's. This one times your hand-ins (QuestBank's hand-in run, which a
  -- level lock's banked quests are for): named for that, a tooltip, shown only while quests are banked or it is on
  FECASES[#FECASES + 1] = { "S5: Route's run button times hand-ins, says so, and shows only while quests are banked", function()
    inGuild({ member("Rone", 1) }, function()
      local c = quest("Rone")
      login(c); tickAll(6)
      local QB = c.addons[2].private
      c.C.UI:Open("route")
      local kit = qwin(c).kits.route
      assert(not QB:Banking() and not kit.run:IsShown() and not button(c, "Start run"), "nothing banked: no run button:\n" .. texts(c))
      local banking = QB.Banking
      QB.Banking = function() return true end
      c.C.UI:Open("route")
      assert(kit.run:IsShown() and kit.run.label:GetText() == "Time hand-ins", "banked: Time hand-ins: " .. tostring(kit.run.label:GetText()))
      local tip = tipOf(kit.run)
      assert(tip:find("ticked off", 1, true) and tip:find("dungeon", 1, true), "its tooltip says what it times and what it is not:\n" .. tip)
      press(kit.run); tick(c, 1)
      assert(QB.Run.Get() and kit.run.label:GetText() == "Stop timing", "on: Stop timing")
      QB.Banking = banking
      c.C.UI:Open("route")
      assert(kit.run:IsShown(), "shown while it is on")
      press(kit.run)
      assert(not QB.Run.Get(), "Stop timing stops it")
      leave(c)
    end)
  end }

  -- S2 (firsthour). Settings > Route's "Minimap far view" (on by default) did nothing with Cute's Map off: the wheel was
  -- hooked only while the minimap was the engine's. The far view (the wheel past the game's widest, a drag to look
  -- around) follows its row alone; Ctrl-wheel, Alt-drag, the right-click menu, the size and the place stay the Map
  -- module's. Both off, the game's own wheel
  FECASES[#FECASES + 1] = { "S2: the minimap's far view follows its row, Map on or off", function()
    inGuild({ member("Rone", 1) }, function()
      local c = quest("Rone")
      login(c); tickAll(6)
      local QB = c.addons[2].private
      local Mini, MV, mini, s = QB.Mini, QB.MiniView, c.env.Minimap, QB:Settings()
      assert(not Mini.Owned() and s.mmExtended ~= false, "Map off, the far view on")
      local far = 0
      local wheel = MV.Wheel
      MV.Wheel = function(d) far = far + 1; return wheel(d) end
      local wheels, clicks, menus = c.gameWheel or 0, c.gameClicks or 0, #c.contextMenus
      assert(mini.__scripts.OnMouseWheel, "the wheel hooked")
      mini.__scripts.OnMouseWheel(mini, -1)
      assert(far == 1 and (c.gameWheel or 0) == wheels, "Map off: the wheel is the far view's")
      local scale = c.env.MinimapCluster.MinimapContainer:GetScale() or 1
      c.ctrl = true
      mini.__scripts.OnMouseWheel(mini, 1)
      c.ctrl = false
      assert(far == 1 and (c.gameWheel or 0) == wheels + 1 and math.abs((c.env.MinimapCluster.MinimapContainer:GetScale() or 1) - scale) < 0.001, "Ctrl-wheel: the game's, no size of ours")
      mini.__scripts.OnMouseUp(mini, "RightButton"); tick(c, 1)
      assert((c.gameClicks or 0) == clicks + 1 and #c.contextMenus == menus, "a right-click: the game's")
      s.mmExtended = false
      mini.__scripts.OnMouseWheel(mini, -1)
      assert(far == 1 and (c.gameWheel or 0) == wheels + 2, "the far view off: the game's wheel")
      s.mmExtended = true
      MV.Wheel = wheel
      leave(c)
    end)
  end }

  -- S8 (scale). The Map window's per-frame OnUpdate went through Cute.Safe: a table and a closure every frame while M
  -- was open (QuestBank 5.4.2 took that pattern out of the engine's own OnUpdates). A plain pcall now, nothing a frame
  FECASES[#FECASES + 1] = { "S8: the Map window's frame tick makes no garbage", function()
    inGuild({ member("Rone", 1) }, function()
      local c = quest("Rone")
      login(c); tickAll(6)
      local QB = c.addons[2].private
      c.C.Modules.Set("Cute_Quest:map", true); tick(c, 1)
      c.C.UI:Open("map")
      local b = c.C.UI.Window("map").mapBox
      assert(b and b.__scripts.OnUpdate, "the map's box ticks")
      local ticks = 0
      local was = QB.MapPage.Tick
      QB.MapPage.Tick = function() ticks = ticks + 1 end
      local on = b.__scripts.OnUpdate
      if jit then jit.off(); jit.flush() end
      collectgarbage("collect"); collectgarbage("stop")
      local before = collectgarbage("count")
      for _ = 1, 500 do on(b, 0.016) end
      local kb = collectgarbage("count") - before
      collectgarbage("restart")
      if jit then jit.on() end
      QB.MapPage.Tick = was
      assert(ticks == 500 and kb < 2, string.format("500 frames: %d ticks, %.1f KB", ticks, kb))
      leave(c)
    end)
  end }

  -- S9 (robust). The addon QuestBank beside Cute shared on GUILD and, in a raid, on RAID, whatever the officers' Who sees
  -- what said. The dormant Bridge sets QuestBank's runtime flags (QuestBankAPI is QuestBank's QB; no saved setting written):
  -- noRaidSync and noGuildSync, so guild sharing goes through Cute's Comm alone
  FECASES[#FECASES + 1] = { "S9: QuestBank loaded beside Cute: its sync told off RAID and GUILD, nothing of its settings written", function()
    inGuild({ member("Rone", 1) }, function()
      local q = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
      local isLoaded = q.env.C_AddOns.IsAddOnLoaded
      q.env.C_AddOns.IsAddOnLoaded = function(x) if x == "QuestBank" then return true, true end return isLoaded(x) end
      local settings = { guide = { on = true, frame = true }, arrow = true, glow = { on = true, style = "sparkle" }, remind = { on = true }, share = { party = true, guild = true }, djShow = { boss = true, rare = true, trash = false, other = true } }
      -- (merge4: a QuestBank that reads noGuildSync has Sync.GuildOn; an older one's share.guild is held off, merge4's B1)
      q.env.QuestBankAPI = {
        version = "6.4.1", logReady = true, state = { level = 5, log = {} }, routeNow = { legs = {}, xp = 0, level = 5, t = 0 },
        Settings = function() return settings end, MarkDirty = function() end, Comma = tostring, Short = tostring, Sync = { GuildOn = function() return false end },
        Model = { Busy = function() return false end }, Data = { CAT = {} }, Quest = { Get = function() return nil end },
        Guide = { Steps = function() return {} end, Text = function(st) return st.text end, TimeToLevel = function() return nil end, MemberSteps = function() return {} end, Reminder = function() return nil end },
        StepFrame = { Menu = function() end, Apply = function() end, RemindChanged = function() end }, Arrow = { Set = function() end },
        UI = { PlaceGroups = function() return {}, {}, nil, nil, nil end, Candidates = function() return {} end, QuestClick = function() end, QuestTooltip = function() end },
        Target = { Route = function() return { legs = {}, xp = 0, level = 5, t = 0 } end }, Run = { Get = function() return nil end },
        DMap = { Attach = function() end, Refresh = function() end }, Gear = { Attach = function() end, Refresh = function() end, RefreshSoon = function() end },
        Remind = { Pull = function() return {}, false end },
      }
      local API = q.env.QuestBankAPI
      login(q); tickAll(5)
      q.C.Modules.Set("Cute_Quest", true); tick(q, 6)
      assert(q.addons[2].private.dormant == true, "QuestBank loaded: the copy sleeps")
      assert(API.noRaidSync == true and API.noGuildSync == true, "QuestBank's sync told off RAID and GUILD")
      assert(settings.share.guild == true and settings.share.party == true, "its saved settings as they were")
      leave(q)
    end)
  end }

  -- S10 (trust). Data you share's "Share your quests with your party" named only the quests, with no tooltip; each 1S
  -- carries your level, XP, class and the plan's levels to PARTY or INSTANCE_CHAT, whatever Who sees what says
  FECASES[#FECASES + 1] = { "S10: the group share's row names what it sends and says where it goes", function()
    inGuild({ member("Rone", 1) }, function()
      local c = quest("Rone")
      login(c); tickAll(6)
      c.C.UI:Open("settings", "share")
      assert(not row(c, "Share your quests with your party"), "the old words gone")
      local r = row(c, "Share your level, XP and quests with your group")
      assert(r, "the row:\n" .. texts(c))
      local tip = tipOf(r)
      assert(tip:find("party or instance group", 1, true) and tip:find("Who sees what", 1, true), "its tooltip:\n" .. tip)
      click(r)
      assert(c.env.CuteQuestDB.settings.share.party == false, "unticked: off")
      click(r)
      assert(c.env.CuteQuestDB.settings.share.party == true, "ticked: on")
      leave(c)
    end)
  end }

  -- S12 (owner). For a quest you hold and have not finished, "show it on the arrow" (the reader's button, Ctrl-click on a
  -- row, on the band's step, on the step frame's) pointed at the hand-in NPC in town; a plain click on the step frame's
  -- quest goes to its nearest open objective. One way now: the step frame's (SF.QuestSpot); the engine's click otherwise
  FECASES[#FECASES + 1] = { "S12: show on the arrow, a held unfinished quest: its nearest open objective, everywhere", function()
    inGuild({ member("Rone", 1) }, function()
      local c = quest("Rone", { log = { [7] = 1 } })
      login(c); tickAll(6)
      local QB = c.addons[2].private
      local q = QB.Quest.Get(7)
      assert(QB.state.log[7] and not QB.state.log[7].complete, "Kobold Camp Cleanup held, not finished")
      local spots, clicks = {}, {}
      local spot, qclick = QB.StepFrame.QuestSpot, QB.UI.QuestClick
      QB.StepFrame.QuestSpot = function(id) spots[#spots + 1] = id; return true end
      QB.UI.QuestClick = function(x, st, which) clicks[#clicks + 1] = x.id end
      local L = qwin(c)
      c.C.UI:Open("quests")
      QB.Reader.Read(L, q)
      press(button(c, "Show on arrow"))
      c.ctrl = true
      QB.RowClick(L, q, QB:Status(q), "LeftButton")
      c.env.Cute.QuestBand.Arrow({ qid = 7 })
      QB.UI.scrollToQuest = 7
      QB.UI:Open(1)
      c.ctrl = false
      assert(#spots == 4 and #clicks == 0, "the reader, a row, the band, the step frame: its objective each time: " .. #spots .. " spots, " .. #clicks .. " clicks")
      local other = QB.Quest.Get(33)
      QB.Reader.Read(L, other)
      press(button(c, "Show on arrow"))
      assert(#clicks == 1 and clicks[1] == 33 and #spots == 4, "a quest not held: the engine's click (its giver)")
      QB.StepFrame.QuestSpot, QB.UI.QuestClick = spot, qclick
      leave(c)
    end)
  end }

  -- S13 (look). Data you share named "The QuestBank Uploader", which Cute's page does not offer; its only copy offers to
  -- install QuestBank, which puts Cute's quest copy to sleep. No word of it until Cute's page offers Cute-Uploader.zip,
  -- then one note that Cute's page has it (merge4: fix-data's page offers it), and never QuestBank's by name
  FECASES[#FECASES + 1] = { "S13: Data you share names no uploader but the one Cute's page offers", function()
    inGuild({ member("Rone", 1) }, function()
      local c = quest("Rone")
      login(c); tickAll(6)
      c.C.UI:Open("settings", "share")
      local shown = texts(c)
      local page = assert(io.open(HERE .. "/../../addons/cute/index.html")):read("*a")
      local zip = io.open(HERE .. "/../../addons/cute/Cute-Uploader.zip", "rb")
      local offered = page:find('href="Cute-Uploader.zip"', 1, true) ~= nil and zip ~= nil
      if zip then zip:close() end
      assert(not shown:find("QuestBank Uploader", 1, true), "never QuestBank's uploader:\n" .. shown)
      if offered then
        assert(shown:find("Cute's page at foreverrank.com has the uploader", 1, true), "Cute's page named for the uploader it offers:\n" .. shown)
      else
        assert(not shown:lower():find("uploader", 1, true), "no uploader named:\n" .. shown)
      end
      leave(c)
    end)
  end }

  -- S4 (firsthour), Cute_Quest's own words: the Finds list's note said what guides gave "QuestBank"; the site, which
  -- gathers them, is foreverrank.com
  FECASES[#FECASES + 1] = { "S4: the Finds list's note names foreverrank.com", function()
    inGuild({ member("Rone", 1) }, function()
      local c = quest("Rone")
      login(c); tickAll(6)
      local QB = c.addons[2].private
      c.C.Modules.Set("Cute_Quest:map", true); tick(c, 1)
      QB.MapWin.OpenFinds()
      local tx = texts(c)
      assert(tx:find("gave foreverrank.com", 1, true) and not tx:find("gave QuestBank", 1, true), "the note:\n" .. tx)
      leave(c)
    end)
  end }

  local failed = {}
  for _, case in ipairs(FECASES) do
    local ok, err = pcall(case[2])
    if ok then print("fix-engine: " .. case[1] .. ": ok") else failed[#failed + 1] = case[1] .. ": " .. tostring(err) end
    collectgarbage("collect")
  end
  assert(#failed == 0, "fix-engine: " .. #failed .. " of " .. #FECASES .. " failed:\n  " .. table.concat(failed, "\n  "))
end

-- [stage: fix-data] that stage's tests go right below this line
----------------------------------------------------------------------------
-- D1. Settings > Data you share says where a Cute player gets the uploader: Cute's page, which offers Cute-Uploader.zip
--     (build_uploader.py --cute: the uploader that never puts QuestBank in) beside Cute.zip, the zip beside the page; the
--     page never sends a Cute player to QuestBank's uploader, whose Install offers QuestBank (Cute_Quest asleep)
----------------------------------------------------------------------------
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  local ok, err
  isolated({ member("Rone", 1) }, function() ok, err = pcall(function()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(c); tickAll(6)
    c.C.UI:Open("settings", "share")
    local shown = texts(c)
    -- (merge4: one short note, the uploader as Cute's page offers it, never QuestBank's by name: fix-engine's S13)
    assert(shown:find("Cute's page at foreverrank.com has the uploader: it sends the site what you found in the world", 1, true), "Data you share says Cute's page has the uploader:\n" .. shown)
    assert(not shown:find("QuestBank Uploader", 1, true), "and never sends a Cute player to QuestBank's:\n" .. shown)
    local page = assert(io.open(HERE .. "/../../addons/cute/index.html")):read("*a")
    assert(page:find('href="Cute-Uploader.zip"', 1, true), "Cute's page offers Cute-Uploader.zip")
    assert(page:find('href="Cute.zip"', 1, true), "Cute's page still offers Cute.zip")
    assert(not page:find("QuestBank-Uploader.zip", 1, true), "Cute's page never offers QuestBank's uploader")
    local zip = io.open(HERE .. "/../../addons/cute/Cute-Uploader.zip", "rb")
    assert(zip, "Cute-Uploader.zip is beside Cute's page")
    zip:close()
    leave(c)
  end) end)
  assert(ok, "fix-data D1: " .. tostring(err))
  print("fix-data: Data you share names Cute's page, which offers Cute-Uploader.zip")
end

-- [stage: pages] that stage's tests go right below this line
----------------------------------------------------------------------------
-- The pages round: addons/cute/index.html and questbank/index.html say what this build does, read against the client.
-- W1. The window's pictures are this build's: one each for J, L and M, whose alt text names the window's tabs as the
--     client draws them, in order (J an officer's, L with its Dungeons and Gear tabs on, M with the Map on); nothing of
--     0.7's single window is left (its Guide and Settings tabs, its band's "Tick Quests" line)
-- W2. Install: Cute_Quest is the base and loads at every login, so no step says it loads only while a module is on; no
--     clause that says what you switch on or off names a base tab (Quests, Route), on the page or in Changes.lua's
--     lines from 0.8.0 on; every key the setup card binds is named
-- W3. The hero's privacy line: the engine shares your level and quest steps with your party by default (share.party),
--     so the line names the party and never says nothing leaves the guild
-- W4. QuestBank loaded: the card asks no Map (M stays the game's) and says the step frame, arrow and Reminders are
--     QuestBank's; Install tells a QuestBank player what that costs (M among it), and the footer does not say QuestBank
--     runs beside Cute
-- W5. QuestBank's page: a help answer that points at the chat line after a hand-in names the box that turns it on,
--     as QuestBank's Settings label it (sayXP is off by default)
-- W6. The owner's order: the window, then Install, then what is new (one line, the older ones folded); who sees what
--     one sentence, the stat list folded
----------------------------------------------------------------------------
do
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "MAGE", level = 21, online = true } end
  local function read(path) local f = assert(io.open(HERE .. "/../../" .. path)); local s = f:read("*a"); f:close(); return s end
  -- a piece of the page as a reader sees it: tags out, entities read, white space one space
  local function plainOf(s)
    s = s:gsub("<[^>]+>", " "):gsub("&#39;", "'"):gsub("&quot;", '"'):gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&amp;", "&"):gsub("%s+", " ")
    return s
  end
  local function sectionOf(page, id) return page:match('<section[^>]*id="' .. id .. '".-</section>') end
  -- the clauses of a text (cut at . ; : ( and ), lower case) that say what you switch on or off
  local function switchClauses(text)
    local out = {}
    for cl in (text:lower() .. "."):gmatch("[^%.;:%(%)]+") do if cl:find("switch", 1, true) then out[#out + 1] = cl end end
    return out
  end
  -- the elements (p, li, details) of a piece of the page, each as its text
  local function blocks(s)
    local out = {}
    for _, t in ipairs({ "p", "li", "details" }) do for body in s:gmatch("<" .. t .. "[%s>].-</" .. t .. ">") do out[#out + 1] = plainOf(body) end end
    return out
  end
  isolated({ member("Rone", 1) }, function()
    local said, failed = {}, {}
    local page, qbPage = read("addons/cute/index.html"), read("questbank/index.html")
    local c = newClient(charOf({ "Rone", 1, "Officer", "MAGE", 21 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true, card = true }))
    login(c); tick(c, 3)
    local Mods = c.C.Modules
    local s = c.env.CuteQuestDB.settings
    local install = sectionOf(page, "install") or ""
    local installText = plainOf(install)
    -- (each case on its own: a failed one names itself and the others still run, so one run shows every page fault)
    local CASES = {}
    CASES[#CASES + 1] = { "W1 J, L and M pictured as the client draws them", function()
      assert(not page:find('data-tab="guide"', 1, true) and not page:find('id="cu-tab-settings"', 1, true) and not page:find("Tick Quests in Settings", 1, true),
        "the page still draws 0.7's single window (a Guide tab, a Settings tab, the band's Tick Quests line)")
      Mods.Set("Cute_Quest:journal", true); Mods.Set("Cute_Quest:gear", true); Mods.Set("Cute_Quest:map", true)
      local function titles(window) local out = {}; for _, def in ipairs(Mods.Pages(true, window)) do out[#out + 1] = def.title end return out end
      local wins = { { "j", titles("guild") }, { "l", titles("quests") }, { "m", titles("map") } }
      for _, w in ipairs(wins) do
        local fig = page:match('<figure[^>]*id="cu%-shot%-' .. w[1] .. '".-</figure>')
        assert(fig, "the page has no picture of the " .. w[1]:upper() .. " window (figure#cu-shot-" .. w[1] .. ")")
        local src, alt = fig:match('<img[^>]*src="([^"]+)"'), plainOf(fig:match('<img[^>]*alt="([^"]*)"') or "")
        local f = src and io.open(HERE .. "/../../addons/cute/" .. src)
        assert(f, "the " .. w[1]:upper() .. " picture's file is beside the page: " .. tostring(src))
        f:close()
        assert(#w[2] > 0, "the client draws the " .. w[1]:upper() .. " window's pages")
        local at = 1
        for _, t in ipairs(w[2]) do
          local i = alt:find(t, at, true)
          assert(i, "the " .. w[1]:upper() .. " picture's alt names the tab " .. t .. " after the ones before it, as the client draws them (" .. table.concat(w[2], ", ") .. "): " .. alt)
          at = i + #t
        end
      end
      said[#said + 1] = "J, L and M pictured with their tabs as the client draws them (" .. table.concat(wins[1][2], ", ") .. "; " .. table.concat(wins[2][2], ", ") .. "; " .. table.concat(wins[3][2], ", ") .. ")"
    end }
    CASES[#CASES + 1] = { "W2 Install true for the base and the card's keys", function()
      assert(install ~= "", "the page has an Install section")
      assert(Mods.Base("Cute_Quest") and not installText:find("loads only while", 1, true), "Cute_Quest is the base, loaded at every login: Install says otherwise:\n" .. installText)
      local bases = {}
      for _, def in ipairs(Mods.list) do if def.base and def.page then bases[#bases + 1] = def.title end end
      assert(#bases >= 2, "the quest window's base tabs: " .. table.concat(bases, ", "))
      local function noBaseSwitched(text, where)
        for _, cl in ipairs(switchClauses(text)) do
          for _, t in ipairs(bases) do assert(not cl:find(t:lower(), 1, true), where .. " says the base tab " .. t .. " is switched on or off: \"" .. cl .. "\"") end
        end
      end
      noBaseSwitched(installText, "Install")
      -- (from 0.8.0, the windows' round, where Quests and Route became the base; 0.7's lines tell 0.7's modules)
      for v, line in pairs(c.C.CHANGES) do if not c.C.VersionNewer("0.8.0", v) then noBaseSwitched(line, "Changes.lua's " .. v .. " line") end end
      local keyed = {}
      for _, r in ipairs(c.C.Setup.Rows()) do
        if r.key then
          for _, w in ipairs(c.C.Keys.ALL) do
            if w.id == r.key then
              local letter = c.bindings[w.action] and c.bindings[w.action][1]
              assert(letter and install:find("<code>" .. letter .. "</code>", 1, true), "Install names the key the card binds for " .. r.label .. ": " .. tostring(letter))
              keyed[#keyed + 1] = letter
            end
          end
        end
      end
      assert(#keyed >= 3, "the card binds J, L and M: " .. table.concat(keyed, " "))
      said[#said + 1] = "Install: the base always loads, no base tab switched (the page and Changes.lua), the card's keys " .. table.concat(keyed, " ")
    end }
    CASES[#CASES + 1] = { "W3 the hero's privacy line names the party", function()
      local hero = plainOf(assert(page:match('<header class="cu%-hero".-</header>'), "the page has its hero"))
      assert(s.share and s.share.party ~= false, "the engine shares with the party by default")
      -- (merge4: the group, in Data you share's own words: merge4's P1)
      assert(not hero:find("nothing leaves the guild", 1, true) and (hero:find("party", 1, true) or hero:find("group", 1, true)), "the party sees your level and quest steps by default: the hero says otherwise:\n" .. hero)
      said[#said + 1] = "the hero names the group"
    end }
    CASES[#CASES + 1] = { "W4 a QuestBank player told what M and Reminders need", function()
      local q = c.C.API.QuestSetup
      c.C.API.QuestSetup = nil
      local mapAsked, line = false, nil
      for _, r in ipairs(c.C.Setup.Rows()) do
        if r.id == "mapwin" then mapAsked = true end
        if r.id == "dormant" then line = r.label end
      end
      c.C.API.QuestSetup = q
      assert(not mapAsked and line and line:find("Reminders", 1, true), "QuestBank loaded: no Map row, the dormant line: " .. tostring(line))
      local told = false
      for _, b in ipairs(blocks(install)) do if b:find("QuestBank", 1, true) and b:find("%f[%w]M%f[^%w]") and b:find("Reminders", 1, true) then told = true end end
      assert(told, "Install tells a QuestBank player that Cute's map (M) and Reminders need QuestBank off:\n" .. installText)
      local foot = plainOf(assert(page:match("<footer.-</footer>"), "the page has its footer"))
      assert(not foot:find("runs beside", 1, true), "the footer says QuestBank runs beside Cute:\n" .. foot)
      said[#said + 1] = "a QuestBank player told what M and Reminders need"
    end }
    CASES[#CASES + 1] = { "W5 QuestBank's help names the Say XP box", function()
      local label = assert(read("tools/questbank/QuestBank/UI.lua"):match('v%.sayXP = checkRow%([^"]*"([^"]+)"'), "QuestBank's Settings label the sayXP box")
      assert(s.sayXP ~= true, "sayXP is off by default")
      local help = assert(sectionOf(qbPage, "help"), "QuestBank's page has its Help")
      local answers = 0
      for _, b in ipairs(blocks(help)) do
        if b:find("chat line", 1, true) then
          answers = answers + 1
          assert(b:find(label, 1, true), "QuestBank's help points at the hand-in's chat line, off by default, without its box (" .. label .. "): " .. b)
        end
      end
      assert(answers > 0, "QuestBank's help still answers the XP question")
      said[#said + 1] = "QuestBank's help names " .. label
    end }
    CASES[#CASES + 1] = { "W6 the window, Install, one line new, who sees what in a sentence", function()
      local order = {}
      for id in page:gmatch('<section[^>]*id="([%w_-]+)"') do order[#order + 1] = id end
      local at = {}
      for i, id in ipairs(order) do at[id] = i end
      assert(at.window == 1 and at.install == 2, "the window first, Install right under it: " .. table.concat(order, ", "))
      local log = assert(sectionOf(page, "changelog"), "the page has its changelog")
      local open = log:gsub("<details.-</details>", "")
      local shown = 0
      for _ in open:gmatch("<li><b>%d+%.%d+%.%d+</b>") do shown = shown + 1 end
      assert(shown == 1 and log:find("<details", 1, true), "one line of what is new, the older ones folded: " .. shown .. " shown")
      local rules = assert(sectionOf(page, "rules"), "the page has who sees what")
      local ruleText = plainOf((rules:gsub("<details.-</details>", ""):gsub("<h2.-</h2>", "")))
      local sentences = 0
      for _ in (ruleText .. " "):gmatch("[%.!?]%s") do sentences = sentences + 1 end
      assert(sentences <= 1 and rules:find("<details", 1, true), "who sees what in one sentence, the stats folded: " .. sentences .. " sentences:\n" .. ruleText)
      said[#said + 1] = "the order: " .. table.concat(order, ", ")
    end }
    for _, case in ipairs(CASES) do
      local ok, err = pcall(case[2])
      if not ok then failed[#failed + 1] = case[1] .. ": " .. tostring(err) end
    end
    leave(c)
    assert(#failed == 0, "pages cases failed:\n" .. table.concat(failed, "\n"))
    print("pages: " .. table.concat(said, "; "))
  end)
end

-- [stage: pages3] that stage's tests go right below this line
----------------------------------------------------------------------------
-- The third pages round, a case each; every case runs, and the block fails at its end naming each one that did not hold:
-- P1. QuestBank's privacy line says who hears it in game as QuestBank's Settings hint does: Cute_Quest's copy of Sync
--     takes a group mate's QuestBank status on QuestBank's prefix and a guild mate's never, so the line names your
--     group's QuestBank and Cute users and your guild's QuestBank users, and never says QuestBank talks only to
--     QuestBank users
----------------------------------------------------------------------------
do
  local CASES, failed, said = {}, {}, {}
  local function read(path) local f = assert(io.open(HERE .. "/../../" .. path)); local s = f:read("*a"); f:close(); return s end
  -- a piece of the page as a reader sees it: tags out, entities read, white space one space
  local function plainOf(s)
    return (s:gsub("<[^>]+>", " "):gsub("&#39;", "'"):gsub("&quot;", '"'):gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&amp;", "&"):gsub("%s+", " "))
  end

  CASES[#CASES + 1] = { "P1 QuestBank's privacy line names who hears it as its Settings hint does", function()
    local status = "1S|5|100|A|WARRIOR|0|0|0|-1|0|0|6.4.2|0000000000"
    local ok, err = true, nil
    isolated({ UIX.member("Rone", 1), UIX.member("Pim", 3) }, function() ok, err = pcall(function()
      local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
      login(c); tickAll(5); tick(c, 6)
      local QB = c.addons[2].private
      local f = QB.Sync.frame
      f.__scripts.OnEvent(f, "CHAT_MSG_ADDON", "QuestBank", status, "GUILD", "Pim-Forever")
      assert(next(QB.Sync.members) == nil, "a guild mate's QuestBank status: Cute takes nothing")
      f.__scripts.OnEvent(f, "CHAT_MSG_ADDON", "QuestBank", status, "PARTY", "Pim-Forever")
      local m = QB.Sync.members["Pim-Forever"]
      assert(m and m.level == 5 and m.class == "WARRIOR", "a group mate's QuestBank status reaches Cute")
      leave(c)
    end) end)
    if not ok then error(err, 0) end
    local hint = assert(read("tools/questbank/QuestBank/UI.lua"):match('v%.shareHint:SetText%("To ([^"]-), never in chat'), "QuestBank's Settings hint names who hears your share")
    local line = plainOf(assert(read("questbank/index.html"):match('<p class="qb%-privacy">(.-)</p>'), "QuestBank's page has its privacy line"))
    assert(not line:find("only to other QuestBank users", 1, true), "the page says QuestBank talks only to other QuestBank users; a Cute client in the group hears it:\n" .. line)
    assert(line:lower():find(hint:lower(), 1, true), "the page names who hears QuestBank as its Settings hint does (" .. hint .. "):\n" .. line)
    assert(line:find("version check", 1, true), "the page still names the realm's version check:\n" .. line)
    said[#said + 1] = "QuestBank's privacy line: " .. hint
  end }

  for _, case in ipairs(CASES) do
    local ok, err = pcall(case[2])
    if not ok then failed[#failed + 1] = case[1] .. ": " .. tostring(err) end
  end
  assert(#failed == 0, "pages3: " .. #failed .. " of " .. #CASES .. " failed:\n  " .. table.concat(failed, "\n  "))
  print("pages3: " .. table.concat(said, "; "))
end

-- [stage: merge4] that stage's tests go right below this line
----------------------------------------------------------------------------
-- The merge's integration findings (launch/merge4), a case each; every case runs, and the block fails at its end naming
-- each one that did not hold:
-- H1. A member promoted while offline logs in to an officer's halls: the members idle since are in This week (its
--     client kept no weeks while it was a member, and an ask with a since brings only what changed); an officer who
--     leaves the guild, its weeks gone, keeps no hold, so a rejoin asks every record whole
-- U1. The setup card's line under Map, unticked, says the minimap's far view stays (its row in Settings, Route): the wheel
--     past the game's widest and a drag; with the far view off, the minimap is the game's
-- B1. QuestBank before 6.4.1 beside Cute (no Sync.GuildOn: it reads no noGuildSync) has its guild share off for the
--     session and put back at the logout; one that reads the flag is left as it is
-- P1. The hero's privacy line says what goes to your group in the client's own words (Data you share's row) and names
--     the run report Runs sends
-- P2. Install says what each download holds: every top folder of Cute.zip and Cute-Uploader.zip is named
-- Z1. build.py tells a zip whose Cute or Cute_Quest differs from the tree: a problem, a warning under --no-zip
----------------------------------------------------------------------------
do
  local CASES, failed, said = {}, {}, {}
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "MAGE", level = 30, online = true } end
  local function char(name, extra) return newClient(charOf({ name, 3, "Raider", "MAGE", 30 }, extra)) end
  local function inGuild(guild, fn)
    local ok, err = true, nil
    isolated(guild, function() ok, err = pcall(fn) end)
    if not ok then error(err, 0) end
  end
  local function read(path) local f = assert(io.open(HERE .. "/../../" .. path)); local x = f:read("*a"); f:close(); return x end
  local function plainOf(x) return (x:gsub("<[^>]+>", " "):gsub("&#39;", "'"):gsub("&quot;", '"'):gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&amp;", "&"):gsub("%s+", " ")) end
  local function run(cmd) local p = io.popen(cmd .. " 2>&1"); local out = p and p:read("*a") or ""; if p then p:close() end return out end

  CASES[#CASES + 1] = { "H1 a member promoted while offline has the idle members' weeks; an officer who left keeps no hold", function()
    local brann = member("Brann", 3)
    inGuild({ member("Wora", 1), brann, member("Wex", 3) }, function()
      local o, b, x = char("Wora"), char("Brann"), char("Wex")
      local bdb = {}
      login(o); login(b, bdb); login(x)
      tickAll(200)
      -- Wex dies while Brann is online, a member: Brann's client keeps no weeks
      fire(x, "PLAYER_DEAD")
      tickAll(5)
      local wex = x.o.guid
      assert(o.C.Halls.ThisWeek(wex, "deaths_week") == 1 and next(b.C.Halls.DB().weeks) == nil, "the officer keeps Wex's week, the member none")
      -- (Brann stays a while: what went in the last minute before a logout is sent again, Comm.lua HOLD_MARGIN)
      tickAll(300)
      fire(b, "PLAYER_LOGOUT"); leave(b)
      assert(type(bdb.chars) == "table" and type(b.C.Char().hold) == "table", "Brann's logout keeps a hold")
      -- promoted while offline; Wex idle since
      brann.rank, brann.rankName = 1, "Officer"
      tickAll(60)
      local b2 = char("Brann")
      login(b2, bdb)
      tickAll(200)
      assert(b2.C.Roster:MeOfficer(), "Brann is an officer at this login")
      assert(b2.C.Halls.ThisWeek(wex, "deaths_week") == 1, "This week's halls have idle Wex's deaths: " .. tostring(b2.C.Halls.ThisWeek(wex, "deaths_week")))
      for _, c in ipairs({ o, b2, x }) do leave(c) end
      -- an officer who leaves the guild: its weeks go, and so does its hold, at once and at the logout
      local o2 = char("Wora")
      local odb = o.env.CuteDB
      fire(o, "PLAYER_LOGOUT")
      assert(type(o.C.Char().hold) == "table", "Wora's logout keeps a hold")
      login(o2, odb); login(x, x.env.CuteDB)
      tickAll(200)
      assert(next(o2.C.Halls.DB().weeks) ~= nil, "the officer holds weeks again")
      o2.C.Roster:LeftGuild()
      assert(next(o2.C.Halls.DB().weeks) == nil and o2.C.Char().hold == nil, "the guild left: weeks and hold gone")
      fire(o2, "PLAYER_LOGOUT")
      assert(o2.C.Char().hold == nil, "and no hold written at the logout, so a rejoin asks every record whole")
      leave(o2); leave(x)
    end)
    said[#said + 1] = "a member promoted while offline has idle members' weeks; an officer who left keeps no hold"
  end }

  CASES[#CASES + 1] = { "U1 the card's Map line, unticked, says the far view stays", function()
    inGuild({ UIX.member("Rone", 1) }, function()
      local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true, card = true }))
      login(c); tick(c, 3)
      assert(c.env.CuteSetupFrame and c.env.CuteSetupFrame:IsShown(), "the card")
      local ON = "Cute's map on M; the minimap's wheel and right-click become Cute's"
      local FAR = "The minimap stays the game's, but for the far view (Settings, Route): wheel out past its widest, drag to look around"
      local GAME = "The minimap stays the game's"
      assert(UIX.text(c, ON), "ticked, the line as before:\n" .. texts(c))
      click(UIX.row(c, "Map"))
      assert(UIX.text(c, FAR) and not UIX.text(c, ON), "unticked, the far view is said:\n" .. texts(c))
      check(c.env.CuteSetupFrame, "merge4 U1 the card, Map unticked")
      local s = c.env.CuteQuestDB.settings
      s.mmExtended = false
      c.C.Setup.Draw()
      assert(UIX.text(c, GAME) and not UIX.text(c, FAR), "the far view off: the minimap is the game's:\n" .. texts(c))
      s.mmExtended = true
      click(UIX.row(c, "Map"))
      assert(UIX.text(c, ON), "ticked again, the line as before")
      leave(c)
    end)
    said[#said + 1] = "the card's Map line says the far view when Map is unticked"
  end }

  CASES[#CASES + 1] = { "B1 QuestBank before 6.4.1 beside Cute: its guild share off for the session", function()
    inGuild({ member("Rone", 1) }, function()
      local function beside(sync)
        local q = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
        local isLoaded = q.env.C_AddOns.IsAddOnLoaded
        q.env.C_AddOns.IsAddOnLoaded = function(x) if x == "QuestBank" then return true, true end return isLoaded(x) end
        local settings = { guide = { on = true, frame = true }, arrow = true, glow = { on = true, style = "sparkle" }, remind = { on = true }, share = { party = true, guild = true }, djShow = { boss = true, rare = true, trash = false, other = true } }
        q.env.QuestBankAPI = {
          version = "6.4.0", logReady = true, state = { level = 5, log = {} }, routeNow = { legs = {}, xp = 0, level = 5, t = 0 },
          Settings = function() return settings end, MarkDirty = function() end, Comma = tostring, Short = tostring, Sync = sync,
          Model = { Busy = function() return false end }, Data = { CAT = {} }, Quest = { Get = function() return nil end },
          Guide = { Steps = function() return {} end, Text = function(st) return st.text end, TimeToLevel = function() return nil end, MemberSteps = function() return {} end, Reminder = function() return nil end },
          StepFrame = { Menu = function() end, Apply = function() end, RemindChanged = function() end }, Arrow = { Set = function() end },
          UI = { PlaceGroups = function() return {}, {}, nil, nil, nil end, Candidates = function() return {} end, QuestClick = function() end, QuestTooltip = function() end },
          Target = { Route = function() return { legs = {}, xp = 0, level = 5, t = 0 } end }, Run = { Get = function() return nil end },
          DMap = { Attach = function() end, Refresh = function() end }, Gear = { Attach = function() end, Refresh = function() end, RefreshSoon = function() end },
          Remind = { Pull = function() return {}, false end },
        }
        login(q); tickAll(5)
        q.C.Modules.Set("Cute_Quest", true); tick(q, 6)
        assert(q.addons[2].private.dormant == true, "QuestBank loaded: the copy sleeps")
        return q, settings
      end
      local q, s = beside({})
      assert(s.share.guild == false and s.share.party == true, "an older QuestBank: its guild share off for the session, the party's as it was")
      fire(q, "PLAYER_LOGOUT")
      assert(s.share.guild == true, "put back at the logout, before its saved variables are written")
      leave(q)
      local q2, s2 = beside({ GuildOn = function() return false end })
      assert(s2.share.guild == true and q2.env.QuestBankAPI.noGuildSync == true, "a QuestBank that reads noGuildSync: its setting as it is")
      leave(q2)
    end)
    said[#said + 1] = "an older QuestBank's guild share held off for the session"
  end }

  CASES[#CASES + 1] = { "P1 the hero says what goes to your group in the client's words, run reports too", function()
    local page = read("addons/cute/index.html")
    local hero = plainOf(assert(page:match('<header class="cu%-hero".-</header>'), "the page has its hero"))
    local label = assert(read("tools/cute/Cute_Quest/PageQuests.lua"):match('col:Check%("(Share your [^"]+)"'), "Data you share's group row")
    local what, to = label:match("^Share (.-) with (your %a+)$")
    assert(what and to, "the row's words: " .. label)
    assert(hero:find(to .. " " .. what, 1, true), "the hero says \"" .. to .. " " .. what .. "\" (" .. label .. "):\n" .. hero)
    assert(hero:find("run report", 1, true) and hero:find("Runs", 1, true), "the hero names the run report Runs sends to the group:\n" .. hero)
    said[#said + 1] = "the hero says " .. to .. " " .. what .. " and the run report"
  end }

  CASES[#CASES + 1] = { "P2 Install says what each download holds", function()
    local page = read("addons/cute/index.html")
    local install = assert(page:match('<section[^>]*id="install".-</section>'), "the page has Install")
    local first = assert(install:match("<li>(.-)</li>"), "Install's first step")
    if run("command -v unzip"):find("unzip", 1, true) then
      for _, zip in ipairs({ "Cute.zip", "Cute-Uploader.zip" }) do
        assert(first:find('href="' .. zip .. '"', 1, true), "the first step offers " .. zip)
        local tops = {}
        for line in run("unzip -Z1 '" .. HERE .. "/../../addons/cute/" .. zip .. "'"):gmatch("[^\n]+") do tops[line:match("^([^/]+)")] = true end
        for top in pairs(tops) do
          assert(first:find("<code>" .. top .. "</code>", 1, true), zip .. " holds " .. top .. ", which the first step does not name:\n" .. plainOf(first))
        end
      end
      said[#said + 1] = "Install names each download's folders"
    else
      said[#said + 1] = "Install's folders not checked (no unzip here)"
    end
  end }

  CASES[#CASES + 1] = { "Z1 build.py tells a zip whose Cute or Cute_Quest differs from the tree", function()
    if not SEEDED then return end
    local py = [[
import os, sys, tempfile, zipfile
sys.path.insert(0, sys.argv[1])
import build
d = tempfile.mkdtemp()
for top in ("Cute", "Cute_Quest"): os.makedirs(os.path.join(d, top))
open(os.path.join(d, "Cute", "Cute.toc"), "w").write("## Version: 1.0.0\n")
open(os.path.join(d, "Cute_Quest", "Sync.lua"), "w").write("new\n")
same, old = os.path.join(d, "same.zip"), os.path.join(d, "old.zip")
with zipfile.ZipFile(same, "w") as z:
    z.write(os.path.join(d, "Cute", "Cute.toc"), "Cute/Cute.toc"); z.write(os.path.join(d, "Cute_Quest", "Sync.lua"), "Cute_Quest/Sync.lua")
    z.writestr("QuestBank_Finds/Finds.lua", "x")
with zipfile.ZipFile(old, "w") as z:
    z.write(os.path.join(d, "Cute", "Cute.toc"), "Cute/Cute.toc"); z.writestr("Cute_Quest/Sync.lua", "old\n"); z.writestr("Cute_Quest/Gone.lua", "x")
print("stale", build.zip_stale(same, d), build.zip_stale(old, d))
sys.argv = ["build.py"]; del build.problems[:]; build.check_zips([old], d); print("problems", len(build.problems))
sys.argv = ["build.py", "--no-zip"]; del build.problems[:]; build.check_zips([old], d); print("problems", len(build.problems))
]]
    local path = os.tmpname()
    local f = assert(io.open(path, "w"))
    f:write(py)
    f:close()
    local out = run("python3 -I '" .. path .. "' '" .. HERE .. "'")
    os.remove(path)
    assert(out:find("stale [] ['Cute_Quest/Gone.lua', 'Cute_Quest/Sync.lua']", 1, true), "zip_stale names the files that differ, and only those:\n" .. out)
    assert(out:find("problems 1\n", 1, true) and out:find("warn", 1, true) and out:find("problems 0\n", 1, true), "a problem when zipping, a warning under --no-zip:\n" .. out)
    said[#said + 1] = "build.py tells a stale zip"
  end }

  for _, case in ipairs(CASES) do
    local ok, err = pcall(case[2])
    if not ok then failed[#failed + 1] = case[1] .. ": " .. tostring(err) end
  end
  assert(#failed == 0, "merge4: " .. #failed .. " of " .. #CASES .. " failed:\n  " .. table.concat(failed, "\n  "))
  print("merge4: " .. table.concat(said, "; "))
end

-- [stage: fix2-cute-core] that stage's tests go right below this line
----------------------------------------------------------------------------
-- fix2-cute-core: the second launch audit's findings on Cute's core, a case each; every case runs, and the block fails
-- at its end naming each one that did not hold:
-- R1. A stat the officers open again asks every record whole only on a client that deleted its values while it was
--     closed (not an officer's, which deletes nothing, nor one that never held any: a stat closed by default opened
--     for the first time), and for one login: a member offline at the opening asks whole at its next login, whose
--     logout keeps a hold again
-- R2. A stat opened: no member asks the guild for what it dropped while it routed by the line from before (the
--     officer's value sent at the click, a mate's sent as it read the line first). Kept aside in memory, those are
--     taken once its own read opens the stat; one of a stat that stays closed goes after a while, never kept
-- L1. A level-up in the guild is patched in place from its club event (the level cap raised): no full read, no identity
--     built, no record walked; a full read that finds levels alone moved builds none either
-- W1. The wire keeps one sent time a label and one a boss's own claim (its first kill in a group), not every text a kill
--     or a growing loot list ever sent; a wire of the old kind is kept by id
-- Q1. A 1Q from a member the officers marked untrusted starts nothing; one asker's 1Q is answered twice a session at
--     most, and forces the whole statistics pass once in half an hour
-- N1. Settings > Data you share counts finds in the footers' words and its Show finds tooltip ends as M's note does:
--     no "QuestBank" under Cute
----------------------------------------------------------------------------
do
  local CASES, failed, said = {}, {}, {}
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "MAGE", level = 30, online = true } end
  local function char(name, rank, extra) return newClient(charOf({ name, rank, rank <= 1 and "Officer" or "Raider", "MAGE", 30 }, extra)) end
  local function inGuild(guild, fn)
    local ok, err = true, nil
    isolated(guild, function() ok, err = pcall(fn) end)
    if not ok then error(err, 0) end
  end
  local function pol(mine, vis)
    local copy = {}
    for k, v in pairs(vis or {}) do copy[k] = v end
    return { policy = { vis = copy, by = "Ofa-Forever", mine = mine or nil, rank = 1, at = EPOCH, threshold = 1 } }
  end
  local function askOf(c, from) for i = from or 1, #c.sent do local m = c.sent[i].msg; if m:sub(1, 3) == "1R|" then return m end end end
  local function hexOf(ask) return ask and ask:match("|(%x*)$") or "" end
  local function size(t) local n = 0; for _ in pairs(t or {}) do n = n + 1 end return n end

  CASES[#CASES + 1] = { "R1 a stat opened again asks whole only where its values were deleted, and for one login", function()
    inGuild({ member("Ofa", 1), member("Cobb", 3), member("Cyra", 3) }, function()
      INFO[7] = infoLine(pol().policy)
      local ofa, a, b = char("Ofa", 1), char("Cobb", 3), char("Cyra", 3)
      local odb, adb = pol(true), pol()
      login(ofa, odb); login(a, adb); login(b, pol())
      tickAll(200)
      assert(adb.roster[b.sender] and adb.roster[b.sender].stats.zone == "Duskwood", "Cobb has Cyra's zone")
      -- Whispers an hour, the officers' by default, opened for the first time: nobody held any of it
      assert(ofa.C.Policy:Set("whispers", "all") and saveLine(ofa))
      tickAll(60)
      assert(a.C.Policy:Route("whispers") == "all" and not a.C.Comm.unheld and not ofa.C.Comm.unheld, "a stat closed by default opened for the first time drops no hold")
      -- Zone closed: Cobb deletes Cyra's zone, Ofa, an officer, deletes nothing
      assert(ofa.C.Policy:Set("zone", "self") and saveLine(ofa))
      tickAll(60)
      assert(adb.roster[b.sender].stats.zone == nil and odb.roster[b.sender].stats.zone == "Duskwood", "Cobb deleted her zone, Ofa kept it")
      fire(a, "PLAYER_LOGOUT"); leave(a)
      assert(type(adb.chars[a.name].hold) == "table", "Cobb's logout keeps a hold")
      -- Zone opened again while Cobb is away: Cyra, online, deleted Ofa's zone (her next login asks whole), Ofa nothing
      assert(ofa.C.Policy:Set("zone", "all") and saveLine(ofa))
      tickAll(60)
      assert(b.C.Comm.unheld and not ofa.C.Comm.unheld, "Cyra, who deleted values, keeps no hold; Ofa, who deleted none, keeps hers")
      -- Cobb's login reads the line before its hello: that ask goes whole, and its logout keeps a hold
      local a2 = char("Cobb", 3)
      login(a2, adb)
      tickAll(200)
      assert(#hexOf(askOf(a2)) == 16, "his login after the opening asks whole: " .. tostring(askOf(a2)))
      assert(adb.roster[b.sender].stats.zone == "Duskwood", "and he has her zone again")
      fire(a2, "PLAYER_LOGOUT"); leave(a2)
      assert(type(adb.chars[a.name].hold) == "table", "that login's logout keeps a hold: one login asks whole")
      local a3 = char("Cobb", 3)
      login(a3, adb)
      tickAll(30)
      assert(#hexOf(askOf(a3)) == 32, "the next login asks with a since: " .. tostring(askOf(a3)))
      leave(a3)
      fire(ofa, "PLAYER_LOGOUT")
      assert(type(odb.chars[ofa.name].hold) == "table", "Ofa deleted nothing: her logout keeps a hold")
      leave(ofa); leave(b)
    end)
    said[#said + 1] = "a stat opened again asks whole only where its values were deleted, and for one login"
  end }

  CASES[#CASES + 1] = { "R2 a stat opened: nobody asks the guild, and what came before the read is taken as it opens", function()
    inGuild({ member("Ofa", 1), member("Mia", 3), member("Zed", 3) }, function()
      INFO[7] = infoLine(pol(nil, { hearth = "self" }).policy)
      local ofa, mia, zed = char("Ofa", 1), char("Mia", 3), char("Zed", 3, { hearth = "Stormwind" })
      local mdb, zdb = pol(nil, { hearth = "self" }), pol(nil, { hearth = "self" })
      login(ofa, pol(true, { hearth = "self" })); login(mia, mdb); login(zed, zdb)
      tickAll(200)
      assert(mdb.roster[zed.sender].stats.hearth == nil and zdb.roster[ofa.sender].stats.hearth == nil, "the officers alone hold the hearths")
      -- Mia's roster ask went a second ago: her read of the new line waits, and Zed's hearth, sent as he reads it, comes first
      mia.C.Roster.askedAt = mia.C.Now() - 1
      local m0, z0 = msgs(mia, "1R"), msgs(zed, "1R")
      assert(ofa.C.Policy:Set("hearth", "all") and saveLine(ofa))
      tickAll(4)
      assert(mia.C.Policy:Route("hearth") == "self" and mdb.roster[zed.sender].stats.hearth == nil, "Mia routes by the line from before: nothing taken yet")
      tickAll(120)
      assert(mia.C.Policy:Route("hearth") == "all" and zed.C.Policy:Route("hearth") == "all", "both read the line")
      assert(msgs(mia, "1R") == m0 and msgs(zed, "1R") == z0, "nobody asked the guild: " .. (msgs(mia, "1R") - m0) .. " and " .. (msgs(zed, "1R") - z0) .. " asks")
      assert(mdb.roster[zed.sender].stats.hearth == "Stormwind" and mdb.roster[ofa.sender].stats.hearth == "Goldshire",
        "Mia holds Zed's hearth and Ofa's, kept aside until her read: " .. tostring(mdb.roster[zed.sender].stats.hearth) .. ", " .. tostring(mdb.roster[ofa.sender].stats.hearth))
      assert(zdb.roster[ofa.sender].stats.hearth == "Goldshire", "Zed holds Ofa's, sent at her click: " .. tostring(zdb.roster[ofa.sender].stats.hearth))
      -- a value of a stat the line keeps closed (Whispers an hour): aside, never in the record, gone after a while
      local R = mia.C.Roster
      R:Apply(zed.sender, { whispers = 7 })
      assert(mdb.roster[zed.sender].stats.whispers == nil and R.aside and R.aside[zed.sender] and R.aside[zed.sender].v.whispers, "kept aside, not in Zed's record")
      tickAll(700)
      assert(R.aside[zed.sender] == nil and mdb.roster[zed.sender].stats.whispers == nil and msgs(mia, "1R") == m0, "gone after a while, never kept, nothing asked")
      for _, c in ipairs({ ofa, mia, zed }) do leave(c) end
    end)
    said[#said + 1] = "a stat opened: nobody asks the guild, what came before the read is taken as it opens, a closed one's goes"
  end }

  CASES[#CASES + 1] = { "L1 a level-up is patched in place from its club event", function()
    local guild = { member("Ofa", 0) }
    for i = 1, 30 do guild[#guild + 1] = member("Lv" .. i, 3) end
    inGuild(guild, function()
      local c = char("Ofa", 0)
      login(c); tickAll(40)
      local R = c.C.Roster
      local calls = { sweep = 0, identity = 0 }
      local rs, ri = R.Sweep, R.Identity
      R.Sweep = function(...) calls.sweep = calls.sweep + 1; return rs(...) end
      R.Identity = function(...) calls.identity = calls.identity + 1; return ri(...) end
      local ver0, lv0, reads0 = R.version, R.levelVersion, c.memberReads or 0
      -- Lv3 dings: its event names it
      guild[4].level = 31
      fire(c, "CLUB_MEMBER_UPDATED", 7, 4)
      assert(not R.soon and (c.memberReads or 0) - reads0 == 1, "the member read alone, no full read booked")
      assert(calls.sweep == 0 and calls.identity == 0 and R.version > ver0, "no identity built, no record walked; the rows drawn again")
      assert(R.byGuid[guidOf("Lv3")].level == 31 and R.maxLevel == 31 and R.levelVersion > lv0, "Lv3 at 31, the cap's top raised: " .. tostring(R.maxLevel))
      local row
      for _, r in ipairs(R:Rows()) do if r.guid == guidOf("Lv3") then row = r end end
      assert(row and row.level == 31, "its row says 31")
      -- a full read that finds a level alone moved (its event missed): rows only
      guild[5].level = 32
      local ver1 = R.version
      fire(c, "GUILD_ROSTER_UPDATE")
      assert(calls.sweep == 0 and calls.identity == 0 and R.byGuid[guidOf("Lv4")].level == 32 and R.maxLevel == 32 and R.version > ver1,
        "a full read with a level alone moved: rows only: " .. calls.identity .. " identities, " .. calls.sweep .. " sweeps")
      -- a rank moved still reads the guild
      guild[6].rank = 1
      fire(c, "CLUB_MEMBER_UPDATED", 7, 6)
      assert(R.soon, "a rank moved: the full read booked")
      R.Sweep, R.Identity = rs, ri
      leave(c)
    end)
    said[#said + 1] = "a level-up is patched in place from its club event; a full read with levels alone moved builds no identity"
  end }

  CASES[#CASES + 1] = { "W1 the wire keeps one sent time a label and a boss's own claim alone", function()
    inGuild({ member("Ofa", 1), member("Ann", 3), member("Mo", 3) }, function()
      -- a wire of the old kind: labels and claims kept by their whole text
      local old = { v = {}, l = { ["e1230:36=Rhahk'Zor"] = EPOCH + 500, ["l1230=1"] = EPOCH + 600, ["l1230=1.2"] = EPOCH + 700 },
        k = { ["1230@a:x"] = EPOCH + 500, ["1230@b:x"] = EPOCH + 800 } }
      local was = { v = {}, l = {}, k = {} }
      for kind, list in pairs(old) do for key in pairs(list) do was[kind][key] = true end end
      local adb = { chars = { ["Ann-Forever"] = { counters = {}, modules = {}, wire = { club = "7", login = EPOCH + 400, sentAt = old, was = was } } } }
      local ann, mo = char("Ann", 3, { party = { "Mo" } }), char("Mo", 3, { party = { "Ann" } })
      login(ann, adb); login(mo)
      local M = ann.C.Comm
      assert(size(M.sentAt.l) == 2 and M.sentAt.l.e1230 == EPOCH + 500 and M.sentAt.l.l1230 == EPOCH + 700 and M.was.l.l1230 == "l1230=1.2",
        "an old wire's labels kept by id, the newest text: " .. json(M.sentAt.l))
      assert(size(M.sentAt.k) == 1 and M.sentAt.k.e1230 == EPOCH + 500 and M.was.k.e1230 == "1230@a:x", "and a boss's first claim: " .. json(M.sentAt.k))
      tickAll(60)
      -- three kills of one boss in a group
      for _, c in ipairs({ ann, mo }) do c.o.instance, c.o.instanceID, c.o.instName = "party", 36, "The Deadmines"; fire(c, "PLAYER_ENTERING_WORLD", false, false) end
      for _ = 1, 3 do
        for _, c in ipairs({ ann, mo }) do fire(c, "ENCOUNTER_END", 1230, "Rhahk'Zor", 1, 5, 1, {}) end
        tickAll(30)
      end
      local claims = {}
      for _, m in ipairs(ann.sent) do if m.channel == "GUILD" and m.msg:sub(1, 3) == "1K|" then claims[#claims + 1] = m.msg:sub(4) end end
      assert(#claims == 3, "three claims went: " .. #claims)
      assert(size(M.sentAt.k) == 1 and M.was.k.e1230 == claims[1], "the wire keeps the boss's own claim alone, the first kill's: " .. json(M.was.k))
      for key, text in pairs(M.was.l) do assert(key:match("^%a%d+$") and type(text) == "string", "a label kept by its id: " .. key) end
      assert(M.was.l.e1230 and M.sentAt.l.e1230 == EPOCH + 500, "the boss's label, its text the same, keeps its time: " .. tostring(M.sentAt.l.e1230))
      for _, c in ipairs({ ann, mo }) do leave(c) end
    end)
    said[#said + 1] = "the wire keeps one sent time a label and a boss's own claim alone, an old wire's by id"
  end }

  CASES[#CASES + 1] = { "Q1 an untrusted member's 1Q starts nothing; one asker's is answered twice a session, its pass once", function()
    inGuild({ member("Ofa", 1), member("Ann", 3), member("Mal", 3), member("Bo", 3) }, function()
      local g = guidOf("Mal")
      local p = pol()
      p.policy.untrusted, p.policy.trustAt = { [g] = true }, { [g] = EPOCH }
      local ann = char("Ann", 3, { withStats = true })
      login(ann, p)
      tickAll(700)
      assert(ann.C.Policy:Untrusted(g), "Mal untrusted on Ann's client")
      local function answers(from)
        local rec, pass = 0, 0
        for i = from + 1, #ann.sent do
          local m = ann.sent[i].msg
          if m:sub(1, 3) == "1F|" and m:find("level=", 1, true) then rec = rec + 1 end
          if m:sub(1, 3) == "1F|" and m:find("g2001=", 1, true) then pass = pass + 1 end
        end
        return rec, pass
      end
      local s0 = #ann.sent
      for _ = 1, 3 do ann.C.Comm:Receive("1Q|" .. ann.o.guid, "GUILD", "Mal-Forever"); tickAll(200) end
      local r, ps = answers(s0)
      assert(r == 0 and ps == 0, "Mal's 1Qs start nothing: " .. r .. " records, " .. ps .. " passes")
      s0 = #ann.sent
      for _ = 1, 3 do ann.C.Comm:Receive("1Q|" .. ann.o.guid, "GUILD", "Bo-Forever"); tickAll(200) end
      tickAll(500)
      r, ps = answers(s0)
      assert(r == 2 and ps == 1, "Bo's three 1Qs: the record whole twice, the pass once: " .. r .. " records, " .. ps .. " passes")
      leave(ann)
    end)
    said[#said + 1] = "an untrusted member's 1Q starts nothing; one asker's is answered twice a session, its pass once in half an hour"
  end }

  CASES[#CASES + 1] = { "N1 Data you share counts finds in Cute's words", function()
    inGuild({ UIX.member("Rone", 1) }, function()
      local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true, log = { [7] = 2 } }))
      login(c); tickAll(6)
      c.C.Modules.Set("Cute_Quest:map", true); tick(c, 1)
      local QB = c.addons[2].private
      local disc = QB.Discover.DB()
      disc.find = { o9001 = { p = { { 1429, 400, 400, 1 } }, b = "A Diary of Your Own", n = 1 } }
      disc.findN = (tonumber(disc.findN) or 0) + 1
      c.C.UI:Open("settings", "share")
      local st = texts(c)
      assert(st:find("1 new find" .. c.C.UI.Look.DOT, 1, true) and st:find(" confirmed by the guild", 1, true) and not st:find("QuestBank does not have", 1, true),
        "the footers' words: " .. st)
      local tip = tipOf(UIX.button(c, "Show finds"))
      assert(tip:find("what players' games and guides gave foreverrank.com.", 1, true) and not tip:find("QuestBank", 1, true), "the tooltip as M's note: " .. tip)
      check(c.C.UI.Window("settings").frame, "fix2-cute-core N1 Data you share")
      leave(c)
    end)
    said[#said + 1] = "Data you share counts finds in the footers' words, Show finds' tooltip as M's note"
  end }

  for _, case in ipairs(CASES) do
    local ok, err = pcall(case[2])
    if not ok then failed[#failed + 1] = case[1] .. ": " .. tostring(err) end
  end
  assert(#failed == 0, "fix2-cute-core: " .. #failed .. " of " .. #CASES .. " failed:\n  " .. table.concat(failed, "\n  "))
  print("fix2-cute-core: " .. table.concat(said, "; "))
end

-- [stage: fix2-cute-ui] that stage's tests go right below this line
----------------------------------------------------------------------------
-- The second launch audit's cute-ui findings, a case each; every case runs, and the block fails at its end naming each
-- one that did not hold:
-- V1. A member's pick card on L says "Levels and bosses as the guild has met them." only where that is so: its range
--     and every boss the guild's (no seed: all of it). A research or beta range, or a boss from research, and the
--     line is not there (each line above says its source)
-- V2. The setup card's Map line, unticked, sends the far view to where its switch is: Settings, Route ("Minimap far
--     view"), not the Route tab
-- V3. Settings > Data you share counts the finds in the footers' words ("1 new find, a dot, 0 confirmed by the
--     guild"), and Show finds says the Map window's words: never QuestBank, an addon a Cute player does not have
-- V4. The officer ranks stop at the guild's last rank (GuildControlGetNumRanks, Blizzard_Communities/GuildRoster.lua:137;
--     9 where the client lacks it): no made-up "rank 4"; the guild master alone "sees every value and sets this list"
-- V5. Settings > Modules' top line says both: the module boxes apply on reload, the guild switches at once
----------------------------------------------------------------------------
UNDOCUMENTED.GuildControlGetNumRanks = { "Blizzard_Communities/GuildRoster.lua:137 (the roster's rank menu: maxRankOrder, the guild's rank count)", optional = true }
do
  local CASES, failed, said = {}, {}, {}
  local function inGuild(guild, fn)
    local ok, err = true, nil
    isolated(guild, function() ok, err = pcall(fn) end)
    if not ok then error(err, 0) end
  end

  CASES[#CASES + 1] = { "V1 a member's pick says the guild's levels and bosses only where they are the guild's", function()
    inGuild({ UIX.member("Helga", 1), UIX.member("Pim", 3) }, function()
      local LINE = "Levels and bosses as the guild has met them."
      local m = newClient(charOf({ "Pim", 3, "Raider", "WARRIOR", 20 }))
      login(m); tickAll(35)
      local R = m.C.Rules
      openGuide(m); redraw(m)
      local tip = tipOf(guideHead(m))
      if R.SeedState() == "none" then
        assert(tip:find(LINE, 1, true), "no seed: every level and boss is the guild's, and the line says so:\n" .. tip)
        said[#said + 1] = "no seed: the member's line"
        leave(m)
        return
      end
      assert(R.SeedState() == "fresh", "the seed checked: " .. tostring(R.SeedState()))
      local _, plan = m.C.Guide.Items(false)
      local d = assert(plan.next.card, "a level 20 member's pick is a card: " .. tostring(plan.next.line)).d
      assert(tip:find("Levels " .. d.min .. "-" .. d.max, 1, true) and (tip:find("the research's range", 1, true) or tip:find("the beta's range", 1, true)),
        "the card's range is the research's:\n" .. tip)
      assert(not tip:find(LINE, 1, true), "a research range: the line does not say the guild met it:\n" .. tip)
      -- the range learned from the guild, its bosses still the research's: still not said
      d.range, d.levels = "learned", 2
      redraw(m)
      tip = tipOf(guideHead(m))
      assert(tip:find("learned from 2 members", 1, true) and not tip:find(LINE, 1, true), "the guild's range, the research's bosses: not said:\n" .. tip)
      -- and every boss the guild's: said
      for _, enc in ipairs(d.bosses or {}) do local b = R.Model().bosses[enc]; if b then b.state, b.n = "seen", 2 end end
      redraw(m)
      tip = tipOf(guideHead(m))
      assert(tip:find(LINE, 1, true) and not tip:find("from research;", 1, true), "the guild's range and bosses: said:\n" .. tip)
      said[#said + 1] = "the member's line only where the range and bosses are the guild's"
      leave(m)
    end)
  end }

  CASES[#CASES + 1] = { "V2 the card's Map line, unticked, sends the far view to Settings, Route", function()
    inGuild({ UIX.member("Rone", 1) }, function()
      local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true, card = true }))
      login(c); tick(c, 3)
      assert(c.env.CuteSetupFrame and c.env.CuteSetupFrame:IsShown(), "the card")
      click(UIX.row(c, "Map"))
      local FAR = "The minimap stays the game's, but for the far view (Settings, Route): wheel out past its widest, drag to look around"
      assert(UIX.text(c, FAR) and not texts(c):find("Route tab", 1, true), "unticked, the far view by where its switch is:\n" .. texts(c))
      check(c.env.CuteSetupFrame, "fix2-cute-ui V2 the card, Map unticked")
      click(UIX.row(c, "Map"))
      c.env.CuteSetupFrame:Hide()
      -- where the line sends you: Settings' Route section has the row; the Route tab has none
      c.C.UI:Open("settings", "route")
      assert(UIX.row(c, "Minimap far view"), "Settings, Route: the far view's row:\n" .. texts(c))
      c.C.UI.Window("settings").frame:Hide()
      c.C.UI:Open("quests", "route")
      assert(not texts(c):find("far view", 1, true), "the Route tab has no far view:\n" .. texts(c))
      leave(c)
    end)
    said[#said + 1] = "the card sends the far view to Settings, Route"
  end }

  CASES[#CASES + 1] = { "V3 Data you share counts the finds in the footers' words, never QuestBank", function()
    inGuild({ UIX.member("Rone", 1) }, function()
      local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true, log = { [7] = 2 } }))
      login(c); tickAll(6)
      c.C.Modules.Set("Cute_Quest:map", true); tick(c, 1)
      local QB = c.addons[2].private
      local disc = QB.Discover.DB()
      disc.find = { o9001 = { p = { { 1429, 400, 400, 1 } }, b = "A Diary of Your Own", n = 1 } }
      disc.findN = (tonumber(disc.findN) or 0) + 1
      c.C.UI:Open("settings", "share")
      local new, sure2 = c.C.Finds.Tally()
      local words = c.C.API.Finds.FooterText(new, sure2)
      local st = texts(c)
      assert(new == 1 and words:find("^1 new find") and st:find(words, 1, true), "the footers' words, \"" .. words .. "\":\n" .. st)
      assert(not st:find("QuestBank does not have", 1, true), "no QuestBank in the count:\n" .. st)
      local tip = tipOf(UIX.button(c, "Show finds"))
      assert(tip:find("what players' games and guides gave foreverrank.com", 1, true) and not tip:find("QuestBank", 1, true), "Show finds in the Map window's words:\n" .. tip)
      check(c.C.UI.Window("settings").frame, "fix2-cute-ui V3 Data you share, the finds line")
      leave(c)
    end)
    said[#said + 1] = "Data you share counts new finds as the footers do"
  end }

  CASES[#CASES + 1] = { "V4 the officer ranks stop at the guild's last rank; the guild master alone sees and sets", function()
    inGuild({ UIX.member("Gwen", 0), UIX.member("Rone", 1), UIX.member("Pim", 2) }, function()
      local names = { "Guild Master", "Officer", "Member" }
      local c = newClient(charOf({ "Gwen", 0, "Guild Master", "WARRIOR", 5 }, { rankNames = names }))
      c.env.GuildControlGetNumRanks = function() return #names end
      login(c); tickAll(60)
      local listed = false
      for _, n in ipairs(c.C.UNDOCUMENTED) do if n == "GuildControlGetNumRanks" then listed = true end end
      assert(listed, "/cute api reports GuildControlGetNumRanks")
      local P = c.C.Policy
      assert(P.Editable() and P:Threshold() == 1, "the guild master edits the officer ranks: " .. tostring(P:Threshold()))
      c.C.UI:Open("settings", "vis")
      local function step(label)
        for _, fr in ipairs(c.frames) do
          if fr.__kind == "Button" and fr:IsVisible() and fr.label and fr.label:GetText() == label and tipOf(fr):find("Officer ranks", 1, true) then return fr end
        end
      end
      press(step("+"))
      local t = texts(c)
      assert(P:Threshold() == 2 and t:find("Officer ranks: Guild Master to Member see every value and set this list", 1, true), "a step up to the last rank:\n" .. t)
      local plus = step("+")
      assert(plus and not plus:IsEnabled(), "the last rank: + is off")
      press(plus)
      t = texts(c)
      assert(P:Threshold() == 2 and not t:find("rank 4", 1, true) and not tipOf(plus):find("rank 4", 1, true), "no step past it, no made-up rank:\n" .. t)
      press(step("-")); press(step("-"))
      t = texts(c)
      assert(P:Threshold() == 0 and t:find("Officer ranks: Guild Master alone sees every value and sets this list", 1, true), "the guild master alone:\n" .. t)
      check(sframe(c), "fix2-cute-ui V4 Who sees what, the guild master alone")
      leave(c)
    end)
    said[#said + 1] = "the officer ranks stop at the guild's last; the guild master alone sees and sets"
  end }

  CASES[#CASES + 1] = { "V5 Settings > Modules' top line: the boxes on reload, the guild switches at once", function()
    inGuild({ UIX.member("Rone", 1) }, function()
      local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
      login(c); tickAll(6)
      c.C.UI:Open("settings", "modules")
      local t = texts(c)
      assert(UIX.row(c, "Achievements for the whole guild") and UIX.row(c, "Records for the whole guild"), "the guild switches are there:\n" .. t)
      assert(t:find("Module boxes apply on reload; the guild switches apply at once.", 1, true) and not t:find("Changes here apply on reload.", 1, true), "the top line says both:\n" .. t)
      check(sframe(c), "fix2-cute-ui V5 Settings > Modules, the top line")
      leave(c)
    end)
    said[#said + 1] = "Settings > Modules says the boxes reload and the guild switches apply at once"
  end }

  for _, case in ipairs(CASES) do
    local ok, err = pcall(case[2])
    if not ok then failed[#failed + 1] = case[1] .. ": " .. tostring(err) end
  end
  assert(#failed == 0, "fix2-cute-ui: " .. #failed .. " of " .. #CASES .. " failed:\n  " .. table.concat(failed, "\n  "))
  print("fix2-cute-ui: " .. table.concat(said, "; "))
end

-- [stage: fix2-engine] that stage's tests go right below this line
----------------------------------------------------------------------------
-- The final audit's engine findings, Cute's side (launch/fix2-engine), a case each; each failed on 0.9.1's files. Every
-- case runs, and the block fails at its end naming each one that did not hold
----------------------------------------------------------------------------
do
  local CASES, failed, said = {}, {}, {}
  local function member(name, rank) return { name = name .. "-Forever", guid = guidOf(name), rank = rank, rankName = rank <= 1 and "Officer" or "Raider", class = "WARRIOR", level = 5, online = true } end
  local function inGuild(guild, fn)
    local ok, err = true, nil
    isolated(guild, function() ok, err = pcall(fn) end)
    if not ok then error(err, 0) end
  end
  local function questChar()
    local c = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
    login(c); tickAll(5); tick(c, 6)
    return c
  end

  -- A1 (firsthour, must). The interact light's two rows were in Reminders' section alone, which goes while the module is
  -- off: a light left on had no switch anywhere in Cute's windows, though the card says Settings puts its settings back
  CASES[#CASES + 1] = { "A1 Reminders off: the interact light keeps a Settings section of its own", function()
    inGuild({ member("Rone", 1) }, function()
      local c = questChar()
      local QB, M, s = c.addons[2].private, c.C.Modules, c.env.CuteQuestDB.settings
      local function ids() local t = {}; for _, sec in ipairs(c.C.SettingsPage.Sections(true)) do t[#t + 1] = sec.id end return " " .. table.concat(t, " ") .. " " end
      M.Set("Cute_Quest:camp", true); tick(c, 1)
      local n = #c.C.SettingsPage.Sections(true)
      assert(ids():find(" camp ", 1, true) and not ids():find(" light ", 1, true), "Reminders on: the light's rows in its section, none of their own:" .. ids())
      M.Set("Cute_Quest:camp", false); tick(c, 1)
      assert(not ids():find(" camp ", 1, true) and ids():find(" light ", 1, true), "Reminders off: the light's own section:" .. ids())
      assert(#c.C.SettingsPage.Sections(true) == n, "one section in place of the other")
      QB.Glow.Set(true)
      c.C.UI:Open("settings", "light")
      local t = texts(c)
      assert(t:find("Interact light", 1, true) and t:find("Light style", 1, true), "the section's two rows:\n" .. t)
      local box = UIX.row(c, "Interact light")
      assert(box and box:GetChecked() and s.glow.on == true, "the light on: its row ticked")
      click(box)
      assert(s.glow.on == false, "its row unticked: the light off")
      click(UIX.row(c, "Game's"))
      assert(s.glow.style == "game", "its style chosen there: " .. tostring(s.glow.style))
      M.Set("Cute_Quest:camp", true); tick(c, 1)
      leave(c)
    end)
    said[#said + 1] = "the interact light has its own section while Reminders is off"
  end }

  -- F1 (robust, should). An older QuestBank beside Cute shared on RAID (before 6.3.0, no noRaidSync) and, before 6.1.0
  -- (no QuestBankAPI), on GUILD too, around the officers' Who sees what: its guild share is held off for the session, and
  -- before 6.3.0 its party share while you are in a raid, each put back at the logout
  CASES[#CASES + 1] = { "F1 an older QuestBank beside Cute: before 6.1.0 its guild share held off, before 6.3.0 its group share in a raid", function()
    inGuild({ member("Rone", 1) }, function()
      local function beside(version, withApi)
        local q = newClient(charOf({ "Rone", 1, "Officer", "WARRIOR", 5 }, { modules = { "Cute_Quest" }, addonState = {}, quest = true }))
        local isLoaded, meta = q.env.C_AddOns.IsAddOnLoaded, q.env.C_AddOns.GetAddOnMetadata
        q.env.C_AddOns.IsAddOnLoaded = function(x) if x == "QuestBank" then return true, true end return isLoaded(x) end
        q.env.C_AddOns.GetAddOnMetadata = function(x, field) if x == "QuestBank" then return field == "Version" and version or nil end return meta(x, field) end
        local raid = false
        q.env.IsInRaid = function() return raid end
        local settings = { guide = { on = true, frame = true }, arrow = true, glow = { on = true, style = "sparkle" }, remind = { on = true }, share = { party = true, guild = true }, djShow = { boss = true, rare = true, trash = false, other = true } }
        if withApi then
          q.env.QuestBankAPI = {
            version = version, logReady = true, state = { level = 5, log = {} }, routeNow = { legs = {}, xp = 0, level = 5, t = 0 },
            Settings = function() return settings end, MarkDirty = function() end, Comma = tostring, Short = tostring, Sync = {},
            Model = { Busy = function() return false end }, Data = { CAT = {} }, Quest = { Get = function() return nil end },
            Guide = { Steps = function() return {} end, Text = function(st) return st.text end, TimeToLevel = function() return nil end, MemberSteps = function() return {} end, Reminder = function() return nil end },
            StepFrame = { Menu = function() end, Apply = function() end, RemindChanged = function() end }, Arrow = { Set = function() end },
            UI = { PlaceGroups = function() return {}, {}, nil, nil, nil end, Candidates = function() return {} end, QuestClick = function() end, QuestTooltip = function() end },
            Target = { Route = function() return { legs = {}, xp = 0, level = 5, t = 0 } end }, Run = { Get = function() return nil end },
            DMap = { Attach = function() end, Refresh = function() end }, Gear = { Attach = function() end, Refresh = function() end, RefreshSoon = function() end },
            Remind = { Pull = function() return {}, false end },
          }
        else
          q.env.QuestBankAPI = nil
          q.env.QuestBankDB = { settings = settings }
        end
        login(q); tickAll(5)
        q.C.Modules.Set("Cute_Quest", true); tick(q, 6)
        assert(q.addons[2].private.dormant == true, version .. ": QuestBank loaded, the copy sleeps")
        return q, settings.share, function(on) raid = on; fire(q, "GROUP_ROSTER_UPDATE") end
      end
      -- 6.0.1: no QuestBankAPI, its settings in QuestBankDB
      local q, share, raid = beside("6.0.1", false)
      assert(share.guild == false and share.party == true, "6.0.1: its guild share off for the session, its group share on out of a raid")
      raid(true)
      assert(share.party == false, "6.0.1 in a raid: its group share off")
      raid(false)
      assert(share.party == true, "out of the raid: on again")
      raid(true)
      fire(q, "PLAYER_LOGOUT")
      assert(share.guild == true and share.party == true, "6.0.1: both put back at the logout")
      leave(q)
      -- 6.2.0: QuestBankAPI, no noRaidSync read
      q, share, raid = beside("6.2.0", true)
      assert(share.guild == false and share.party == true, "6.2.0: its guild share off (no GuildOn), its group share on")
      raid(true)
      assert(share.party == false, "6.2.0 in a raid: its group share off")
      fire(q, "PLAYER_LOGOUT")
      assert(share.guild == true and share.party == true, "6.2.0: both put back at the logout")
      leave(q)
      -- 6.3.0 reads noRaidSync: its group share left as it is
      q, share, raid = beside("6.3.0", true)
      raid(true)
      assert(share.party == true, "6.3.0 in a raid: its group share as it is (it reads noRaidSync)")
      leave(q)
    end)
    said[#said + 1] = "an older QuestBank's guild share held off before 6.1.0 as after, its group share in a raid before 6.3.0"
  end }

  -- I1 (look, should). Under Cute the minimap's menu named the far view "Far zoom" (Settings > Route says "Minimap far
  -- view"), split Route and Lines (Cute's one row, "Route on the minimap", reads both), and its last line opened
  -- Settings > Quests, which holds none of its switches
  CASES[#CASES + 1] = { "I1 the minimap's menu under Cute: Settings > Route's names and one route row; its settings line opens Route", function()
    inGuild({ member("Rone", 1) }, function()
      local c = questChar()
      local s, mini = c.env.CuteQuestDB.settings, c.env.Minimap
      c.C.Modules.Set("Cute_Quest:map", true); tick(c, 1)
      mini.__scripts.OnMouseUp(mini, "RightButton"); tick(c, 1)
      local byText, names = {}, {}
      for _, e in ipairs(c.contextMenus[#c.contextMenus]) do if e.text then byText[e.text] = e; names[#names + 1] = e.text end end
      local list = table.concat(names, ", ")
      assert(byText["Minimap far view"] and byText["Route on the minimap"], "Settings > Route's names: " .. list)
      assert(not byText["Far zoom"] and not byText["Route"] and not byText["Lines"], "none of QuestBank's: " .. list)
      local route = byText["Route on the minimap"]
      assert(route.get() == true, "the route on: ticked")
      route.set()
      assert(s.minimapPins == false and s.minimapLines == false and route.get() == false, "unticked: the route's pins and lines off, as Settings' row")
      route.set()
      assert(s.minimapPins ~= false and s.minimapLines ~= false, "ticked again: both on")
      byText["Cute settings"].set()
      local S = c.C.UI.Window("settings")
      assert(S.frame:IsShown() and S.section == "route", "its settings line: Settings > Route: " .. tostring(S.section))
      leave(c)
    end)
    said[#said + 1] = "the minimap's menu says Settings > Route's names and opens it"
  end }

  for _, case in ipairs(CASES) do
    local ok, err = pcall(case[2])
    if not ok then failed[#failed + 1] = case[1] .. ": " .. tostring(err) end
  end
  assert(#failed == 0, "fix2-engine: " .. #failed .. " of " .. #CASES .. " failed:\n  " .. table.concat(failed, "\n  "))
  print("fix2-engine: " .. table.concat(said, "; "))
end

-- [stage: merge5] that stage's tests go right below this line
----------------------------------------------------------------------------
-- The integration findings on launch/merge5, Cute's side, a case each; every case runs, and the block fails at its end
-- naming each one that did not hold:
-- R1. Officer ranks saved past the guild's last rank (0.9.1's + went to 9, and an officer still on it can save them) name
--     the ranks there are: no made-up "rank 7", a line saying every member sees every value, and - steps down from the
--     guild's last rank
----------------------------------------------------------------------------
do
  local CASES, failed, said = {}, {}, {}
  local function inGuild(guild, fn)
    local ok, err = true, nil
    isolated(guild, function() ok, err = pcall(fn) end)
    if not ok then error(err, 0) end
  end

  CASES[#CASES + 1] = { "R1 officer ranks saved past the guild's last rank name the ranks there are, and every member sees every value", function()
    inGuild({ UIX.member("Gwen", 0), UIX.member("Rone", 1), UIX.member("Pim", 2) }, function()
      local names = { "Guild Master", "Officer", "Member" }
      local c = newClient(charOf({ "Gwen", 0, "Guild Master", "WARRIOR", 5 }, { rankNames = names }))
      c.env.GuildControlGetNumRanks = function() return #names end
      login(c); tickAll(60)
      local P = c.C.Policy
      assert(P:SetThreshold(8) and P:Threshold() == 8, "a line saved by 0.9.1's stepper: 8: " .. tostring(P:Threshold()))
      c.C.UI:Open("settings", "vis")
      local function step(label)
        for _, fr in ipairs(c.frames) do
          if fr.__kind == "Button" and fr:IsVisible() and fr.label and fr.label:GetText() == label and tipOf(fr):find("Officer ranks", 1, true) then return fr end
        end
      end
      local t, tip = texts(c), tipOf(step("-"))
      assert(not t:find("rank %d") and not tip:find("rank %d"), "no made-up rank:\n" .. t .. "\n--\n" .. tip)
      assert(t:find("Officer ranks: Guild Master to Member see every value and set this list", 1, true), "the ranks there are, to the last:\n" .. t)
      assert(t:find("every member sees every value", 1, true), "said: every member sees every value:\n" .. t)
      assert(tip:find("Now 3 ranks: Guild Master, Officer, Member.", 1, true), "the tooltip counts the guild's ranks:\n" .. tip)
      local plus = step("+")
      assert(plus and not plus:IsEnabled(), "+ is off past the last rank")
      check(sframe(c), "merge5 R1 Who sees what, officer ranks saved past the last rank")
      press(step("-"))
      t = texts(c)
      assert(P:Threshold() == 1 and t:find("Officer ranks: Guild Master to Officer see every value and set this list", 1, true),
        "a step down from the guild's last rank: " .. tostring(P:Threshold()) .. "\n" .. t)
      assert(not t:find("every member sees every value", 1, true), "below the last rank, not said:\n" .. t)
      leave(c)
    end)
    said[#said + 1] = "officer ranks saved past the guild's last name the ranks there are and step down from the last"
  end }

  for _, case in ipairs(CASES) do
    local ok, err = pcall(case[2])
    if not ok then failed[#failed + 1] = case[1] .. ": " .. tostring(err) end
  end
  assert(#failed == 0, "merge5: " .. #failed .. " of " .. #CASES .. " failed:\n  " .. table.concat(failed, "\n  "))
  print("merge5: " .. table.concat(said, "; "))
end

-- this pass's problems and layouts join the run's; the last pass prints them all
for _, p in ipairs(problems) do table.insert(CUTE_RESULTS.problems, (SEEDED and "[seed] " or "[no seed] ") .. p) end
for _, l in ipairs(layouts) do l.label = (SEEDED and "seed: " or "no seed: ") .. l.label; table.insert(CUTE_RESULTS.layouts, l) end
if CUTE_LAST then
  local seen, unique = {}, {}
  for _, p in ipairs(CUTE_RESULTS.problems) do if not seen[p] then seen[p] = true; unique[#unique + 1] = p end end
  print("layout problems:", #unique)
  for i = 1, math.min(80, #unique) do print("  " .. unique[i]) end
  if LAYOUT_OUT then
    local f = assert(io.open(LAYOUT_OUT, "w"))
    f:write(json(CUTE_RESULTS.layouts))
    f:close()
    print("layout written to " .. LAYOUT_OUT)
  end
  print(#unique == 0 and "OK" or "OK, with layout problems above")
end
